import Foundation

public struct OfflineDailyVerse: Sendable, Equatable {
    public let surahNumber: Int
    public let ayahNumber: Int
    public let textAr: String
    public let meaningEn: String
    public let meaningTr: String
    public let meaningUr: String
    public let surahNameAr: String
    public let surahNameEn: String
}

public struct OfflineDailyHadith: Sendable, Equatable, Identifiable {
    public let id: String
    public let titleAr: String
    public let titleEn: String
    public let titleTr: String
    public let titleUr: String
    public let textAr: String
    public let translationEn: String
    public let translationTr: String
    public let translationUr: String
    public let narratorAr: String
    public let narratorEn: String
    public let referenceAr: String
    public let referenceEn: String
    public let categoryAr: String
    public let categoryEn: String
    public let explanationAr: String
    public let explanationEn: String
    public let explanationTr: String
    public let explanationUr: String

    public func localizedTitle(language: String) -> String {
        if language.hasPrefix("ar") { return titleAr }
        if language.hasPrefix("ur") { return titleUr.isEmpty ? titleEn : titleUr }
        if language.hasPrefix("tr") { return titleTr.isEmpty ? titleEn : titleTr }
        return titleEn
    }

    public func localizedTranslation(language: String) -> String? {
        if language.hasPrefix("ar") { return nil }
        if language.hasPrefix("ur") { return translationUr.isEmpty ? translationEn : translationUr }
        if language.hasPrefix("tr") { return translationTr.isEmpty ? translationEn : translationTr }
        return translationEn
    }

    public func localizedExplanation(language: String) -> String? {
        let pick: String
        if language.hasPrefix("ar") {
            pick = explanationAr
        } else if language.hasPrefix("ur") {
            pick = explanationUr.isEmpty ? explanationAr : explanationUr
        } else if language.hasPrefix("tr") {
            pick = !explanationTr.isEmpty ? explanationTr : (!explanationEn.isEmpty ? explanationEn : explanationAr)
        } else {
            pick = explanationEn.isEmpty ? explanationAr : explanationEn
        }
        return pick.isEmpty ? nil : pick
    }

    public func localizedCategory(language: String) -> String {
        if language.hasPrefix("ar") { return categoryAr }
        if language.hasPrefix("ur") { return DailyQuotesCatalog.urduCategories[categoryEn] ?? categoryAr }
        if language.hasPrefix("tr") { return DailyQuotesCatalog.turkishCategories[categoryEn] ?? categoryEn }
        return categoryEn
    }
}

