    public static let hadiths: [OfflineDailyHadith] = [
        OfflineDailyHadith(id: "1", titleAr: "الأعمال بالنيات", titleEn: "Actions are by Intentions", titleTr: "Ameller Niyetlere Göredir", titleUr: "اعمال کا دارومدار نیتوں پر ہے", textAr: "إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ، فَهِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ، وَمَنْ كَانَتْ هِجْرَتُهُ لِدُنْيَا يُصِيبُهَا أَوِ امْرَأَةٍ يَنْكِحُهَا، فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ.", translationEn: "Actions are according to intentions, and everyone will get what was intended. Whoever migrated for Allah and His Messenger, his migration is for Allah and His Messenger; and whoever migrated for worldly gain or to marry a woman, his migration is for that.", translationTr: "", translationUr: "", narratorAr: "عن أمير المؤمنين عمر بن الخطاب رضي الله عنه", narratorEn: "Narrated by Umar ibn al-Khattab (RA)", referenceAr: "صحيح البخاري وصحيح مسلم - الحديث الأول من الأربعين النووية", referenceEn: "Sahih al-Bukhari & Sahih Muslim - Hadith 1 of An-Nawawi", categoryAr: "الإيمان والنية", categoryEn: "Faith & Intention", explanationAr: "هذا الحديث أصل عظيم من أصول الدين وقاعدة تدور عليها جميع الأعمال، فالنية الصادقة شرط لقبول كل عبادة وقربة.", explanationEn: "A foundational principle of Islam: all deeds are evaluated by sincerity and the underlying intention.", explanationTr: "İslam'ın temel kurallarından biridir: Ameller ancak samimi niyetle kabul edilir.", explanationUr: "اسلام کا ایک بنیادی اصول کہ ہر عمل کا دارومدار اخلاص اور نیت پر ہے۔"),
        OfflineDailyHadith(id: "2", titleAr: "مراتب الدين: الإسلام والإيمان والإحسان", titleEn: "The Levels of Religion (Hadith Jibril)", titleTr: "Dinin Mertebeleri (Cibrîl Hadisi)", titleUr: "دین کے مراتب (حدیثِ جبریل)", textAr: "الإِسْلاَمُ أَنْ تَشْهَدَ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَتُقِيمَ الصَّلاَةَ، وَتُؤْتِيَ الزَّكَاةَ، وَتَصُومَ رَمَضَانَ، وَتَحُجَّ الْبَيْتَ إِنِ اسْتَطَعْتَ إِلَيْهِ سَبِيلاً. الإِيمَانُ أَنْ تُؤْمِنَ بِاللَّهِ، وَمَلاَئِكَتِهِ، وَكُتُبِهِ، وَرُسُلِهِ، وَالْيَوْمِ الآخِرِ، وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ. الإِحْسَانُ أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ.", translationEn: "Islam is to testify that there is no god but Allah and Muhammad is His messenger, establish prayer, give zakah, fast Ramadan, and perform pilgrimage if able. Iman is to believe in Allah, His angels, His books, His messengers, the Last Day, and destiny its good and evil. Ihsan is to worship Allah as though you see Him, for if you see Him not, He sees you.", translationTr: "", translationUr: "", narratorAr: "عن عمر بن الخطاب رضي الله عنه", narratorEn: "Narrated by Umar ibn al-Khattab (RA)", referenceAr: "صحيح مسلم - الحديث الثاني من الأربعين النووية", referenceEn: "Sahih Muslim - Hadith 2 of An-Nawawi", categoryAr: "الإيمان والنية", categoryEn: "Faith & Intention", explanationAr: "يُعرف هذا الحديث بأم السنة لاشتماله على جميع مراتب الدين الثلاث: ظاهر الإسلام، وباطن الإيمان، وغاية المراقبة في الإحسان.", explanationEn: "Encompasses the three levels of Islam: outward acts of devotion, inner faith, and the height of God-consciousness.", explanationTr: "Dinin üç temel mertebesini açıklar: İslam (zahiri ameller), İman (bâtıni inançlar) ve İhsan (sürekli Allah'ı görüyormuşçasına yaşamak).", explanationUr: "دین کے تینوں درجات کا احاطہ کرتا ہے: ظاہری اعمال (اسلام)، باطنی یقین (ایمان)، اور اعلیٰ ترین خشوع (احسان)۔"),
        OfflineDailyHadith(id: "3", titleAr: "بني الإسلام على خمس", titleEn: "Islam is Built Upon Five", titleTr: "İslam Beş Esas Üzerine Kurulmuştur", titleUr: "اسلام کی بنیاد پانچ چیزوں پر ہے", textAr: "بُنِيَ الإِسْلاَمُ عَلَى خَمْسٍ: شَهَادَةِ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامِ الصَّلاَةِ، وَإِيتَاءِ الزَّكَاةِ، وَحَجِّ الْبَيْتِ، وَصَوْمِ رَمَضَانَ.", translationEn: "Islam is built upon five: testifying that there is no god but Allah and that Muhammad is the Messenger of Allah, establishing the prayer, paying the zakah, performing Hajj to the House, and fasting Ramadan.", translationTr: "", translationUr: "", narratorAr: "عن عبد الله بن عمر رضي الله عنهما", narratorEn: "Narrated by Abdullah ibn Umar (RA)", referenceAr: "صحيح البخاري ومسلم - الحديث الثالث من الأربعين النووية", referenceEn: "Sahih al-Bukhari & Sahih Muslim - Hadith 3 of An-Nawawi", categoryAr: "الإيمان والنية", categoryEn: "Faith & Intention", explanationAr: "شبه النبي صلى الله عليه وسلم الإسلام بالبنيان المحكم، وأركانه الخمسة هي الأعمدة التي يقوم عليها.", explanationEn: "Metaphor of a sturdy building supported by its five structural pillars.", explanationTr: "İslam'ı sağlam bir binaya benzetir; beş şart onun ana sütunlarıdır.", explanationUr: "اسلام کو ایک عمارت سے تشبیہ دی گئی ہے جس کے یہ پانچ ستون ہیں۔"),
        OfflineDailyHadith(id: "4", titleAr: "النهي عن الابتداع في الدين", titleEn: "Rejection of Innovations", titleTr: "Bidatlerin Reddi", titleUr: "بدعات کا رد", textAr: "مَنْ أَحْدَثَ فِي أَمْرِنَا هَذَا مَا لَيْسَ فِيهِ فَهُوَ رَدٌّ.", translationEn: "Whoever innovates something in this matter of ours (religion) that is not part of it, will have it rejected.", translationTr: "", translationUr: "", narratorAr: "عن أم المؤمنين عائشة رضي الله عنها", narratorEn: "Narrated by Aisha (RA)", referenceAr: "صحيح البخاري ومسلم - الحديث الخامس من الأربعين النووية", referenceEn: "Sahih al-Bukhari & Sahih Muslim - Hadith 5 of An-Nawawi", categoryAr: "اتباع السنة", categoryEn: "Following the Sunnah", explanationAr: "ميزان الأعمال الظاهرة، فكما أن حديث النيات ميزان الباطن، فهذا الحديث ميزان مطابقة العمل لشرع الله وسنة نبيه.", explanationEn: "The benchmark for external actions: any deed not adhering to the Quran and authentic Sunnah is rejected.", explanationTr: "Zahiri amellerin miyarıdır; sünnete uymayan bidatler merduttur.", explanationUr: "ظاہری اعمال کا معیار کہ جو عمل شریعت اور سنت کے مطابق نہ ہو وہ مردود ہے۔"),
        OfflineDailyHadith(id: "5", titleAr: "الحلال بين والحرام بين", titleEn: "The Halal is Clear and Haram is Clear", titleTr: "Helal Bellidir, Haram Bellidir", titleUr: "حلال واضح ہے اور حرام واضح ہے", textAr: "إِنَّ الْحَلاَلَ بَيِّنٌ وَإِنَّ الْحَرَامَ بَيِّنٌ وَبَيْنَهُمَا مُشْتَبِهَاتٌ لاَ يَعْلَمُهُنَّ كَثِيرٌ مِنَ النَّاسِ، فَمَنِ اتَّقَى الشُّبُهَاتِ اسْتَبْرَأَ لِدِينِهِ وَعِرْضِهِ، وَمَنْ وَقَعَ فِي الشُّبُهَاتِ وَقَعَ فِي الْحَرَامِ، كَالرَّاعِي يَرْعَى حَوْلَ الْحِمَى يُوشِكُ أَنْ يَرْتَعَ فِيهِ، أَلاَ وَإِنَّ لِكُلِّ مَلِكٍ حِمًى، أَلاَ وَإِنَّ حِمَى اللَّهِ مَحَارِمُهُ، أَلاَ وَإِنَّ فِي الْجَسَدِ مُضْغَةً إِذَا صَلَحَتْ صَلَحَ الْجَسَدُ كُلُّهُ وَإِذَا فَسَدَتْ فَسَدَ الْجَسَدُ كُلُّهُ أَلاَ وَهِيَ الْقَلْبُ.", translationEn: "That which is lawful is clear and that which is unlawful is clear, and between the two of them are doubtful matters about which many people do not know. Thus he who avoids doubtful matters clears himself in regard to his religion and his honor, but he who falls into doubtful matters falls into that which is unlawful, like the shepherd who pastures around a sanctuary, all but grazing therein. Truly every king has a sanctuary, and truly Allah's sanctuary is His prohibitions. Truly, in the body there is a morsel of flesh which, if it be whole, all the body is whole and which, if it be diseased, all of it is diseased. Truly, it is the heart.", translationTr: "", translationUr: "", narratorAr: "عن النعمان بن بشير رضي الله عنه", narratorEn: "Narrated by An-Nu'man ibn Bashir (RA)", referenceAr: "صحيح البخاري ومسلم - الحديث السادس من الأربعين النووية", referenceEn: "Sahih al-Bukhari & Sahih Muslim - Hadith 6 of An-Nawawi", categoryAr: "اتباع السنة", categoryEn: "Following the Sunnah", explanationAr: "قاعدة الورع وصلاح القلوب، فالابتعاد عن الشبهات صيانة لدين المسلم وسلامة لقلبه.", explanationEn: "The golden rule of pious precaution and heart purification: steering clear of ambiguity preserves faith and integrity.", explanationTr: "Şüpheli şeylerden kaçınmanın din ve namus emniyeti olduğunu ve kalbin ıslahının önemini anlatır.", explanationUr: "تقویٰ اور صفائی قلب کا اصول، مشتبہ چیزوں سے بچنا دین اور عزت کی حفاظت کا باعث ہے۔"),
        OfflineDailyHadith(id: "6", titleAr: "الدين النصيحة", titleEn: "The Religion is Sincerity", titleTr: "Din Nasihattir", titleUr: "دین خیرخواہی کا نام ہے", textAr: "الدِّينُ النَّصِيحَةُ. قُلْنَا: لِمَنْ؟ قَالَ: لِلَّهِ، وَلِكِتَابِهِ، وَلِرَسُولِهِ، وَلأَئِمَّةِ الْمُسْلِمِينَ، وَعَامَّتِهِمْ.", translationEn: "The religion is sincerity. We said: To whom? He said: To Allah, His Book, His Messenger, and to the leaders of the Muslims and their common folk.", translationTr: "", translationUr: "", narratorAr: "عن تميم الداري رضي الله عنه", narratorEn: "Narrated by Tamim ad-Dari (RA)", referenceAr: "صحيح مسلم - الحديث السابع من الأربعين النووية", referenceEn: "Sahih Muslim - Hadith 7 of An-Nawawi", categoryAr: "حسن الخلق", categoryEn: "Good Character", explanationAr: "النصيحة كلمة جامعة تعني إرادة الخير للمنصوح له والقيام بحقوقه بإخلاص وأمانة.", explanationEn: "Defines sincere goodwill and fulfilling duties toward Allah, His revelation, leaders, and fellow humanity.", explanationTr: "Dinin özünün samimiyet ve herkesin hayrını istemek olduğunu beyan eder.", explanationUr: "دین کی اصل خیر خواہی، سچائی اور اخلاص ہے۔"),
        OfflineDailyHadith(id: "7", titleAr: "من حسن إسلام المرء", titleEn: "Leaving What Does Not Concern You", titleTr: "Kendini İlgilendirmeyeni Terk Etmek", titleUr: "لایعنی کو ترک کرنا", textAr: "مِنْ حُسْنِ إِسْلاَمِ الْمَرْءِ تَرْكُهُ مَا لاَ يَعْنِيهِ.", translationEn: "Part of the perfection of one's Islam is his leaving that which does not concern him.", translationTr: "", translationUr: "", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "سنن الترمذي وابن ماجه (حسن) - الحديث الثاني عشر من الأربعين النووية", referenceEn: "Sunan at-Tirmidhi & Sunan Ibn Majah (Hasan) - Hadith 12 of An-Nawawi", categoryAr: "حسن الخلق", categoryEn: "Good Character", explanationAr: "حفظ الوقت واللسان والجوارح عما لا فائدة فيه في دين أو دنيا، وهو عنوان سلامة الصدر ورجاحة العقل.", explanationEn: "Advises investing time and energy into beneficial pursuits while abandoning meddling in trivia.", explanationTr: "Kişinin kendisini ilgilendirmeyen boş şeyleri terk etmesi kemal-i imanındandır.", explanationUr: "بے مقصد اور غیر متعلقہ باتوں اور کاموں کو چھوڑ دینا اعلیٰ اخلاق کی علامت ہے۔"),
        OfflineDailyHadith(id: "8", titleAr: "حب الخير للمؤمنين", titleEn: "Loving for Others What You Love for Yourself", titleTr: "Kendin İçin İstediğini Kardeşin İçin de İstemek", titleUr: "اپنے لیے جو پسند کرو وہی دوسروں کے لیے پسند کرو", textAr: "لاَ يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ.", translationEn: "None of you truly believes until he loves for his brother what he loves for himself.", translationTr: "", translationUr: "", narratorAr: "عن أنس بن مالك رضي الله عنه", narratorEn: "Narrated by Anas ibn Malik (RA)", referenceAr: "صحيح البخاري ومسلم - الحديث الثالث عشر من الأربعين النووية", referenceEn: "Sahih al-Bukhari & Sahih Muslim - Hadith 13 of An-Nawawi", categoryAr: "الجار والمجتمع", categoryEn: "Neighbours & Society", explanationAr: "كمال الإيمان يقتضي سلامة القلب من الغل والحسد، وتمني الخير والنفع لكل مسلم كما يتمناه لنفسه.", explanationEn: "True faith demands eradicating malice and genuinely wishing goodness, guidance, and prosperity for others.", explanationTr: "Kişi kendisi için istediğini din kardeşi için de istemedikçe kamil mümin olamaz.", explanationUr: "کامل ایمان کی علامت یہ ہے کہ انسان اپنے بھائی کے لیے وہی پسند کرے جو اپنے لیے پسند کرتا ہے۔"),
        OfflineDailyHadith(id: "9", titleAr: "حرمة دم المسلم وماله وعرضه", titleEn: "Sanctity of Muslim Blood, Wealth & Honor", titleTr: "Müslümanın Kanı, Malı ve Onuru Haramdır", titleUr: "مسلمان کا خون، مال اور عزت محترم ہے", textAr: "كُلُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ حَرَامٌ: دَمُهُ، وَمَالُهُ، وَعِرْضُهُ.", translationEn: "All of a Muslim is sacred to another Muslim: his blood, his wealth, and his honor.", translationTr: "", translationUr: "", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "صحيح مسلم - الحديث الخامس والثلاثون من الأربعين النووية", referenceEn: "Sahih Muslim - Hadith 35 of An-Nawawi", categoryAr: "الجار والمجتمع", categoryEn: "Neighbours & Society", explanationAr: "حرمة المسلم أعظم عند الله من حرمة الكعبة، والاعتداء عليه بالقول أو الفعل من كبائر الذنوب.", explanationEn: "Proclaims the absolute sanctity of human life, dignity, property, and personal honor in Islamic ethics.", explanationTr: "Müslümanın canı, malı ve ırzı diğer müslümana kesin olarak haramdır.", explanationUr: "مسلمان کی جان، مال اور عزت دوسرے مسلمان کے لیے قطعی طور پر محترم ہے۔"),
        OfflineDailyHadith(id: "10", titleAr: "النهي عن الغضب", titleEn: "Do Not Become Angry", titleTr: "Öfkelenme", titleUr: "غصہ نہ کرو", textAr: "أَنَّ رَجُلاً قَالَ لِلنَّبِيِّ صلى الله عليه وسلم: أَوْصِنِي. قَالَ: «لاَ تَغْضَبْ». فَرَدَّدَ مِرَارًا، قَالَ: «لاَ تَغْضَبْ».", translationEn: "A man said to the Prophet (PBUH): Advise me. He said: Do not become angry. The man repeated his request several times, and he said: Do not become angry.", translationTr: "", translationUr: "", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "صحيح البخاري - الحديث السادس عشر من الأربعين النووية", referenceEn: "Sahih al-Bukhari - Hadith 16 of An-Nawawi", categoryAr: "حسن الخلق", categoryEn: "Good Character", explanationAr: "الغضب جماع الشر، واجتنابه ومجاهدة النفس عند ثورانه مفتاح كل خير وبر وسلامة.", explanationEn: "Self-restraint in moments of fury prevents destruction and opens the doors of wisdom and mercy.", explanationTr: "Öfkeyi yenmek her türlü kötülüğün önüne geçen büyük bir ahlaki meziyettir.", explanationUr: "غصے پر قابو پانا تمام برائیوں کی جڑ کو ختم کرنے کا نبوی نسخہ ہے۔"),
        OfflineDailyHadith(id: "11", titleAr: "إحسان كل شيء والرفق بالحيوان", titleEn: "Excellence in Everything", titleTr: "Her Şeyde İhsan", titleUr: "ہر کام میں احسان", textAr: "إِنَّ اللَّهَ كَتَبَ الإِحْسَانَ عَلَى كُلِّ شَيْءٍ، فَإِذَا قَتَلْتُمْ فَأَحْسِنُوا الْقِتْلَةَ، وَإِذَا ذَبَحْتُمْ فَأَحْسِنُوا الذَّبْحَ، وَلْيُحِدَّ أَحَدُكُمْ شَفْرَتَهُ، وَلْيُرِحْ ذَبِيحَتَهُ.", translationEn: "Verily Allah has prescribed proficiency and kindness in all things. So if you kill, kill well; and if you slaughter, slaughter well. Let each one of you sharpen his blade and let him spare pain to the animal he slaughters.", translationTr: "", translationUr: "", narratorAr: "عن شداد بن أوس رضي الله عنه", narratorEn: "Narrated by Shaddad ibn Aws (RA)", referenceAr: "صحيح مسلم - الحديث السابع عشر من الأربعين النووية", referenceEn: "Sahih Muslim - Hadith 17 of An-Nawawi", categoryAr: "الرحمة والرفق", categoryEn: "Mercy & Gentleness", explanationAr: "الإسلام دين الرحمة الشاملة والإتقان في كل عمل حتى في موضع الذبح وإراحة الحيوان.", explanationEn: "Manifests Islamic mercy and professional excellence across every single domain of life.", explanationTr: "İslam her işte mükemmellik ve canlılara karşı azami merhameti emreder.", explanationUr: "اسلام ہر معاملے میں احسان، حسن عمل اور شفقت کی تلقین کرتا ہے۔"),
        OfflineDailyHadith(id: "12", titleAr: "الوصية بحفظ الله والتوكل عليه", titleEn: "Mindfulness of Allah & Reliance", titleTr: "Allah'ı Gözetmek ve O'na Tevekkül", titleUr: "اللہ کی حفاظت اور اسی پر توکل", textAr: "يَا غُلاَمُ إِنِّي أُعَلِّمُكَ كَلِمَاتٍ: احْفَظِ اللَّهَ يَحْفَظْكَ، احْفَظِ اللَّهَ تَجِدْهُ تُجَاهَكَ، إِذَا سَأَلْتَ فَاسْأَلِ اللَّهَ، وَإِذَا اسْتَعَنْتَ فَاسْتَعِنْ بِاللَّهِ، وَاعْلَمْ أَنَّ الأُمَّةَ لَوِ اجْتَمَعَتْ عَلَى أَنْ يَنْفَعُوكَ بِشَيْءٍ لَمْ يَنْفَعُوكَ إِلاَّ بِشَيْءٍ قَدْ كَتَبَهُ اللَّهُ لَكَ، وَلَوِ اجْتَمَعُوا عَلَى أَنْ يَضُرُّوكَ بِشَيْءٍ لَمْ يَضُرُّوكَ إِلاَّ بِشَيْءٍ قَدْ كَتَبَهُ اللَّهُ عَلَيْكَ، رُفِعَتِ الأَقْلاَمُ وَجَفَّتِ الصُّحُفُ.", translationEn: "Young man, I shall teach you some words: Be mindful of Allah and He will protect you. Be mindful of Allah and you will find Him before you. If you ask, ask of Allah; if you seek help, seek help of Allah. Know that if the nation gathered to benefit you, they would not benefit you except with what Allah has decreed for you; and if they gathered to harm you, they would not harm you except with what Allah has decreed against you. The pens have been lifted and the pages have dried.", translationTr: "", translationUr: "", narratorAr: "عن عبد الله بن عباس رضي الله عنهما", narratorEn: "Narrated by Abdullah ibn Abbas (RA)", referenceAr: "سنن الترمذي - الحديث التاسع عشر من الأربعين النووية (صحيح)", referenceEn: "Sunan at-Tirmidhi - Hadith 19 of An-Nawawi", categoryAr: "الإيمان والنية", categoryEn: "Faith & Intention", explanationAr: "وصية نبوية جامعة ترسى في القلب التوحيد الخالص، واليقين بالقضاء والقدر، والتوكل على الله وحده.", explanationEn: "Masterful instruction cultivating sincere reliance upon Allah and certainty in divine decree.", explanationTr: "Allah'ın emirlerini koruyanın Allah tarafından korunacağını ve tevekkülün önemini anlatan kapsamlı tavsiye.", explanationUr: "اللہ کی اطاعت، توکل اور تقدیر پر غیر متزلزل یقین کی نبوی وصیت۔"),
        OfflineDailyHadith(id: "13", titleAr: "الاستقامة على دين الله", titleEn: "Steadfastness in Faith", titleTr: "İmanda Sebat", titleUr: "ایمان پر استقامت", textAr: "قُلْتُ: يَا رَسُولَ اللَّهِ قُلْ لِي فِي الإِسْلاَمِ قَوْلاً لاَ أَسْأَلُ عَنْهُ أَحَدًا غَيْرَكَ. قَالَ: «قُلْ آمَنْتُ بِاللَّهِ ثُمَّ اسْتَقِمْ».", translationEn: "I said: O Messenger of Allah, tell me something about Islam which I can ask of no one but you. He said: Say: I believe in Allah, and then be steadfast.", translationTr: "", translationUr: "", narratorAr: "عن سفيان بن عبد الله الثقفي رضي الله عنه", narratorEn: "Narrated by Sufyan ibn Abdullah (RA)", referenceAr: "صحيح مسلم - الحديث الحادي والعشرون من الأربعين النووية", referenceEn: "Sahih Muslim - Hadith 21 of An-Nawawi", categoryAr: "الإيمان والنية", categoryEn: "Faith & Intention", explanationAr: "جمع النبي صلى الله عليه وسلم في كلمتين أصول الإيمان الظاهر والباطن، والثبات على طاعة الله حتى الممات.", explanationEn: "Concise wisdom condensing faith into sincere belief followed by lifelong perseverance.", explanationTr: "İman etmek ve ardından dosdoğru istikamet üzere yaşamak dinin özüdür.", explanationUr: "ایمان لانا اور پھر اس پر ثابت قدم رہنا دین کا خلاصہ ہے۔"),
        OfflineDailyHadith(id: "14", titleAr: "فضل تفريج الكرب والتماس العلم والذكر", titleEn: "Relieving Hardships & Seeking Knowledge", titleTr: "Sıkıntıları Gidermek ve İlim Talebi", titleUr: "مشکلات دور کرنا اور طلبِ علم", textAr: "مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللَّهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ، وَمَنْ يَسَّرَ عَلَى مُعْسِرٍ يَسَّرَ اللَّهُ عَلَيْهِ فِي الدُّنْيَا وَالآخِرَةِ، وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللَّهُ فِي الدُّنْيَا وَالآخِرَةِ، وَاللَّهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ، وَمَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا سَهَّلَ اللَّهُ لَهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ، وَمَا اجْتَمَعَ قَوْمٌ فِي بَيْتٍ مِنْ بُيُوتِ اللَّهِ يَتْلُونَ كِتَابَ اللَّهِ وَيَتَدَارَسُونَهُ بَيْنَهُمْ إِلاَّ نَزَلَتْ عَلَيْهِمُ السَّكِينَةُ، وَغَشِيَتْهُمُ الرَّحْمَةُ، وَحَفَّتْهُمُ الْمَلاَئِكَةُ، وَذَكَرَهُمُ اللَّهُ فِيمَنْ عِنْدَهُ، وَمَنْ بَطَّأَ بِهِ عَمَلُهُ لَمْ يُسْرِعْ بِهِ نَسَبُهُ.", translationEn: "Whoever relieves a believer's distress in this world, Allah will relieve his distress on the Day of Resurrection. Whoever eases the hardship of an insolvent debtor, Allah will ease his hardship in this world and the Hereafter. Whoever conceals the faults of a Muslim, Allah will conceal his faults in this world and the Hereafter. Allah helps His servant as long as the servant helps his brother. Whoever travels a path seeking knowledge, Allah makes easy for him a path to Paradise. No people gather in one of the houses of Allah, reciting the Book of Allah and studying it among themselves, but tranquility descends upon them, mercy covers them, the angels surround them, and Allah mentions them among those who are with Him. And whoever is held back by his deeds will not be hastened forward by his lineage.", translationTr: "", translationUr: "", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "صحيح مسلم - الحديث السادس والثلاثون من الأربعين النووية", referenceEn: "Sahih Muslim - Hadith 36 of An-Nawawi", categoryAr: "العلم", categoryEn: "Knowledge", explanationAr: "حديث عظيم في فضل قضاء حوائج الناس، والتفريج عن المكروبين، وطلب العلم الشرعي، ومجالس الذكر.", explanationEn: "Glorious incentive for helping neighbors, easing distress, seeking knowledge, and gathering in remembrance of Allah.", explanationTr: "Kardeşinin yardımında olanın Allah da yardımında olur; ilim yolu cennet yoludur.", explanationUr: "لوگوں کی مدد کرنا، پریشانیاں دور کرنا اور علم حاصل کرنا قرب خداوندی کا راستہ ہے۔"),
        OfflineDailyHadith(id: "15", titleAr: "فضل التقرب إلى الله بالنوافل", titleEn: "Attaining Proximity to Allah (Hadith Qudsi)", titleTr: "Allah'a Yakınlık (Kudsî Hadis)", titleUr: "اللہ کا قرب (حدیثِ قدسی)", textAr: "إِنَّ اللَّهَ قَالَ: مَنْ عَادَى لِي وَلِيًّا فَقَدْ آذَنْتُهُ بِالْحَرْبِ، وَمَا تَقَرَّبَ إِلَيَّ عَبْدِي بِشَيْءٍ أَحَبَّ إِلَيَّ مِمَّا افْتَرَضْتُ عَلَيْهِ، وَمَا يَزَالُ عَبْدِي يَتَقَرَّبُ إِلَيَّ بِالنَّوَافِلِ حَتَّى أُحِبَّهُ، فَإِذَا أَحْبَبْتُهُ كُنْتُ سَمْعَهُ الَّذِي يَسْمَعُ بِهِ، وَبَصَرَهُ الَّذِي يُبْصِرُ بِهِ، وَيَدَهُ الَّتِي يَبْطِشُ بِهَا، وَرِجْلَهُ الَّتِي يَمْشِي بِهَا، وَإِنْ سَأَلَنِي لأُعْطِيَنَّهُ، وَلَئِنِ اسْتَعَاذَنِي لأُعِيذَنَّهُ.", translationEn: "Allah said: Whoever shows enmity to a pious worshipper of Mine, I declare war on him. My servant draws not near to Me with anything more loved by Me than what I have enjoined upon him, and My servant continues to draw near to Me with voluntary works so that I shall love him. When I love him, I become his hearing with which he hears, his seeing with which he sees, his hand with which he strikes, and his foot with which he walks. Were he to ask of Me, I would surely give it to him; and were he to ask Me for refuge, I would surely grant it.", translationTr: "", translationUr: "", narratorAr: "عن أبي هريرة رضي الله عنه (حديث قدسي)", narratorEn: "Narrated by Abu Hurairah (RA) - Hadith Qudsi", referenceAr: "صحيح البخاري - الحديث الثامن والثلاثون من الأربعين النووية", referenceEn: "Sahih al-Bukhari - Hadith 38 of An-Nawawi", categoryAr: "الإيمان والنية", categoryEn: "Faith & Intention", explanationAr: "أشرف حديث في بيان منزلة أولياء الله الصالحين، وفضل المحافظة على الفرائض والإكثار من النوافل.", explanationEn: "Delineates how performing obligatory deeds followed by voluntary acts earns Allah's direct divine love and protection.", explanationTr: "Farz ibadetlerden sonra nafilelerle Allah'a yaklaşmanın ve O'nun sevgisine mazhar olmanın yüceliği.", explanationUr: "فرائض کی پابندی اور نوافل کے ذریعے اللہ کا محبوب بندہ بننے کی فضیلت۔"),
        OfflineDailyHadith(id: "16", titleAr: "فضل الذكر ومثل الذاكر والغافل", titleEn: "The Virtue of Remembering Allah", titleTr: "Allah'ı Zikretmenin Fazileti", titleUr: "ذکرِ الٰہی کی فضیلت", textAr: "مَثَلُ الَّذِي يَذْكُرُ رَبَّهُ وَالَّذِي لاَ يَذْكُرُ رَبَّهُ مَثَلُ الْحَيِّ وَالْمَيِّتِ.", translationEn: "The example of the one who remembers his Lord in comparison to the one who does not remember his Lord is that of the living and the dead.", translationTr: "", translationUr: "", narratorAr: "عن أبي موسى الأشعري رضي الله عنه", narratorEn: "Narrated by Abu Musa Al-Ash'ari (RA)", referenceAr: "صحيح البخاري ومسلم - باب فضل الذكر", referenceEn: "Sahih al-Bukhari & Sahih Muslim", categoryAr: "الذكر", categoryEn: "Remembrance", explanationAr: "الذكر حياة القلوب والأرواح، فالغافل عن ذكر الله ميت وإن كان يمشي بين الأحياء، والذاكر حي القلب بنور ربه.", explanationEn: "Remembering Allah infuses true life into hearts; abandoning remembrance results in spiritual death despite physical vitality.", explanationTr: "Allah'ı zikretmek kalplerin hayatıdır; zikirden gafil olan manen ölü gibidir.", explanationUr: "اللہ کا ذکر دلوں کی زندگی ہے، اور ذکر سے غافل شخص روحانی طور پر مردہ کے مانند ہے۔"),
        OfflineDailyHadith(id: "17", titleAr: "أفضل الذكر وأفضل الدعاء", titleEn: "The Best Dhikr and Best Supplication", titleTr: "En Faziletli Zikir ve Dua", titleUr: "افضل ذکر اور افضل دعا", textAr: "أَفْضَلُ الذِّكْرِ: لاَ إِلَهَ إِلاَّ اللَّهُ، وَأَفْضَلُ الدُّعَاءِ: الْحَمْدُ لِلَّهِ.", translationEn: "The best dhikr is 'La ilaha illa Allah' (There is no god but Allah), and the best supplication is 'Alhamdulillah' (Praise be to Allah).", translationTr: "", translationUr: "", narratorAr: "عن جابر بن عبد الله رضي الله عنهما", narratorEn: "Narrated by Jabir ibn Abdullah (RA)", referenceAr: "جامع الترمذي وسنن ابن ماجه (حسن)", referenceEn: "Jami at-Tirmidhi & Sunan Ibn Majah (Hasan)", categoryAr: "الذكر", categoryEn: "Remembrance", explanationAr: "كلمة التوحيد أعظم كلمة قالها النبيون، والحمد اعتراف بالنعمة وثناء على المنعم سبحانه.", explanationEn: "The proclamation of Tawhid is the greatest statement uttered, while praising Allah is the pinnacle of gratitude and prayer.", explanationTr: "Tevhid kelimesi imanın esasıdır; elhamdülillah demek ise şükrün zirvesidir.", explanationUr: "کلمہ توحید ایمان کی بنیاد ہے اور الحمد للہ کہنا شکر کا اعلیٰ ترین درجہ ہے۔"),
        OfflineDailyHadith(id: "18", titleAr: "كلمتان خفيفتان على اللسان ثقيلتان في الميزان", titleEn: "Two Words Beloved to the Most Merciful", titleTr: "Rahmân'a Sevimli İki Kelime", titleUr: "رحمٰن کو محبوب دو کلمے", textAr: "كَلِمَتَانِ خَفِيفَتَانِ عَلَى اللِّسَانِ، ثَقِيلَتَانِ فِي الْمِيزَانِ، حَبِيبَتَانِ إِلَى الرَّحْمَنِ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ.", translationEn: "Two words are light on the tongue, heavy on the Scale, and beloved to the Most Merciful: 'Subhan Allahi wa bihamdihi, Subhan Allahil-'Azeem' (Glory be to Allah and His praise, Glory be to Allah the Magnificent).", translationTr: "", translationUr: "", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "صحيح البخاري ومسلم - خاتمة صحيح البخاري", referenceEn: "Sahih al-Bukhari & Sahih Muslim", categoryAr: "الذكر", categoryEn: "Remembrance", explanationAr: "من رحمة الله الواسعة بعباده أن جعل هذا الذكر اليسير في النطق يثقل موازين الحسنات يوم القيامة.", explanationEn: "Demonstrates Allah's boundless grace where lightweight words carry immense weight on the Scales of Eternity.", explanationTr: "Dilde hafif fakat mizanda çok ağır olan ve Rahman'ın en sevdiği mübarek iki kelimedir.", explanationUr: "زبان پر آسان لیکن میزان میں انتہائی بھاری اور رحمن کو محبوب کلمات ہیں۔"),
        OfflineDailyHadith(id: "19", titleAr: "سيد الاستغفار وفضله العظيم", titleEn: "The Master Supplication for Forgiveness (Sayyid al-Istighfar)", titleTr: "İstiğfarın Efendisi (Seyyidü'l-İstiğfâr)", titleUr: "سیدالاستغفار", textAr: "اللَّهُمَّ أَنْتَ رَبِّي لاَ إِلَهَ إِلاَّ أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ لَكَ بِذَنْبِي فَاغْفِرْ لِي، فَإِنَّهُ لاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ.", translationEn: "O Allah, You are my Lord, none has the right to be worshipped but You. You created me and I am Your servant, and I abide by Your covenant and promise as best I can. I seek refuge in You from the evil of what I have done. I acknowledge Your favors upon me and I acknowledge my sin, so forgive me, for none forgives sins except You.", translationTr: "", translationUr: "", narratorAr: "عن شداد بن أوس رضي الله عنه", narratorEn: "Narrated by Shaddad ibn Aws (RA)", referenceAr: "صحيح البخاري - أذكار الصباح والمساء", referenceEn: "Sahih al-Bukhari - Morning & Evening Dhikr", categoryAr: "الدعاء", categoryEn: "Supplication", explanationAr: "جامع للاعتراف بالربوبية والعبودية والنعمة والتقصير، ومن قاله موقناً به فمات في يومه أو ليلته دخل الجنة.", explanationEn: "Harmonizes acknowledgment of divine lordship, human servitude, gratitude for blessings, and contrite repentance.", explanationTr: "Tevbe ve istiğfarın şahıdır; ihlasla sabah ve akşam okuyan cennet ehlinden olur.", explanationUr: "استغفار کا سردار ہے، جو خلوص دل سے صبح یا شام پڑھے وہ اہل جنت میں سے ہے۔"),
        OfflineDailyHadith(id: "20", titleAr: "كنز من كنوز الجنة: لا حول ولا قوة إلا بالله", titleEn: "A Treasure from the Treasures of Paradise", titleTr: "Cennet Hazinelerinden Bir Hazine", titleUr: "جنت کے خزانوں میں سے ایک خزانہ", textAr: "أَلاَ أَدُلُّكَ عَلَى كَلِمَةٍ هِيَ كَنْزٌ مِنْ كُنُوزِ الْجَنَّةِ؟ لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ.", translationEn: "Shall I not guide you to a word which is a treasure from the treasures of Paradise? 'La hawla wa la quwwata illa billah' (There is no power nor might except with Allah).", translationTr: "", translationUr: "", narratorAr: "عن أبي موسى الأشعري رضي الله عنه", narratorEn: "Narrated by Abu Musa Al-Ash'ari (RA)", referenceAr: "صحيح البخاري ومسلم", referenceEn: "Sahih al-Bukhari & Sahih Muslim", categoryAr: "الذكر", categoryEn: "Remembrance", explanationAr: "التبرؤ من الحول والقوة وتفويض الأمر كله لله القوي العزيز، وهي ذخر عظيم لصاحبها في الجنة.", explanationEn: "Acknowledges that all ability and transformation belong exclusively to Allah, storing perpetual treasures in Paradise.", explanationTr: "İnsanın kendi güç ve kuvvetinden sıyrılıp her şeyi Allah'a havale etmesidir; cennet hazinelerindendir.", explanationUr: "اپنی بے بسی کا اعتراف اور ہر معاملے کو اللہ کے سپرد کرنا، جنت کے خزانوں میں سے ایک خزانہ ہے۔"),
        OfflineDailyHadith(id: "21", titleAr: "دعاء ذي النون لتفريج الكرب", titleEn: "Supplication of Prophet Yunus (Dhun-Nun) in Distress", titleTr: "Sıkıntı Anında Yunus (a.s.) Duası", titleUr: "حضرت یونس علیہ السلام کی دعا بوقتِ تنگی", textAr: "دَعْوَةُ ذِي النُّونِ إِذْ دَعَا وَهُوَ فِي بَطْنِ الْحُوتِ: لاَ إِلَهَ إِلاَّ أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ؛ فَإِنَّهُ لَمْ يَدْعُ بِهَا رَجُلٌ مُسْلِمٌ فِي شَيْءٍ قَطُّ إِلاَّ اسْتَجَابَ اللَّهُ لَهُ.", translationEn: "The supplication of Dhun-Nun when he called upon Allah inside the belly of the whale: 'La ilaha illa Anta, Subhanaka inni kuntu minaz-zalimeen' (There is no deity except You; exalted are You. Indeed, I have been of the wrongdoers). No Muslim ever supplicates with it for anything except that Allah answers him.", translationTr: "", translationUr: "", narratorAr: "عن سعد بن أبي وقاص رضي الله عنه", narratorEn: "Narrated by Sa'd ibn Abi Waqqas (RA)", referenceAr: "سنن الترمذي ومستدرك الحاكم (صحيح) - باب دعاء الكرب", referenceEn: "Sunan at-Tirmidhi & Mustadrak al-Hakim (Sahih)", categoryAr: "الدعاء", categoryEn: "Supplication", explanationAr: "أعظم دعاء لكشف الشدائد وتفريج الكرب؛ جمع بين التوحيد والتنزيه والاعتراف بالذنب.", explanationEn: "The ultimate prayer for relief from agony and tribulation, unifying Monotheism, adoration, and humble contrition.", explanationTr: "Dert ve sıkıntıları gideren en tesirli duadır; tevhid, tenzih ve tövbeyi bir araya getirir.", explanationUr: "تکلیف اور پریشانی دور کرنے کی سب سے موثر دعا ہے، جس میں توحید، تسبیح اور گناہ کا اعتراف جمع ہے۔"),
        OfflineDailyHadith(id: "22", titleAr: "الباقيات الصالحات وحط الخطايا", titleEn: "The Enduring Good Deeds and Erasing of Sins", titleTr: "Kalıcı Salih Ameller ve Günahların Silinmesi", titleUr: "باقیاتِ صالحات اور گناہوں کا مٹنا", textAr: "أَحَبُّ الْكَلاَمِ إِلَى اللَّهِ أَرْبَعٌ: سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكْبَرُ، لاَ يَضُرُّكَ بِأَيِّهِنَّ بَدَأْتَ.", translationEn: "The most beloved words to Allah are four: 'Subhan Allah, wal-Hamdu lillah, wa La ilaha illa Allah, wallahu Akbar' (Glory be to Allah, praise be to Allah, there is no god but Allah, and Allah is the Greatest). It does not matter with which of them you begin.", translationTr: "", translationUr: "", narratorAr: "عن سمرة بن جندب رضي الله عنه", narratorEn: "Narrated by Samurah ibn Jundub (RA)", referenceAr: "صحيح مسلم - باب فضل التسبيح والتحميد", referenceEn: "Sahih Muslim - Chapter on Tasbih & Tahmid", categoryAr: "الذكر", categoryEn: "Remembrance", explanationAr: "هذه الكلمات الأربع هي الباقيات الصالحات وغراس الجنة، وأحب الذكر إلى الله بعد القرآن الكريم.", explanationEn: "These four phrases form the everlasting righteous deeds, seedlings of Paradise, and the dearest words to Allah.", explanationTr: "Bu dört mübarek kelime cennetin fidanları ve Kur'an'dan sonra Allah'a en sevimli sözlerdir.", explanationUr: "یہ چار کلمات باقی رہنے والی نیکیاں اور جنت کے پودے ہیں، اور قرآن کے بعد اللہ کو سب سے محبوب ہیں۔"),
        OfflineDailyHadith(id: "23", titleAr: "فضل الصلاة على النبي صلى الله عليه وسلم", titleEn: "The Virtue of Sending Blessings upon the Prophet", titleTr: "Peygamber'e Salavat Getirmenin Fazileti", titleUr: "نبی ﷺ پر درود بھیجنے کی فضیلت", textAr: "مَنْ صَلَّى عَلَيَّ صَلاَةً وَاحِدَةً صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْرًا، وَحَطَّ عَنْهُ عَشْرَ خَطِيئَاتٍ، وَرَفَعَ لَهُ عَشْرَ دَرَجَاتٍ.", translationEn: "Whoever sends blessings upon me once, Allah will send ten blessings upon him, erase ten sins from him, and raise him ten degrees in status.", translationTr: "", translationUr: "", narratorAr: "عن أنس بن مالك رضي الله عنه", narratorEn: "Narrated by Anas ibn Malik (RA)", referenceAr: "سنن النسائي ومسند أحمد (صحيح) - باب فضل الصلاة على النبي", referenceEn: "Sunan an-Nasa'i & Musnad Ahmad (Sahih)", categoryAr: "الذكر", categoryEn: "Remembrance", explanationAr: "الصلاة على النبي صلى الله عليه وسلم سبب لمغفرة الذنوب وكفاية الهموم ونيل شفاعته ورفعة الدرجات في الدنيا والآخرة.", explanationEn: "Supplicating blessings upon the Prophet grants relief from grief, forgiveness of sins, high ranks, and intercession.", explanationTr: "Peygamberimize salavat getirmek günahların affına, sıkıntıların giderilmesine ve derecelerin yükselmesine vesiledir.", explanationUr: "نبی کریم ﷺ پر درود بھیجنا گناہوں کی معافی، غموں کے خاتمے اور درجات کی بلندی کا ذریعہ ہے۔"),
        OfflineDailyHadith(id: "101", titleAr: "الصلوات الخمس كالنهر", titleEn: "The Five Prayers Are Like a River", titleTr: "Beş Vakit Namaz Bir Irmak Gibidir", titleUr: "پانچ نمازیں ایک نہر کی مانند", textAr: "أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ «أَرَأَيْتُمْ لَوْ أَنَّ نَهَرًا بِبَابِ أَحَدِكُمْ، يَغْتَسِلُ فِيهِ كُلَّ يَوْمٍ خَمْسًا، مَا تَقُولُ ذَلِكَ يُبْقِي مِنْ دَرَنِهِ». قَالُوا لاَ يُبْقِي مِنْ دَرَنِهِ شَيْئًا. قَالَ «فَذَلِكَ مِثْلُ الصَّلَوَاتِ الْخَمْسِ، يَمْحُو اللَّهُ بِهَا الْخَطَايَا».", translationEn: "I heard Allah's Messenger (ﷺ) saying, \"If there was a river at the door of anyone of you and he took a bath in it five times a day would you notice any dirt on him?\" They said, \"Not a trace of dirt would be left.\" The Prophet (ﷺ) added, \"That is the example of the five prayers with which Allah blots out (annuls) evil deeds.\"", translationTr: "Nebi Sallallahu Aleyhi ve Sellem: \"Sizden birinizin kapısının önünden günde beş kez yıkandığı bir nehir aksa, ne dersiniz bu yıkanma onun üzerinde bir kir bırakır mı?\" diye sordu. Ashâb-ı kiram, \"Kirden eser bırakmaz\" diye cevap verdi. Bunun üzerine Resulullah Sallallahu Aleyhi ve Sellem şöyle buyurdu: \"Beş vakit namaz da böyledir. Onlar sayesinde Allah, günahları siler.\"", translationUr: "انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ صلی اللہ علیہ وسلم فرماتے تھے کہ اگر کسی شخص کے دروازے پر نہر جاری ہو اور وہ روزانہ اس میں پانچ پانچ دفعہ نہائے تو تمہارا کیا گمان ہے۔ کیا اس کے بدن پر کچھ بھی میل باقی رہ سکتا ہے؟ صحابہ نے عرض کی کہ نہیں یا رسول اللہ! ہرگز نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا کہ یہی حال پانچوں وقت کی نمازوں کا ہے کہ اللہ پاک ان کے ذریعہ سے گناہوں کو مٹا دیتا ہے۔", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (٥٢٨)", referenceEn: "Sahih al-Bukhari 528", categoryAr: "الصلاة", categoryEn: "Prayer", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "102", titleAr: "فضل صلاة الجماعة", titleEn: "The Worth of Praying Together", titleTr: "Cemaatle Namazın Fazileti", titleUr: "باجماعت نماز کی فضیلت", textAr: "أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ «صَلاَةُ الْجَمَاعَةِ تَفْضُلُ صَلاَةَ الْفَذِّ بِسَبْعٍ وَعِشْرِينَ دَرَجَةً».", translationEn: "Allah's Messenger (ﷺ) said, \"The prayer in congregation is twenty seven times superior to the prayer offered by a person alone.\"", translationTr: "Nebi Sallallahu Aleyhi ve Sellem'in şöyle buyurduğu nakledilmiştir: \"Cemaatle kılınan namaz, tek başına kılınan namazdan yirmi yedi derece daha üstündür.\"", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ جماعت کے ساتھ نماز اکیلے نماز پڑھنے سے ستائیس درجہ زیادہ فضیلت رکھتی ہے۔", narratorAr: "عن عبد الله بن عمر رضي الله عنهما", narratorEn: "Narrated by Abdullah ibn Umar (RA)", referenceAr: "رواه البخاري (٦٤٥)", referenceEn: "Sahih al-Bukhari 645", categoryAr: "الصلاة", categoryEn: "Prayer", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "103", titleAr: "صلاة الفجر والعصر", titleEn: "The Dawn and Afternoon Prayers", titleTr: "Sabah ve İkindi Namazları", titleUr: "فجر اور عصر کی نمازیں", textAr: "أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ «مَنْ صَلَّى الْبَرْدَيْنِ دَخَلَ الْجَنَّةَ».", translationEn: "Allah's Messenger (ﷺ) said, \"Whoever prays the two cool prayers ('Asr and Fajr) will go to Paradise.\"", translationTr: "Allah Resulü (Sallallahu Aleyhi ve Sellem)'in şöyle dediğini nakletmiştir: \"iki serin vakitteki namazları kim kılarsa cennete girer.\"", translationUr: "نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ جس نے ٹھنڈے وقت کی دو نمازیں ( وقت پر ) پڑھیں ( فجر اور عصر ) تو وہ جنت میں داخل ہو گا۔", narratorAr: "عن أبي موسى الأشعري رضي الله عنه", narratorEn: "Narrated by Abu Musa al-Ash'ari (RA)", referenceAr: "رواه البخاري (٥٧٤)", referenceEn: "Sahih al-Bukhari 574", categoryAr: "الصلاة", categoryEn: "Prayer", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "104", titleAr: "أقرب ما يكون العبد من ربه", titleEn: "Nearest to the Lord in Prostration", titleTr: "Kulun Rabbine En Yakın Anı", titleUr: "بندہ اپنے رب کے سب سے قریب کب ہوتا ہے", textAr: "أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ «أَقْرَبُ مَا يَكُونُ الْعَبْدُ مِنْ رَبِّهِ وَهُوَ سَاجِدٌ فَأَكْثِرُوا الدُّعَاءَ».", translationEn: "Abu Huraira reported: The Messenger of Allah (ﷺ) said: The nearest a servant comes to his Lord is when he is prostrating himself, so make supplication (in this state)", translationTr: "Resulullah (Sallallahu Aleyhi ve Sellem): «Kulun rabbine en yakın olduğu hâl secdede bulunduğu hâldir. Binaenaleyh siz (secdede) duayı çok edin!» buyurmuşlar.", translationUr: "رسول اللہﷺ نے فرمایا : ’’بندہ اپنے رب کے سب سے زیادہ قریب اس حالت میں ہوتا ہے جب وہ سجدے میں ہوتا ہے، لہٰذا اس میں کثرت سے دعا کرو۔‘‘", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه مسلم (٤٨٢)", referenceEn: "Sahih Muslim 482", categoryAr: "الصلاة", categoryEn: "Prayer", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "105", titleAr: "الصلوات الخمس تكفّر ما بينها", titleEn: "Each Prayer Wipes Away What Came Before", titleTr: "Namazlar Aralarındaki Günahlara Kefarettir", titleUr: "نمازیں درمیانی گناہوں کا کفارہ ہیں", textAr: "عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ «الصَّلَوَاتُ الْخَمْسُ وَالْجُمُعَةُ إِلَى الْجُمُعَةِ كَفَّارَاتٌ لِمَا بَيْنَهُنَّ».", translationEn: "Abu Huraira reported that the Messenger of Allah (ﷺ) said: The five (daily) prayers and one Friday prayer to (the next) Friday prayer are expiations (for the sins committed in the intervals) between them.", translationTr: "Nebi (Sallallahu aleyhi ve Sellem)'den şöyle buyurduğunu nakletti: \"Beş vakit namaz, bir sonraki cumaya kadar Cuma namazı aralarındaki (günah)lar için kefarettir.\"", translationUr: "نبی ﷺ سے روایت کی، آپ نے فرمایا : ’’ پانچوں نمازیں اور ایک جمعہ ( دوسرے ) جمعہ تک درمیانی مدت کے گناہوں کاکفارہ ہیں۔‘‘", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه مسلم (٢٣٣)", referenceEn: "Sahih Muslim 233", categoryAr: "الصلاة", categoryEn: "Prayer", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "106", titleAr: "صيام رمضان إيمانًا واحتسابًا", titleEn: "Fasting Ramadan with Faith and Hope", titleTr: "Ramazan'ı İnanarak ve Sevabını Umarak Oruçla Geçirmek", titleUr: "ایمان اور ثواب کی نیت سے رمضان کے روزے", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «مَنْ صَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ».", translationEn: "Allah's Messenger (ﷺ) said, \"Whoever observes fasts during the month of Ramadan out of sincere faith, and hoping to attain Allah's rewards, then all his past sins will be forgiven.\"", translationTr: "Resulullah sallallahu aleyhi ve sellem buyurdu ki: \"Kim inanarak ve sevabını yalnızca Allah'tan umarak Ramazan orucunu tutarsa geçmiş günahları bağışlanır.\"", translationUr: "نبی کریم صلی اللہ علیہ وسلم نے فرمایا جس نے رمضان کے روزے ایمان اور خالص نیت کے ساتھ رکھے اس کے پچھلے گناہ بخش دیئے گئے۔", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (٣٨)", referenceEn: "Sahih al-Bukhari 38", categoryAr: "الصيام", categoryEn: "Fasting", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "107", titleAr: "للصائم فرحتان", titleEn: "The Two Joys of One Who Fasts", titleTr: "Oruçlunun İki Sevinci", titleUr: "روزہ دار کی دو خوشیاں", textAr: "عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ «يَقُولُ اللَّهُ عَزَّ وَجَلَّ الصَّوْمُ لِي وَأَنَا أَجْزِي بِهِ يَدَعُ شَهْوَتَهُ وَأَكْلَهُ وَشُرْبَهُ مِنْ أَجْلِي، وَالصَّوْمُ جُنَّةٌ، وَلِلصَّائِمِ فَرْحَتَانِ فَرْحَةٌ حِينَ يُفْطِرُ وَفَرْحَةٌ حِينَ يَلْقَى رَبَّهُ، وَلَخَلُوفُ فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ».", translationEn: "The Prophet (ﷺ) said, \"Allah said: The Fast is for Me and I will give the reward for it, as he (the one who observes the fast) leaves his sexual desire, food and drink for My Sake. Fasting is a screen (from Hell) and there are two pleasures for a fasting person, one at the time of breaking his fast, and the other at the time when he will meet his Lord. And the smell of the mouth of a fasting person is better in Allah's Sight than the smell of musk.\"", translationTr: "Nebi Sallallahu Aleyhi ve Sellem şöyle haber vermiştir: Aziz ve celil olan Allah şöyle buyurur: 'Oruç benim içindir. Onun mükafatını ancak ben veririm. Oruçlu kişi şehvetini, yemesini, içmesini benim için terkeder. Oruç bir kalkandır. Oruçlu için iki sevinç anı vardır: Biri iftar ederken duyduğu sevinç, biri de (kıyamet günü) Rabbine kavuşurken duyacağı sevinç. Yemin olsun ki, oruçlu ağzın açlık kokusu, Allah katında misk kokusundan daha hoştur.", translationUr: "نبی کریم صلی اللہ علیہ وسلم نے فرمایا ”اللہ عزوجل فرماتا ہے کہ روزہ خالص میرے لیے ہوتا ہے اور میں ہی اس کا بدلہ دیتا ہوں۔ بندہ اپنی شہوت، کھانا پینا میری رضا کے لیے چھوڑتا ہے اور روزہ گناہوں سے بچنے کی ڈھال ہے اور روزہ دار کے لیے دو خوشیاں ہیں۔ ایک خوشی اس وقت جب وہ افطار کرتا ہے اور ایک خوشی اس وقت جب وہ اپنے رب سے ملتا ہے اور روزہ دار کے منہ کی بو، اللہ کے نزدیک مشک عنبر کی خوشبو سے زیادہ پاکیزہ ہے۔“", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (٧٤٩٢)", referenceEn: "Sahih al-Bukhari 7492", categoryAr: "الصيام", categoryEn: "Fasting", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "108", titleAr: "بركة السحور", titleEn: "The Blessing in the Pre-Dawn Meal", titleTr: "Sahurdaki Bereket", titleUr: "سحری میں برکت", textAr: "قَالَ النَّبِيُّ صلى الله عليه وسلم «تَسَحَّرُوا فَإِنَّ فِي السَّحُورِ بَرَكَةً».", translationEn: "The Prophet (ﷺ) said, \"Take Suhur as there is a blessing in it.\"", translationTr: "Resulullah Sallallahu Aleyhi ve Sellem şöyle buyurmuştur: \"Sahur yapın! Çünkü sahurda bereket vardır.\"", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، سحری کھاؤ کہ سحری میں برکت ہوتی ہے۔", narratorAr: "عن أنس بن مالك رضي الله عنه", narratorEn: "Narrated by Anas ibn Malik (RA)", referenceAr: "رواه البخاري (١٩٢٣)", referenceEn: "Sahih al-Bukhari 1923", categoryAr: "الصيام", categoryEn: "Fasting", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "109", titleAr: "الصيام عن قول الزور", titleEn: "Fasting from False Speech", titleTr: "Yalan Sözden de Oruç Tutmak", titleUr: "جھوٹ سے بھی روزہ", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «مَنْ لَمْ يَدَعْ قَوْلَ الزُّورِ وَالْعَمَلَ بِهِ فَلَيْسَ لِلَّهِ حَاجَةٌ فِي أَنْ يَدَعَ طَعَامَهُ وَشَرَابَهُ».", translationEn: "The Prophet (ﷺ) said, \"Whoever does not give up forged speech and evil actions, Allah is not in need of his leaving his food and drink (i.e. Allah will not accept his fasting)\"", translationTr: "Nebi Sallallahu Aleyhi ve Sellem şöyle buyurmuştur: \"Yalan söylemeyi ve bu yalancı şahitliği bırakmayan kimsenin yemeyi ve içmeyi bırakmasına Allah'ın asla ihtiyacı yoktur.\"", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، اگر کوئی شخص جھوٹ بولنا اور دغا بازی کرنا ( روزے رکھ کر بھی ) نہ چھوڑے تو اللہ تعالیٰ کو اس کی کوئی ضرورت نہیں کہ وہ اپنا کھانا پینا چھوڑ دے۔", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (١٩٠٣)", referenceEn: "Sahih al-Bukhari 1903", categoryAr: "الصيام", categoryEn: "Fasting", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "110", titleAr: "صيام يوم في سبيل الله", titleEn: "A Day's Fast for the Sake of Allah", titleTr: "Allah Yolunda Bir Günlük Oruç", titleUr: "اللہ کی راہ میں ایک دن کا روزہ", textAr: "سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ «مَنْ صَامَ يَوْمًا فِي سَبِيلِ اللَّهِ بَاعَدَ اللَّهُ وَجْهَهُ عَنِ النَّارِ سَبْعِينَ خَرِيفًا».", translationEn: "Abu Sa'id al-Khudri (Allah be pleased with him) reported Allah's Messenger (ﷺ) as saying: He who observes fast for a day in the way of Allah He would remove his face from the Hell to the extent of seventy years' distance.", translationTr: "Ben Resulullah (Sallallahu Aleyhi ve Sellem): «Her kim Allah yolunda bir gün oruç tutarsa Allah o kimsenin yüzünü yetmiş yıl cehennemden ırak eyler, buyururken işittim.»", translationUr: "میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فر ما تے ہو ئے سنا : \" جس نے اللہ کی راہ میں ایک دن کا روزہ رکھا اللہ تعا لیٰ اس کے چہرے کو ( جہنم کی ) آگ سے ستر سال کی مسافت تک دور کر دیتا ہے۔\"", narratorAr: "عن أبي سعيد الخدري رضي الله عنه", narratorEn: "Narrated by Abu Sa'id al-Khudri (RA)", referenceAr: "رواه مسلم (١١٥٣)", referenceEn: "Sahih Muslim 1153", categoryAr: "الصيام", categoryEn: "Fasting", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "111", titleAr: "الصدقة لا تنقص المال", titleEn: "Charity Never Lessens Wealth", titleTr: "Sadaka Malı Eksiltmez", titleUr: "صدقہ مال کم نہیں کرتا", textAr: "عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم قَالَ «مَا نَقَصَتْ صَدَقَةٌ مِنْ مَالٍ وَمَا زَادَ اللَّهُ عَبْدًا بِعَفْوٍ إِلاَّ عِزًّا وَمَا تَوَاضَعَ أَحَدٌ لِلَّهِ إِلاَّ رَفَعَهُ اللَّهُ».", translationEn: "Abu Huraira reported Allah's Messenger (ﷺ) as saying: Charity does not decrease wealth, no one forgives another except that Allah increases his honor, and no one humbles himself for the sake of Allah except that Allah raises his status.", translationTr: "Resûlullah (Sallallahu Aleyhi ve Sellem)’den naklen rivayet etti: «Sadaka hiç bir malı eksiltmez. Af sebebiyle Allah bir kulun ancak Şerefini artırır. Ve bir kimse Allah için tevazu gösterirse Allah onu ancak yükseltir.» buyurmuşlar.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" صدقے نے مال میں کبھی کوئی کمی نہیں کی اور معاف کرنے سے اللہ تعالیٰ بندے کو عزت ہی میں بڑھاتا ہے اور کوئی شخص ( صرف اور صرف ) اللہ کی خاطر تواضع ( انکسار ) اختیار نہیں کرتا مگر اللہ تعالیٰ اس کا مقام بلند کر دیتا ہے۔\"", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه مسلم (٢٥٨٨)", referenceEn: "Sahih Muslim 2588", categoryAr: "الصدقة", categoryEn: "Charity", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "112", titleAr: "ولو بشق تمرة", titleEn: "Even Half a Date", titleTr: "Yarım Hurmayla Bile Olsa", titleUr: "خواہ کھجور کا ایک ٹکڑا ہی ہو", textAr: "سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ «اتَّقُوا النَّارَ وَلَوْ بِشِقِّ تَمْرَةٍ».", translationEn: "\"Save yourself from Hell-fire even by giving half a date-fruit in charity.\"", translationTr: "Rasûlullah Sallallahu Aleyhi ve Sellem'in şöyle buyurduğunu işittim demiştir: \"Yarım hurmayla bile olsa cehennemden korunun.\"", translationUr: "میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ کہتے سنا کہ جہنم سے بچو اگرچہ کھجور کا ایک ٹکڑا دے کر ہی سہی ( مگر ضرور صدقہ کر کے دوزخ کی آگ سے بچنے کی کوشش کرو )۔", narratorAr: "عن عدي بن حاتم رضي الله عنه", narratorEn: "Narrated by Adi ibn Hatim (RA)", referenceAr: "رواه البخاري (١٤١٧)", referenceEn: "Sahih al-Bukhari 1417", categoryAr: "الصدقة", categoryEn: "Charity", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "113", titleAr: "اليد العليا خير من اليد السفلى", titleEn: "The Giving Hand Is Better", titleTr: "Veren El Alan Elden Hayırlıdır", titleUr: "دینے والا ہاتھ بہتر ہے", textAr: "عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ «الْيَدُ الْعُلْيَا خَيْرٌ مِنَ الْيَدِ السُّفْلَى، وَابْدَأْ بِمَنْ تَعُولُ، وَخَيْرُ الصَّدَقَةِ عَنْ ظَهْرِ غِنًى، وَمَنْ يَسْتَعْفِفْ يُعِفَّهُ اللَّهُ، وَمَنْ يَسْتَغْنِ يُغْنِهِ اللَّهُ».", translationEn: "The Prophet (ﷺ) said, \"The upper hand is better than the lower hand (i.e. he who gives in charity is better than him who takes it). One should start giving first to his dependents. And the best object of charity is that which is given by a wealthy person (from the money which is left after his expenses). And whoever abstains from asking others for some financial help, Allah will give him and save him from asking others, Allah will make him self-sufficient.\"", translationTr: "", translationUr: "", narratorAr: "عن حكيم بن حزام رضي الله عنه", narratorEn: "Narrated by Hakim ibn Hizam (RA)", referenceAr: "رواه البخاري (١٤٢٧)", referenceEn: "Sahih al-Bukhari 1427", categoryAr: "الصدقة", categoryEn: "Charity", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "114", titleAr: "كل معروف صدقة", titleEn: "Every Kindness Is Charity", titleTr: "Her İyilik Sadakadır", titleUr: "ہر نیکی صدقہ ہے", textAr: "عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ «كُلُّ مَعْرُوفٍ صَدَقَةٌ».", translationEn: "The Prophet (ﷺ) said, \"Every good deed is a Sadaqa.\"", translationTr: "Nebi Sallallahu Aleyhi ve Sellem: \"Her maruf (iyilik) bir sadakadır\" buyurdu.", translationUr: "نبی کریم صلی اللہ علیہ وسلم نے فرمایا ”ہر نیک کام صدقہ ہے۔“", narratorAr: "عن جابر بن عبد الله رضي الله عنهما", narratorEn: "Narrated by Jabir ibn Abdullah (RA)", referenceAr: "رواه البخاري (٦٠٢١)", referenceEn: "Sahih al-Bukhari 6021", categoryAr: "الصدقة", categoryEn: "Charity", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "115", titleAr: "دعاء الملكين للمنفق", titleEn: "The Angels' Prayer for the Giver", titleTr: "Meleklerin Infak Edene Duası", titleUr: "خرچ کرنے والے کے لیے فرشتوں کی دعا", textAr: "أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ «مَا مِنْ يَوْمٍ يُصْبِحُ الْعِبَادُ فِيهِ إِلاَّ مَلَكَانِ يَنْزِلاَنِ فَيَقُولُ أَحَدُهُمَا اللَّهُمَّ أَعْطِ مُنْفِقًا خَلَفًا، وَيَقُولُ الآخَرُ اللَّهُمَّ أَعْطِ مُمْسِكًا تَلَفًا».", translationEn: "The Prophet (ﷺ) said, \"Every day two angels come down from Heaven and one of them says, 'O Allah! Compensate every person who spends in Your Cause,' and the other (angel) says, 'O Allah! Destroy every miser.\"", translationTr: "Resulullah Sallallahu Aleyhi ve Sellem şöyle buyurmuştur: \"Her gün, dünyaya iki melek iner ve bunlardan biri «Allah'ım! İnfak eden kişiye yenisini ver», diğeri de «Allah'ım! Vermeyenin malını telef et» der.\"", translationUr: "نبی کریم صلی اللہ علیہ وسلم نے فرمایا، کوئی دن ایسا نہیں جاتا کہ جب بندے صبح کو اٹھتے ہیں تو دو فرشتے آسمان سے نہ اترتے ہوں۔ ایک فرشتہ تو یہ کہتا ہے کہ اے اللہ! خرچ کرنے والے کو اس کا بدلہ دے۔ اور دوسرا کہتا ہے کہ اے اللہ! «ممسك» اور بخیل کے مال کو تلف کر دے۔", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (١٤٤٢)", referenceEn: "Sahih al-Bukhari 1442", categoryAr: "الصدقة", categoryEn: "Charity", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "116", titleAr: "خيركم من تعلم القرآن وعلّمه", titleEn: "The Best of You Learn and Teach the Quran", titleTr: "En Hayırlınız Kur'an'ı Öğrenen ve Öğretendir", titleUr: "تم میں بہترین وہ ہے جو قرآن سیکھے اور سکھائے", textAr: "عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ «خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ».", translationEn: "The Prophet (ﷺ) said, \"The best among you (Muslims) are those who learn the Qur'an and teach it.\"", translationTr: "Nebi Sallallahu Aleyhi ve Sellem'in şöyle buyurduğu rivayet edilmiştir: \"Sizin en hayırlınız Kur'an'ı öğrenen ve öğretendir.\"", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ تم میں سب سے بہتر وہ ہے جو قرآن مجید پڑھے اور پڑھائے۔", narratorAr: "عن عثمان بن عفان رضي الله عنه", narratorEn: "Narrated by Uthman ibn Affan (RA)", referenceAr: "رواه البخاري (٥٠٢٧)", referenceEn: "Sahih al-Bukhari 5027", categoryAr: "القرآن الكريم", categoryEn: "The Quran", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "117", titleAr: "الماهر بالقرآن", titleEn: "The One Skilled in the Quran", titleTr: "Kur'an'da Mahir Olan", titleUr: "قرآن میں ماہر", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «الْمَاهِرُ بِالْقُرْآنِ مَعَ السَّفَرَةِ الْكِرَامِ الْبَرَرَةِ وَالَّذِي يَقْرَأُ الْقُرْآنَ وَيَتَتَعْتَعُ فِيهِ وَهُوَ عَلَيْهِ شَاقٌّ لَهُ أَجْرَانِ».", translationEn: "A'isha reported Allah's Messenger (ﷺ) (as saying): One who is proficient in the Qur'an is associated with the noble, upright, recording angels; and he who falters in it, and finds it difficult for him, will have two rewards.", translationTr: "Resûlullah (Sallallahu Aleyhi ve Sellem): «Kur'ân'da mahir olan sefere denilen kerîm ve muti' Nebilerle beraber olacakdır. Kur'ân-ı kekeleyerek güç hâl ile okuyana ise iki ecir vardır.» buyurdular.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" قرآن مجید کا ماہر قرآن لکھنے والے انتہائی معزز اور اللہ تعالیٰ کے فرمانبردار فرشتوں کے ساتھ ہوگا اور جو انسان قرآن مجید پڑھتا ہے اور ہکلاتا ہے۔ اور وہ ( پڑھنا ) اس کے لئے مشقت کا باعث ہے، اس کے لئے دو اجر ہیں۔\"", narratorAr: "عن أم المؤمنين عائشة رضي الله عنها", narratorEn: "Narrated by Aishah, Mother of the Believers (RA)", referenceAr: "رواه مسلم (٧٩٨)", referenceEn: "Sahih Muslim 798", categoryAr: "القرآن الكريم", categoryEn: "The Quran", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "118", titleAr: "القرآن شفيع لأصحابه", titleEn: "The Quran Will Intercede for Its Readers", titleTr: "Kur'an Okuyanlarına Şefaatçi Olur", titleUr: "قرآن اپنے پڑھنے والوں کی سفارش کرے گا", textAr: "سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ «اقْرَءُوا الْقُرْآنَ فَإِنَّهُ يَأْتِي يَوْمَ الْقِيَامَةِ شَفِيعًا لأَصْحَابِهِ اقْرَءُوا الزَّهْرَاوَيْنِ الْبَقَرَةَ وَسُورَةَ آلِ عِمْرَانَ فَإِنَّهُمَا تَأْتِيَانِ يَوْمَ الْقِيَامَةِ كَأَنَّهُمَا غَمَامَتَانِ أَوْ كَأَنَّهُمَا غَيَايَتَانِ أَوْ كَأَنَّهُمَا فِرْقَانِ مِنْ طَيْرٍ صَوَافَّ تُحَاجَّانِ عَنْ أَصْحَابِهِمَا اقْرَءُوا سُورَةَ الْبَقَرَةِ فَإِنَّ أَخْذَهَا بَرَكَةٌ وَتَرْكَهَا حَسْرَةٌ وَلاَ تَسْتَطِيعُهَا الْبَطَلَةُ».", translationEn: "Abu Umama said he heard Allah's Messenger (ﷺ) say: Recite the Qur'an, for on the Day of Resurrection it will come as an intercessor for those who recite It. Recite the two bright ones, al-Baqara and Surah Al 'Imran, for on the Day of Resurrection they will come as two clouds or two shades, or two flocks of birds in ranks, pleading for those who recite them. Recite Surah al-Baqara, for to take recourse to it is a blessing and to give it up is a cause of grief, and the magicians cannot confront it.", translationTr: "Resûlullah (Sallallahu Aleyhi ve Sellem)'i «Kur'ân-ı okuyun! Çünkü Kur'ân, onu okuyanlara kıyamet günü şefaatçi olarak gelecekdir. Zehrâveyn'i (yâni) Bakara ile Âl-i Imrân sûrelerini okuyun! Çünkü onlar kıyamet gününde iki bulut yahut iki gölge veya safbeste iki fırka kuş gibi gelecek; okuyucularını müdâfaa edeceklerdir. Sûre-i Bakara'yı okuyun! Zîra onu okumak bereketdir; terk etmek ise pişmanlıkdır. Onu tahsil etmeye battaller muktedir olamazlar.» buyururken işittim.", translationUr: "میں نے رسول اللہ صلی اللہ علیہ وسلم کویہ فرماتے ہوئے سنا : \" قرآن پڑھا کرو کیونکہ وہ قیامت کے دن اصحاب قرآن ( حفظ وقراءت اور عمل کرنے والوں ) کا سفارشی بن کر آئےگا۔ دو روشن چمکتی ہوئی سورتیں : البقرہ اور آل عمران پڑھا کرو کیونکہ وہ قیامت کے دن اس طرح آئیں گی جیسے وہ دو بادل یا دو سائبان ہوں یا جیسے وہ ایک سیدھ میں اڑتے پرندوں کی وہ ڈاریں ہوں، وہ اپنی صحبت میں ( پڑھنے اور عمل کرنے ) والوں کی طرف سے دفاع کریں گی۔ سورہ بقرہ پڑھا کرو کیونکہ اسے حاصل کرنا باعث برکت اور اسے ترک کرناباعث حسرت ہے اور باطل پرست اس کی طاقت نہیں رکھتے۔\"", narratorAr: "عن أبي أمامة رضي الله عنه", narratorEn: "Narrated by Abu Umamah (RA)", referenceAr: "رواه مسلم (٨٠٤)", referenceEn: "Sahih Muslim 804", categoryAr: "القرآن الكريم", categoryEn: "The Quran", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "119", titleAr: "مثل المؤمن الذي يقرأ القرآن", titleEn: "The Believer Who Recites the Quran", titleTr: "Kur'an Okuyan Müminin Örneği", titleUr: "قرآن پڑھنے والے مومن کی مثال", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «مَثَلُ الْمُؤْمِنِ الَّذِي يَقْرَأُ الْقُرْآنَ كَمَثَلِ الأُتْرُجَّةِ، رِيحُهَا طَيِّبٌ وَطَعْمُهَا طَيِّبٌ، وَمَثَلُ الْمُؤْمِنِ الَّذِي لاَ يَقْرَأُ الْقُرْآنَ كَمَثَلِ التَّمْرَةِ لاَ رِيحَ لَهَا وَطَعْمُهَا حُلْوٌ، وَمَثَلُ الْمُنَافِقِ الَّذِي يَقْرَأُ الْقُرْآنَ مَثَلُ الرَّيْحَانَةِ، رِيحُهَا طَيِّبٌ وَطَعْمُهَا مُرٌّ، وَمَثَلُ الْمُنَافِقِ الَّذِي لاَ يَقْرَأُ الْقُرْآنَ كَمَثَلِ الْحَنْظَلَةِ، لَيْسَ لَهَا رِيحٌ وَطَعْمُهَا مُرٌّ».", translationEn: "Allah's Messenger (ﷺ) said, \"The example of a Believer who recites the Qur'an, is that of a citron which smells good and tastes good; And the example of a Believer who does not recite the Qur'an, is that of a date which has no smell but tastes sweet; and the example of a hypocrite who recites the Qur'an, is that of an aromatic plant which smells good but tastes bitter; and the example of a hypocrite who does not recite the Qur'an, is that of a colocynth plant which has no smell and is bitter in taste.\"", translationTr: "Resulullah Sallallahu Aleyhi ve Sellem şöyle buyurdu: Kur'an okuyan mu'minin misali, kokusu da hoş, tadı da hoş olan portakala benzer. Kur'an okumayan mu'minin misali ise kokusu bulunmayan ve tadı da tatlı olan hurmaya benzer. Kur'an okuyan münafığın misali ise kokusu hoş, tadı acı olan reyhan, (fesleğen)e benzer. Kur'an'ı okumayan münafığın misali ise kokusu da olmayan, tadı da acı olan Hamala'ya (Ebu Cehil karpuzuna) benzer.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ اس مومن کی مثال جو قرآن پڑھتا ہو سنگترے جیسی ہے جس کی خوشبو بھی پاکیزہ ہے اور مزہ بھی پاکیزہ ہے اور اس مومن کی مثال جو قرآن نہیں پڑھتا کھجور جیسی ہے جس میں کوئی خوشبو نہیں ہوتی لیکن مزہ میٹھا ہوتا ہے اور منافق کی مثال جو قرآن پڑھتا ہو، ریحانہ ( پھول ) جیسی ہے جس کی خوشبو تو اچھی ہوتی ہے لیکن مزہ کڑوا ہوتا ہے اور جو منافق قرآن بھی نہیں پڑھتا اس کی مثال اندرائن جیسی ہے جس میں کوئی خوشبو نہیں ہوتی اور جس کا مزہ بھی کڑوا ہوتا ہے۔", narratorAr: "عن أبي موسى الأشعري رضي الله عنه", narratorEn: "Narrated by Abu Musa al-Ash'ari (RA)", referenceAr: "رواه البخاري (٥٤٢٧)", referenceEn: "Sahih al-Bukhari 5427", categoryAr: "القرآن الكريم", categoryEn: "The Quran", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "120", titleAr: "بكل حرف حسنة", titleEn: "A Reward for Every Letter", titleTr: "Her Harfe Bir Sevap", titleUr: "ہر حرف پر ایک نیکی", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «مَنْ قَرَأَ حَرْفًا مِنْ كِتَابِ اللَّهِ فَلَهُ بِهِ حَسَنَةٌ وَالْحَسَنَةُ بِعَشْرِ أَمْثَالِهَا لاَ أَقُولُ الم حَرْفٌ وَلَكِنْ أَلِفٌ حَرْفٌ وَلاَمٌ حَرْفٌ وَمِيمٌ حَرْفٌ».", translationEn: "The Messenger of Allah (ﷺ) said: \"Whoever recites a letter from Allah's Book, then he receives the reward from it, and the reward of ten the like of it. I do not say that Alif Lam Mim is a letter, but Alif is a letter, Lam is a letter and Mim is a letter.\"", translationTr: "Rasûlüllah (sallallahü aleyhi ve sellem) şöyle buyurdu: “Kim Kur’ân’dan bir harf okursa kendisine bir sevap yazılacaktır ve her sevap on katıyla karşılık bulacaktır. Elif lam mîm bir harftir demiyorum. Fakat elif bir harf lam bir harf mim de bir harftir.”", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے کتاب اللہ کا ایک حرف پڑھا اسے اس کے بدلے ایک نیکی ملے گی، اور ایک نیکی دس گنا بڑھا دی جائے گی، میں نہیں کہتا «الم» ایک حرف ہے، بلکہ «الف» ایک حرف ہے، «لام» ایک حرف ہے اور «میم» ایک حرف ہے“۔", narratorAr: "عن عبد الله بن مسعود رضي الله عنه", narratorEn: "Narrated by Abdullah ibn Mas'ud (RA)", referenceAr: "رواه الترمذي (٢٩١٠)، وصححه الألباني", referenceEn: "Jami at-Tirmidhi 2910 (Sahih - al-Albani)", categoryAr: "القرآن الكريم", categoryEn: "The Quran", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "121", titleAr: "لا تستعجل الإجابة", titleEn: "Do Not Grow Impatient for an Answer", titleTr: "Duanın Kabulünde Acele Etmeyin", titleUr: "دعا کی قبولیت میں جلدی نہ کرو", textAr: "أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ «يُسْتَجَابُ لأَحَدِكُمْ مَا لَمْ يَعْجَلْ يَقُولُ دَعَوْتُ فَلَمْ يُسْتَجَبْ لِي».", translationEn: "Allah's Messenger (ﷺ) said, \"The invocation of anyone of you is granted (by Allah) if he does not show impatience (by saying, \"I invoked Allah but my request has not been granted)", translationTr: "Nebi Sallallahu Aleyhi ve Sellem şöyle buyurmuştur: \"Dua ettim kabul edilmedi denilerek acele edilmediği sürece dualar mutlaka kabul edilir\".", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ”بندہ کی دعا قبول ہوتی ہے جب تک کہ وہ جلدی نہ کرے کہ کہنے لگے کہ میں نے دعا کی تھی اور میری دعا قبول نہیں ہوئی۔“", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (٦٣٤٠)", referenceEn: "Sahih al-Bukhari 6340", categoryAr: "الدعاء", categoryEn: "Supplication", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "122", titleAr: "الدعاء في الثلث الأخير من الليل", titleEn: "Praying in the Last Third of the Night", titleTr: "Gecenin Son Üçte Birinde Dua", titleUr: "رات کے آخری تہائی حصے میں دعا", textAr: "أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ «يَنْزِلُ رَبُّنَا تَبَارَكَ وَتَعَالَى كُلَّ لَيْلَةٍ إِلَى السَّمَاءِ الدُّنْيَا حِينَ يَبْقَى ثُلُثُ اللَّيْلِ الآخِرُ يَقُولُ مَنْ يَدْعُونِي فَأَسْتَجِيبَ لَهُ مَنْ يَسْأَلُنِي فَأُعْطِيَهُ مَنْ يَسْتَغْفِرُنِي فَأَغْفِرَ لَهُ».", translationEn: "Allah's Messenger (ﷺ) said, \"Our Lord, the Blessed, the Superior, comes every night down on the nearest Heaven to us when the last third of the night remains, saying: \"Is there anyone to invoke Me, so that I may respond to invocation? Is there anyone to ask Me, so that I may grant him his request? Is there anyone seeking My forgiveness, so that I may forgive him?", translationTr: "Nebi Sallallahu Aleyhi ve Sellem şöyle buyurmuştur: \"Yüce Rabbimiz her gece, gecenin son üçte biri kaldığında en yakın semaya inerek şöyle der: Bana dua eden yok mu ona icabet edeyim, isteyen yok mu ona vereyim, bağışlanmayı isteyen yok mu onu bağışlayayım.\"", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ ہمارا پروردگار بلند برکت والا ہے ہر رات کو اس وقت آسمان دنیا پر آتا ہے جب رات کا آخری تہائی حصہ رہ جاتا ہے۔ وہ کہتا ہے کوئی مجھ سے دعا کرنے والا ہے کہ میں اس کی دعا قبول کروں، کوئی مجھ سے مانگنے والا ہے کہ میں اسے دوں کوئی مجھ سے بخشش طلب کرنے والا ہے کہ میں اس کو بخش دوں۔", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (١١٤٥)", referenceEn: "Sahih al-Bukhari 1145", categoryAr: "الدعاء", categoryEn: "Supplication", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "123", titleAr: "الدعاء للأخ بظهر الغيب", titleEn: "Praying for a Brother in His Absence", titleTr: "Kardeşine Gıyabında Dua", titleUr: "بھائی کے لیے اس کی غیر موجودگی میں دعا", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «مَا مِنْ عَبْدٍ مُسْلِمٍ يَدْعُو لأَخِيهِ بِظَهْرِ الْغَيْبِ إِلاَّ قَالَ الْمَلَكُ وَلَكَ بِمِثْلٍ».", translationEn: "Allah's Messenger (ﷺ) said: There is no believing servant who supplicates for his brother behind his back (in his absence) that the Angels do not say: The same be for you too.", translationTr: "Resulullah (Sallallahu Aleyhi ve Sellem): «Din kardeşi için gâibâne dua eden hiç bir müslüman kul yoktur ki: Melek sana da bir misli demesin!» buyurdular.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کوئی مسلمان بندہ نہیں جو اپنے بھائی کی پیٹھ پیچھے اس کے لیے دعا کرے، مگر ایک فرشتہ ( ہے جو ) کہتا ہے : تمہیں بھی اس کے مانند ملے۔\"", narratorAr: "عن أبي الدرداء رضي الله عنه", narratorEn: "Narrated by Abu ad-Darda' (RA)", referenceAr: "رواه مسلم (٢٧٣٢)", referenceEn: "Sahih Muslim 2732", categoryAr: "الدعاء", categoryEn: "Supplication", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "124", titleAr: "الدعاء هو العبادة", titleEn: "Supplication Is Worship", titleTr: "Dua İbadetin Ta Kendisidir", titleUr: "دعا ہی عبادت ہے", textAr: "عَنِ النَّبِيِّ صلى الله عليه وسلم فِي قَوْلِهِ: (وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ ) قَالَ «الدُّعَاءُ هُوَ الْعِبَادَةُ».", translationEn: "From the Prophet (ﷺ) regarding Allah's saying: Your Lord said: Invoke Me, I shall respond to you, he said: \"The supplication is the worship.\"", translationTr: "Nebi (s.a.v.), Mü’min sûresi 60. ayet; “Rabbiniz buyuruyor ki bana duâ edin duânızı kabul edeyim” ayetindeki duâ ibadet etmek demektir dedi.", translationUr: "نبی اکرم صلی اللہ علیہ وسلم نے آیت: «وقال ربكم ادعوني أستجب لكم» ”اور تمہارے رب کا فرمان ہے کہ مجھ سے دعا کرو میں تمہاری دعاؤں کو قبول کروں گا، یقین مانو کہ جو لوگ میری عبادت سے اعراض کرتے ہیں وہ عنقریب ذلیل ہو کر جہنم میں پہنچ جائیں گے“ ( المؤمن: ۶۰ )، کی تفسیر میں فرمایا کہ دعا ہی عبادت ہے۔", narratorAr: "عن النعمان بن بشير رضي الله عنهما", narratorEn: "Narrated by An-Nu'man ibn Bashir (RA)", referenceAr: "رواه الترمذي (٢٩٦٩)، وصححه الألباني", referenceEn: "Jami at-Tirmidhi 2969 (Sahih - al-Albani)", categoryAr: "الدعاء", categoryEn: "Supplication", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "125", titleAr: "ما يصيب المسلم يكفّر خطاياه", titleEn: "What Befalls a Muslim Wipes Away Sins", titleTr: "Müslümanın Başına Gelen Günahlarına Kefarettir", titleUr: "مسلمان کو پہنچنے والی تکلیف گناہوں کا کفارہ ہے", textAr: "عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ «مَا يُصِيبُ الْمُسْلِمَ مِنْ نَصَبٍ وَلاَ وَصَبٍ وَلاَ هَمٍّ وَلاَ حُزْنٍ وَلاَ أَذًى وَلاَ غَمٍّ حَتَّى الشَّوْكَةِ يُشَاكُهَا، إِلاَّ كَفَّرَ اللَّهُ بِهَا مِنْ خَطَايَاهُ».", translationEn: "The Prophet (ﷺ) said, \"No fatigue, nor disease, nor sorrow, nor sadness, nor hurt, nor distress befalls a Muslim, even if it were the prick he receives from a thorn, but that Allah expiates some of his sins for that.\"", translationTr: "Nebi Sallallahu Aleyhi ve Sellem şöyle buyurmuştur: \"Batan bir dikene varıncaya kadar Müslüman'a isabet eden herhangi bir yorgunluk, hastalık, keder, üzüntü, eziyet ve gam sebebiyle mutlaka Allah, bunlara karşı olarak günahlarının bir kısmını affeder.\"", translationUr: "", narratorAr: "عن أبي سعيد الخدري وأبي هريرة رضي الله عنهما", narratorEn: "Narrated by Abu Sa'id al-Khudri and Abu Hurairah (RA)", referenceAr: "رواه البخاري (٥٦٤١)", referenceEn: "Sahih al-Bukhari 5641", categoryAr: "الصبر والمرض", categoryEn: "Patience & Illness", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "126", titleAr: "عجبًا لأمر المؤمن", titleEn: "The Believer's Affair Is All Good", titleTr: "Müminin Hâli Ne Hoştur", titleUr: "مومن کا معاملہ عجیب ہے", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «عَجَبًا لأَمْرِ الْمُؤْمِنِ إِنَّ أَمْرَهُ كُلَّهُ خَيْرٌ وَلَيْسَ ذَاكَ لأَحَدٍ إِلاَّ لِلْمُؤْمِنِ إِنْ أَصَابَتْهُ سَرَّاءُ شَكَرَ فَكَانَ خَيْرًا لَهُ وَإِنْ أَصَابَتْهُ ضَرَّاءُ صَبَرَ فَكَانَ خَيْرًا لَهُ».", translationEn: "Suhaib reported that Allah's Messenger (ﷺ) said: Strange are the ways of a believer for there is good in every affair of his and this is not the case with anyone else except in the case of a believer for if he has an occasion to feel delight, he thanks (God), thus there is a good for him in it, and if he gets into trouble and shows resignation (and endures it patiently), there is a good for him in it.", translationTr: "Resulullah Sallallahu Aleyhi ve Sellem: «Mü'minin işine şaşarım. Gerçekten onun bütün işleri hayırdır. bu mü'minden başka hiç bir kimsede yoktur. Kendisine varlık isabet ederse şükreyler, bu onun için hayr olur. Darlık isabet ederse sabreyler, bu da onun için hayr olur.» buyurdular.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" مومن کا معاملہ عجیب ہے۔ اس کا ہرمعاملہ اس کے لیے بھلائی کا ہے۔ اور یہ بات مومن کے سوا کسی اور کومیسر نہیں۔ اسے خوشی اور خوشحالی ملے توشکر کرتا ہے۔ اور یہ اس کے لیے اچھا ہوتا ہے اور اگر اسے کوئی نقصان پہنچے تو ( اللہ کی رضا کے لیے ) صبر کر تا ہے، یہ ( ابھی ) اس کے لیے بھلائی ہوتی ہے۔\"", narratorAr: "عن صهيب رضي الله عنه", narratorEn: "Narrated by Suhayb (RA)", referenceAr: "رواه مسلم (٢٩٩٩)", referenceEn: "Sahih Muslim 2999", categoryAr: "الصبر والمرض", categoryEn: "Patience & Illness", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "127", titleAr: "أجر المريض والمسافر", titleEn: "The Reward of the Sick and the Traveller", titleTr: "Hasta ve Yolcunun Sevabı", titleUr: "بیمار اور مسافر کا اجر", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «إِذَا مَرِضَ الْعَبْدُ أَوْ سَافَرَ، كُتِبَ لَهُ مِثْلُ مَا كَانَ يَعْمَلُ مُقِيمًا صَحِيحًا».", translationEn: "Allah's Apostle said, \"When a slave falls ill or travels, then he will get reward similar to that he gets for good deeds practiced at home when in good health.\"", translationTr: "Resulullah Sallallahu Aleyhi ve Sellem'in şöyle buyurduğunu söylemişti: \"Kul hastalandığında veya yolculuğa çıktığında sağlıklı iken veya yolculuğa çıkmadan önce yapmış olduğu amellerin sevabını aynen alır.\"", translationUr: "نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ جب بندہ بیمار ہوتا ہے یا سفر کرتا ہے تو اس کے لیے ان تمام عبادات کا ثواب لکھا جاتا ہے جنہیں اقامت یا صحت کے وقت یہ کیا کرتا تھا۔", narratorAr: "عن أبي موسى الأشعري رضي الله عنه", narratorEn: "Narrated by Abu Musa al-Ash'ari (RA)", referenceAr: "رواه البخاري (٢٩٩٦)", referenceEn: "Sahih al-Bukhari 2996", categoryAr: "الصبر والمرض", categoryEn: "Patience & Illness", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "128", titleAr: "البلاء علامة خير", titleEn: "Hardship Can Be a Sign of Good", titleTr: "Musibet Hayrın İşareti Olabilir", titleUr: "آزمائش بھلائی کی علامت ہو سکتی ہے", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «مَنْ يُرِدِ اللَّهُ بِهِ خَيْرًا يُصِبْ مِنْهُ».", translationEn: "Allah's Messenger (ﷺ) said, \"If Allah wants to do good to somebody, He afflicts him with trials.\"", translationTr: "Resulullah Sallallahu Aleyhi ve Sellem şöyle buyurdu: Allah kimin hakkında hayır murad ederse ona musibet verir.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ اللہ تعالیٰ جس کے ساتھ خیر و بھلائی کرنا چاہتا ہے اسے بیماری کی تکالیف اور دیگر مصیبتوں میں مبتلا کر دیتا ہے۔", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (٥٦٤٥)", referenceEn: "Sahih al-Bukhari 5645", categoryAr: "الصبر والمرض", categoryEn: "Patience & Illness", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "129", titleAr: "الصبر عند الصدمة الأولى", titleEn: "Patience at the First Blow", titleTr: "Sabır İlk Sarsıntı Anındadır", titleUr: "صبر پہلے صدمے کے وقت ہے", textAr: "مَرَّ النَّبِيُّ صلى الله عليه وسلم بِامْرَأَةٍ تَبْكِي عِنْدَ قَبْرٍ فَقَالَ «اتَّقِي اللَّهَ وَاصْبِرِي». قَالَتْ إِلَيْكَ عَنِّي، فَإِنَّكَ لَمْ تُصَبْ بِمُصِيبَتِي، وَلَمْ تَعْرِفْهُ. فَقِيلَ لَهَا إِنَّهُ النَّبِيُّ صلى الله عليه وسلم. فَأَتَتْ باب النَّبِيِّ صلى الله عليه وسلم فَلَمْ تَجِدْ عِنْدَهُ بَوَّابِينَ فَقَالَتْ لَمْ أَعْرِفْكَ. فَقَالَ «إِنَّمَا الصَّبْرُ عِنْدَ الصَّدْمَةِ الأُولَى».", translationEn: "The Prophet (ﷺ) passed by a woman who was weeping beside a grave. He told her to fear Allah and be patient. She said to him, \"Go away, for you have not been afflicted with a calamity like mine.\" And she did not recognize him. Then she was informed that he was the Prophet (ﷺ) . so she went to the house of the Prophet (ﷺ) and there she did not find any guard. Then she said to him, \"I did not recognize you.\" He said, \"Verily, the patience is at the first stroke of a calamity.\"", translationTr: "Nebi Sallallahu Aleyhi ve Sellem bir kabrin başında ağlayan bir kadının yanına uğradı ve ona \"Allah'tan kork ve sabret\" dedi. Kadın: \"Benden uzak dur. Benim başıma gelen musibet senin başına gelmiş değildir\" dedi. Kadına \"O Nebi idi\" denilince kadın derhal Nebi (Sallallahu aleyhi ve Sellem)'in evine geldi. Nebi Sallallahu Aleyhi ve Sellem'in evinde kapıcıların (kapıda bekleyen hiç kimsenin) bulunmadığını gördü. (Onun huzuruna girerek) şöyle dedi: \"Ben seni tanıyamadım (Ey Allah'ın Resulü!).\" Nebi Sallallahu Aleyhi ve Sellem de ona şöyle buyurdu: \"Sabır, musibetin darbesini ilk yediğin anda göstereceğin davranıştır.\"", translationUr: "نبی کریم صلی اللہ علیہ وسلم کا گزر ایک عورت پر ہوا جو قبر پر بیٹھی رو رہی تھی۔ آپ صلی اللہ علیہ وسلم نے فرمایا کہ اللہ سے ڈر اور صبر کر۔ وہ بولی جاؤ جی پرے ہٹو۔ یہ مصیبت تم پر پڑی ہوتی تو پتہ چلتا۔ وہ آپ صلی اللہ علیہ وسلم کو پہچان نہ سکی تھی۔ پھر جب لوگوں نے اسے بتایا کہ یہ نبی کریم صلی اللہ علیہ وسلم تھے، تو اب وہ ( گھبرا کر ) نبی کریم صلی اللہ علیہ وسلم کے دروازہ پر پہنچی۔ وہاں اسے کوئی دربان نہ ملا۔ پھر اس نے کہا کہ میں آپ کو پہچان نہ سکی تھی۔ ( معاف فرمائیے ) تو آپ صلی اللہ علیہ وسلم نے فرمایا کہ صبر تو جب صدمہ شروع ہو اس وقت کرنا چاہیے ( اب کیا ہوتا ہے )۔", narratorAr: "عن أنس بن مالك رضي الله عنه", narratorEn: "Narrated by Anas ibn Malik (RA)", referenceAr: "رواه البخاري (١٢٨٣)", referenceEn: "Sahih al-Bukhari 1283", categoryAr: "الصبر والمرض", categoryEn: "Patience & Illness", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "130", titleAr: "لكل داء شفاء", titleEn: "There Is a Cure for Every Illness", titleTr: "Her Hastalığın Bir Şifası Vardır", titleUr: "ہر بیماری کی شفا ہے", textAr: "عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ «مَا أَنْزَلَ اللَّهُ دَاءً إِلاَّ أَنْزَلَ لَهُ شِفَاءً».", translationEn: "The Prophet (ﷺ) said, \"There is no disease that Allah has created, except that He also has created its treatment.\"", translationTr: "Nebi Sallallahu Aleyhi ve Sellem şöyle buyurdu: \"Allah ne kadar hastalık indirmişse, mutlaka onun için bir de şifa indirmiştir.\"", translationUr: "نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ اللہ تعالیٰ نے کوئی ایسی بیماری نہیں اتاری جس کی دوا بھی نازل نہ کی ہو۔", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (٥٦٧٨)", referenceEn: "Sahih al-Bukhari 5678", categoryAr: "الصبر والمرض", categoryEn: "Patience & Illness", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "131", titleAr: "فضل عيادة المريض", titleEn: "The Worth of Visiting the Sick", titleTr: "Hasta Ziyaretinin Fazileti", titleUr: "بیمار کی عیادت کی فضیلت", textAr: "عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم قَالَ «مَنْ عَادَ مَرِيضًا لَمْ يَزَلْ فِي خُرْفَةِ الْجَنَّةِ». قِيلَ يَا رَسُولَ اللَّهِ وَمَا خُرْفَةُ الْجَنَّةِ قَالَ «جَنَاهَا».", translationEn: "Thauban, the freed slave of Allah's Messenger (ﷺ), reported Allah's Messenger (ﷺ) as saying: He who visits the sick is supposed to remain in the fruit garden of Paradise. It was said: Allah's Messenger, what is this Khurfat-ul-jannah? He said: It is a place abounding in fruits.", translationTr: "«Bir kimse bir hastayı dolaşırsa, cennetin hurfesinde olur.» — Yâ Resûlallah! Cennetin hurfesi nedir? diye sorulmuş. «Onun devşirilmiş yemişidir.» buyurmuşlar.", translationUr: "آپ نے فرمایا : \" جس شخص نے کسی مریض کی عیادت کی وہ مسلسل جنت کی روش میں رہا۔ \" آپ سے پوچھا گیا : یا رسول اللہ! جنت کی روش کیا چیز ہے؟ آپ نے فرمایا : \" اس کے پھل جنہیں وہ چنتا ہے۔\"", narratorAr: "عن ثوبان رضي الله عنه", narratorEn: "Narrated by Thawban (RA)", referenceAr: "رواه مسلم (٢٥٦٨)", referenceEn: "Sahih Muslim 2568", categoryAr: "الصبر والمرض", categoryEn: "Patience & Illness", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "132", titleAr: "لا تتمنَّ الموت لضرّ نزل بك", titleEn: "Do Not Wish for Death Because of Hardship", titleTr: "Başınıza Gelen Sıkıntıdan Dolayı Ölümü Temenni Etmeyin", titleUr: "تکلیف کی وجہ سے موت کی تمنا نہ کرو", textAr: "قَالَ النَّبِيُّ صلى الله عليه وسلم «لاَ يَتَمَنَّيَنَّ أَحَدُكُمُ الْمَوْتَ مِنْ ضُرٍّ أَصَابَهُ، فَإِنْ كَانَ لاَ بُدَّ فَاعِلاً فَلْيَقُلِ اللَّهُمَّ أَحْيِنِي مَا كَانَتِ الْحَيَاةُ خَيْرًا لِي، وَتَوَفَّنِي إِذَا كَانَتِ الْوَفَاةُ خَيْرًا لِي».", translationEn: "The Prophet (ﷺ) said, \"None of you should wish for death because of a calamity befalling him; but if he has to wish for death, he should say: \"O Allah! Keep me alive as long as life is better for me, and let me die if death is better for me.", translationTr: "Nebi Sallallahu Aleyhi ve Sellem şöyle buyurdu: \"Sakın sizden biriniz kendisine gelip çatan bir zarar ve sıkıntı dolayısıyla ölümü temenni etmesin. Eğer mutlaka böyle bir şeyi yapacaksa: Allah'ım, hayat benim için hayırlı olduğu sürece beni hayatta bırak ve eğer ölüm benim için hayırlı ise canımı al, desin.\"", translationUr: "نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ کسی تکلیف میں اگر کوئی شخص مبتلا ہو تو اسے موت کی تمنا نہیں کرنی چاہیئے اور اگر کوئی موت کی تمنا کرنے ہی لگے تو یہ کہنا چاہیئے «اللهم أحيني ما كانت الحياة خيرا لي،‏‏‏‏ وتوفني إذا كانت الوفاة خيرا لي» ”اے اللہ! جب تک زندگی میرے لیے بہتر ہے مجھے زندہ رکھ اور جب موت میرے لیے بہتر ہو تو مجھ کو اٹھا لے۔“", narratorAr: "عن أنس بن مالك رضي الله عنه", narratorEn: "Narrated by Anas ibn Malik (RA)", referenceAr: "رواه البخاري (٥٦٧١)", referenceEn: "Sahih al-Bukhari 5671", categoryAr: "الصبر والمرض", categoryEn: "Patience & Illness", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "133", titleAr: "أمك ثم أمك ثم أمك", titleEn: "Your Mother, Then Your Mother", titleTr: "Annen, Sonra Annen", titleUr: "تمہاری ماں، پھر تمہاری ماں", textAr: "جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ مَنْ أَحَقُّ النَّاسِ بِحُسْنِ صَحَابَتِي قَالَ «أُمُّكَ». قَالَ ثُمَّ مَنْ قَالَ «ثُمَّ أُمُّكَ». قَالَ ثُمَّ مَنْ قَالَ «ثُمَّ أُمُّكَ». قَالَ ثُمَّ مَنْ قَالَ «ثُمَّ أَبُوكَ».", translationEn: "Abu Huraira reported that a person came to Allah's Messenger (ﷺ) and said: Who among the people is most deserving of a fine treatment from my hand? He said: Your mother. He again said: Then who (is the next one)? He said: Again it is your mother (who deserves the best treatment from you). He said: Then who (is the next one)? He (the Holy Prophet) said: Again, it is your mother. He (again) said: Then who? Thereupon he said: Then it is your father.", translationTr: "Bir adam Resûlullah (Sallallahu Aleyhi ve Sellem)'e gelerek: — Benim güzel sohbet etmeme insanların en lâyık olanı kimdir? diye sordu. «Annendir!» buyurdular. — Sonra kimdir? dedi. «Sonra annendir!» buyurdu. — Sonra kimdir? dedi. «Sonra annendir!» buyurdu. — Sonra kimdir? dedi. «Sonra babandır!»", translationUr: "ایک شخص رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور عرض کی : لوگوں میں سے حسنِ معاشرت ( خدمت اور حسن سلوک ) کا سب سے زیادہ حقدار کون ہے؟ آپ نے فرمایا : تمہاری ماں۔ \" اس نے کہا : پھر کون؟ فرمایا : \" پھر تمہاری ماں۔ \" اس نے پوچھا : اس کے بعد کون؟ فرمایا : \" پھر تمہاری ماں۔ \" اس نے پوچھا : پھر کون؟ فرمایا : \" پھر تمہارا والد۔", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه مسلم (٢٥٤٨)", referenceEn: "Sahih Muslim 2548", categoryAr: "الوالدان وصلة الرحم", categoryEn: "Family & Parents", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "134", titleAr: "برّ الوالدين عند الكبر", titleEn: "Honouring Parents in Their Old Age", titleTr: "Yaşlanan Anne Babaya İyilik", titleUr: "بڑھاپے میں والدین کی خدمت", textAr: "عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ «رَغِمَ أَنْفُ ثُمَّ رَغِمَ أَنْفُ ثُمَّ رَغِمَ أَنْفُ». قِيلَ مَنْ يَا رَسُولَ اللَّهِ قَالَ «مَنْ أَدْرَكَ أَبَوَيْهِ عِنْدَ الْكِبَرِ أَحَدَهُمَا أَوْ كِلَيْهِمَا فَلَمْ يَدْخُلِ الْجَنَّةَ».", translationEn: "Abu Huraira reported Allah's Apostle (ﷺ) as saying: Let him be humbled into dust; let him be humbled into dust. It was said: Allah's Messenger, who is he? He said: He who sees either of his parents during their old age or he sees both of them, but he does not enter Paradise.", translationTr: "Nebi (Sallallahu Aleyhi ve Sellem)'den naklen rivayet etti: «Burnu yere sürünsün! Sonra burnu yere sürünsün! Sonra burnu yere sürünsün!» buyurmuşlar. — Kimin yâ Resûlallah? diye sorulmuş. «İhtiyarlığı anında annesi ile babasından birine yahut her ikisine yetişip de, onlar sebebiyle cennete giremeyenin!» buyurmuşlar.", translationUr: "انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" ( اس شخص کی ) ناک خاک آلود ہو گئی، پھر ( اس کی ) ناک خاک آلود ہو گئی۔ \" پوچھا گیا : اللہ کے رسول! وہ کون شخص ہے؟ فرمایا : \" جس نے اپنے ماں باپ یا ان میں سے کسی ایک کو یا دونوں کو بڑھاپے میں پایا تو ( ان کی خدمت کر کے ) جنت میں داخل نہ ہوا۔\"", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه مسلم (٢٥٥١)", referenceEn: "Sahih Muslim 2551", categoryAr: "الوالدان وصلة الرحم", categoryEn: "Family & Parents", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "135", titleAr: "صلة الرحم تزيد الرزق", titleEn: "Keeping Family Ties Brings Provision", titleTr: "Akraba Ziyareti Rızkı Artırır", titleUr: "صلہ رحمی رزق میں اضافہ کرتی ہے", textAr: "سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ «مَنْ سَرَّهُ أَنْ يُبْسَطَ لَهُ فِي رِزْقِهِ، وَأَنْ يُنْسَأَ لَهُ فِي أَثَرِهِ، فَلْيَصِلْ رَحِمَهُ».", translationEn: "I heard Allah's Messenger (ﷺ) saying, \"Who ever is pleased that he be granted more wealth and that his lease of life be pro longed, then he should keep good relations with his Kith and kin.\"", translationTr: "Resulullah Sallallahu Aleyhi ve Sellem'i şöyle buyururken dinledim: Kim rızkının lehine genişletilmesine, ecelinin de geciktirilmesine memnun oluyorsa, o da akrabalık bağını gözetsin.", translationUr: "میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ جسے پسند ہے کہ اس کی روزی میں فراخی ہو اور اس کی عمردراز کی جائے تو وہ صلہ رحمی کیا کرے۔", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (٥٩٨٥)", referenceEn: "Sahih al-Bukhari 5985", categoryAr: "الوالدان وصلة الرحم", categoryEn: "Family & Parents", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "136", titleAr: "الواصل الحقيقي", titleEn: "Truly Keeping the Ties of Kinship", titleTr: "Gerçek Akraba Bağını Gözeten", titleUr: "حقیقی صلہ رحمی کرنے والا", textAr: "عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ «لَيْسَ الْوَاصِلُ بِالْمُكَافِئِ، وَلَكِنِ الْوَاصِلُ الَّذِي إِذَا قَطَعَتْ رَحِمُهُ وَصَلَهَا».", translationEn: "The Prophet (ﷺ) said, \"Al-Wasil is not the one who recompenses the good done to him by his relatives, but Al-Wasil is the one who keeps good relations with those relatives who had severed the bond of kinship with him.\"", translationTr: "Nebi Sallallahu Aleyhi ve Sellem şöyle buyurdu: \"Akrabalık bağını gözeten, (yapılan iyiliği karşılık vererek) mükafatlandıran kimse değildir. Ama asıl akrabalık bağını gözeten kişi, akrabalık bağı kopartıldığı halde kendisi onu gözeten kimsedir.\"", translationUr: "آپ نے فرمایا کہ کسی کام کا بدلہ دینا صلہ رحمی نہیں ہے بلکہ صلہ رحمی کرنے والا وہ ہے کہ جب اس کے ساتھ صلہ رحمی کا معاملہ نہ کیا جا رہا ہو تب بھی وہ صلہ رحمی کرے۔", narratorAr: "عن عبد الله بن عمرو رضي الله عنهما", narratorEn: "Narrated by Abdullah ibn Amr (RA)", referenceAr: "رواه البخاري (٥٩٩١)", referenceEn: "Sahih al-Bukhari 5991", categoryAr: "الوالدان وصلة الرحم", categoryEn: "Family & Parents", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "137", titleAr: "خيركم خيركم لأهله", titleEn: "The Best of You to Their Families", titleTr: "En Hayırlınız Ailesine En Hayırlı Olandır", titleUr: "تم میں بہترین وہ ہے جو اپنے گھر والوں کے لیے بہترین ہو", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «خَيْرُكُمْ خَيْرُكُمْ لأَهْلِهِ وَأَنَا خَيْرُكُمْ لأَهْلِي».", translationEn: "The Messenger of Allah (ﷺ) said: \"The best of you is the best to his wives, and I am the best of you to my wives.\"", translationTr: "Rasûlüllah (sallallahü aleyhi ve sellem) şöyle buyurdu: “Sizin en hayırlınız ailesine en hayırlı olandır. Aileme karşı en hayırlı olan da benim.”", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تم میں سے بہتر وہ ہے جو اپنے گھر والوں کے لیے بہتر ہو اور میں اپنے گھر والوں کے لیے سب سے بہتر ہوں۔“", narratorAr: "عن أم المؤمنين عائشة رضي الله عنها", narratorEn: "Narrated by Aishah, Mother of the Believers (RA)", referenceAr: "رواه الترمذي (٣٨٩٥)، وصححه الألباني", referenceEn: "Jami at-Tirmidhi 3895 (Sahih - al-Albani)", categoryAr: "الوالدان وصلة الرحم", categoryEn: "Family & Parents", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "138", titleAr: "وصية جبريل بالجار", titleEn: "Jibril's Counsel about the Neighbour", titleTr: "Cebrail'in Komşu Hakkındaki Tavsiyesi", titleUr: "پڑوسی کے بارے میں جبریل کی وصیت", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «مَا زَالَ جِبْرِيلُ يُوصِينِي بِالْجَارِ حَتَّى ظَنَنْتُ أَنَّهُ سَيُوَرِّثُهُ».", translationEn: "Allah's Apostle said, Gabriel kept on recommending me about treating the neighbors in a kind and polite manner, so much so that I thought that he would order (me) to make them (my) heirs.", translationTr: "Resulullah Sallallahu Aleyhi ve Sellem şöyle buyurdu: Cibril bana komşuyu o kadar tavsiye edip durdu ki, sonunda onu mirasçı kılacağını zannettim.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ”جبرائیل علیہ السلام مجھے اس طرح باربار پڑوسی کے حق میں وصیت کرتے رہے کہ مجھے خیال گزرا کہ شاید پڑوسی کو وراثت میں شریک نہ کر دیں۔“", narratorAr: "عن عبد الله بن عمر رضي الله عنهما", narratorEn: "Narrated by Abdullah ibn Umar (RA)", referenceAr: "رواه البخاري (٦٠١٥)", referenceEn: "Sahih al-Bukhari 6015", categoryAr: "الجار والمجتمع", categoryEn: "Neighbours & Society", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "139", titleAr: "من لا يأمن جاره بوائقه", titleEn: "A Neighbour Safe from Your Harm", titleTr: "Komşusu Kötülüğünden Emin Olmayan", titleUr: "جس کا پڑوسی اس کی ایذا سے محفوظ نہ ہو", textAr: "أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ «وَاللَّهِ لاَ يُؤْمِنُ، وَاللَّهِ لاَ يُؤْمِنُ، وَاللَّهِ لاَ يُؤْمِنُ». قِيلَ وَمَنْ يَا رَسُولَ اللَّهِ قَالَ «الَّذِي لاَ يَأْمَنُ جَارُهُ بَوَايِقَهُ».", translationEn: "The Prophet (ﷺ) said, \"By Allah, he does not believe! By Allah, he does not believe! By Allah, he does not believe!\" It was said, \"Who is that, O Allah's Messenger (ﷺ)?\" He said, \"That person whose neighbor does not feel safe from his evil.\"", translationTr: "Nebi Sallallahu Aleyhi ve Sellem şöyle buyurdu: \"Allah'a yemin ederim iman etmiş olmaz, Allah'a yemin ederim iman etmiş olmaz, Allah'a yemin ederim iman etmiş olmaz. Kim ey Allah'ın Rasulü, diye soruldu. O: Komşusu sıkıntılarından yana emin olmayan kimse, buyurdu.\"", translationUr: "نبی کریم صلی اللہ علیہ وسلم نے بیان کیا ”واللہ! وہ ایمان والا نہیں۔ واللہ! وہ ایمان والا نہیں۔ واللہ! وہ ایمان والا نہیں۔ عرض کیا گیا کون: یا رسول اللہ؟ فرمایا وہ جس کے شر سے اس کا پڑوسی محفوظ نہ ہو۔“", narratorAr: "عن أبي شريح رضي الله عنه", narratorEn: "Narrated by Abu Shurayh (RA)", referenceAr: "رواه البخاري (٦٠١٦)", referenceEn: "Sahih al-Bukhari 6016", categoryAr: "الجار والمجتمع", categoryEn: "Neighbours & Society", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "140", titleAr: "المسلم من سلم المسلمون من لسانه ويده", titleEn: "Others Safe from Your Tongue and Hand", titleTr: "Müslüman, Dilinden ve Elinden Müslümanların Emin Olduğu Kişidir", titleUr: "مسلمان وہ ہے جس کی زبان اور ہاتھ سے مسلمان محفوظ رہیں", textAr: "قَالَ النَّبِيُّ صلى الله عليه وسلم «الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ، وَالْمُهَاجِرُ مَنْ هَجَرَ مَا نَهَى اللَّهُ عَنْهُ».", translationEn: "The Prophet (ﷺ) said, \"A Muslim is the one who avoids harming Muslims with his tongue or his hands. And a Muhajir (an emigrant) is the one who gives up (abandons) all what Allah has forbidden.\"", translationTr: "Resulullah Sallallahu Aleyhi ve Sellem \"Müslüman, dilinden ve elinden Müslümanların selamette kaldığı kimsedir. Muhacir de Allah'ın yasakladığı şeyleri terk edendir\" buyurmuştur.", translationUr: "نبی کریم صلی اللہ علیہ وسلم نے فرمایا ”مسلمان وہ ہے جو مسلمانوں کو اپنی زبان اور ہاتھ سے ( تکلیف پہنچنے سے ) محفوظ رکھے اور مہاجر وہ ہے جو ان چیزوں سے رک جائے جس سے اللہ نے منع کیا ہے۔“", narratorAr: "عن عبد الله بن عمرو رضي الله عنهما", narratorEn: "Narrated by Abdullah ibn Amr (RA)", referenceAr: "رواه البخاري (٦٤٨٤)", referenceEn: "Sahih al-Bukhari 6484", categoryAr: "الجار والمجتمع", categoryEn: "Neighbours & Society", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "141", titleAr: "المؤمنون كالجسد الواحد", titleEn: "Believers Are Like One Body", titleTr: "Müminler Tek Beden Gibidir", titleUr: "مومن ایک جسم کی مانند ہیں", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «مَثَلُ الْمُؤْمِنِينَ فِي تَوَادِّهِمْ وَتَرَاحُمِهِمْ وَتَعَاطُفِهِمْ مَثَلُ الْجَسَدِ إِذَا اشْتَكَى مِنْهُ عُضْوٌ تَدَاعَى لَهُ سَائِرُ الْجَسَدِ بِالسَّهَرِ وَالْحُمَّى».", translationEn: "Nu'man b. Bashir reported Allah's Messenger (ﷺ) as saying: The similitude of believers in regard to mutual love, affection, fellow-feeling is that of one body; when any limb of it aches, the whole body aches, because of sleeplessness and fever.", translationTr: "Resûlullah (Sallallahu Aleyhi ve Sellem): «Birbirlerini sevmekte, birbirlerine acımakta ve birbirlerine şefkat hususunda mu'minlerin misali cesed gibidir. Ondan bir uzuv şikayet ederse, cesedin sair uzuvları uykusuzluk ve humma ile ona (iştirake) çağrışırlar.» buyurdular.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" مسلمانوں کی ایک دوسرے سے محبت، ایک دوسرے کے ساتھ رحم دلی اور ایک دوسرے کی طرف التفات و تعاون کی مثال ایک جسم کی طرح ہے، جب اس کے ایک عضو کو تکلیف ہوتی ہے تو باقی سارا جسم بیداری اور بخار کے ذریعے سے ( سب اعضاء کو ایک دوسرے کے ساتھ ملا کر ) اس کا ساتھ دیتا ہے۔\"", narratorAr: "عن النعمان بن بشير رضي الله عنهما", narratorEn: "Narrated by An-Nu'man ibn Bashir (RA)", referenceAr: "رواه مسلم (٢٥٨٦)", referenceEn: "Sahih Muslim 2586", categoryAr: "الجار والمجتمع", categoryEn: "Neighbours & Society", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "142", titleAr: "الصدق يهدي إلى البر", titleEn: "Truthfulness Leads to Goodness", titleTr: "Doğruluk İyiliğe Götürür", titleUr: "سچائی نیکی کی طرف لے جاتی ہے", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «إِنَّ الصِّدْقَ بِرٌّ وَإِنَّ الْبِرَّ يَهْدِي إِلَى الْجَنَّةِ وَإِنَّ الْعَبْدَ لَيَتَحَرَّى الصِّدْقَ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ صِدِّيقًا وَإِنَّ الْكَذِبَ فُجُورٌ وَإِنَّ الْفُجُورَ يَهْدِي إِلَى النَّارِ وَإِنَّ الْعَبْدَ لَيَتَحَرَّى الْكَذِبَ حَتَّى يُكْتَبَ كَذَّابًا».", translationEn: "Abdullah b. Mas'ud reported Allah's Messenger (ﷺ) as saying: Telling of truth is a virtue and virtue leads to Paradise and the servant who endeavours to tell the truth is recorded as truthful, and lie is obscenity and obscenity leads to Hell-Fire, and the servant who endeavours to tell a lie is recorded as a liar.", translationTr: "Resûlullah (Sallallahu Aleyhi ve Sellem): «Şüphesiz doğruluk birrdir. Birr de cennete götürür. Kul doğruluğu araya araya nihayet Allah indinde doğrucu yazılır. Yalancılık da fucurdur. Şüphesiz fucur cehenneme götürür. Kul yalancılığı araya araya nihayet yalancı yazılır.» buyurdular.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" سچ نیکی ہے اور نیکی جنت کی طرف رہنمائی کرتی ہے اور بندہ پوری کوشش سے سچ ہی کا قصد کرتا رہتا ہے حتی کہ وہ اللہ تعالیٰ کے نزدیک صدیق لکھ دیا جاتا ہے اور جھوٹ کج روی ہے اور کج روی جہنم کی طرف لے جاتی ہے اور بندہ جھوٹ بولنے کا قصد ہوتا رہتا ہے حتی کہ اسے جھوٹا لکھ دیا جاتا ہے۔\"", narratorAr: "عن عبد الله بن مسعود رضي الله عنه", narratorEn: "Narrated by Abdullah ibn Mas'ud (RA)", referenceAr: "رواه مسلم (٢٦٠٧)", referenceEn: "Sahih Muslim 2607", categoryAr: "الصدق", categoryEn: "Truthfulness", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "143", titleAr: "علامات المنافق", titleEn: "The Signs of a Hypocrite", titleTr: "Münafığın Alametleri", titleUr: "منافق کی نشانیاں", textAr: "أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ «آيَةُ الْمُنَافِقِ ثَلاَثٌ إِذَا حَدَّثَ كَذَبَ، وَإِذَا وَعَدَ أَخْلَفَ، وَإِذَا اؤْتُمِنَ خَانَ».", translationEn: "Allah's Messenger (ﷺ) said, \"The signs of a hypocrite are three: Whenever he speaks, he tells a lie; and whenever he promises, he breaks his promise; and whenever he is entrusted, he betrays (proves to be dishonest)\"", translationTr: "Resulullah Sallallahu Aleyhi ve Sellem şöyle buyurdu: Münafıkın alameti üçtür: Konuşursa yalan söyler, söz verirse sözünde durmaz, ona bir emanet verilirse hainlik eder.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ”منافق کی تین نشانیاں ہیں، جب بولتا ہے جھوٹ بولتا ہے، جب وعدہ کرتا ہے خلاف کرتا ہے اور جب اسے امین بنایا جاتا ہے تو خیانت کرتا ہے۔“", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (٦٠٩٥)", referenceEn: "Sahih al-Bukhari 6095", categoryAr: "الصدق", categoryEn: "Truthfulness", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "144", titleAr: "البركة في الصدق في البيع", titleEn: "Honesty Blesses a Sale", titleTr: "Alışverişte Doğruluğun Bereketi", titleUr: "خرید و فروخت میں سچائی کی برکت", textAr: "عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ «الْبَيِّعَانِ بِالْخِيَارِ مَا لَمْ يَتَفَرَّقَا، فَإِنْ صَدَقَا وَبَيَّنَا بُورِكَ لَهُمَا فِي بَيْعِهِمَا، وَإِنْ كَذَبَا وَكَتَمَا مُحِقَتْ بَرَكَةُ بَيْعِهِمَا».", translationEn: "The Prophet (ﷺ) said, \"The buyer and the seller have the option of canceling or confirming the bargain unless they separate, and if they spoke the truth and made clear the defects of the goods, then they would be blessed in their bargain, and if they told lies and hid some facts, their bargain would be deprived of Allah's blessings.\"", translationTr: "Nebi Sallallahu Aleyhi ve Sellem'den nakletmiştir: \"Alıcı ve satıcı birbirinden ayrılmadıkları sürece muhayyerdirler. Şayet doğru söylerler ve açıklamaları gereken şeyleri açıklarlar ise alış verişleri bereketli kılınır. Yalan söylerler ve açıklamaları gereken şeyleri gizlerlerse alış verişlerinin bereketi giderilir.\"", translationUr: "نبی کریم صلی اللہ علیہ وسلم نے فرمایا خریدنے اور بیچنے والے جب تک ایک دوسرے سے الگ الگ نہ ہو جائیں انہیں اختیار باقی رہتا ہے۔ اب اگر دونوں نے سچائی اختیار کی اور ہر بات صاف صاف بیان اور واضح کر دی، تو ان کی خرید و فروخت میں برکت ہوتی ہے۔ لیکن اگر انہوں نے کوئی بات چھپائی یا جھوٹ بولا تو ان کی خرید و فروخت میں سے برکت مٹا دی جاتی ہے۔", narratorAr: "عن حكيم بن حزام رضي الله عنه", narratorEn: "Narrated by Hakim ibn Hizam (RA)", referenceAr: "رواه البخاري (٢١١٠)", referenceEn: "Sahih al-Bukhari 2110", categoryAr: "الصدق", categoryEn: "Truthfulness", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "145", titleAr: "إن الله رفيق يحب الرفق", titleEn: "Allah Is Gentle and Loves Gentleness", titleTr: "Allah Yumuşaktır, Yumuşaklığı Sever", titleUr: "اللہ نرم ہے اور نرمی کو پسند کرتا ہے", textAr: "أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ «يَا عَائِشَةُ إِنَّ اللَّهَ رَفِيقٌ يُحِبُّ الرِّفْقَ وَيُعْطِي عَلَى الرِّفْقِ مَا لاَ يُعْطِي عَلَى الْعُنْفِ وَمَا لاَ يُعْطِي عَلَى مَا سِوَاهُ».", translationEn: "A'isha, the wife of Allah's Apostle (ﷺ), reported that Allah's Messenger (ﷺ) said: 'A'isha, verily Allah is kind and He loves kindness and confers upon kindness which he does not confer upon severity and does not confer upon anything else besides it (kindness)", translationTr: "Resûlullah (Sallallahu Aleyhi ve Sellem): «Yâ Âişe! Şüphesiz ki, Allah refikdir. Rıfkı sever. Rıfk karşılığında şiddet ve başkası için vermediğini verir.» buyurmuşlar.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" عائشہ! اللہ تعالیٰ نرمی کرنے والا اور نرمی کو پسند فرماتا ہے اور نرمی کی بنا پر وہ کچھ عطا فرماتا ہے جو درشت مزاجی کی بنا پر عطا نہیں فرماتا، وہ اس کے علاوہ کسی بھی اور بات پر اتنا عطا نہیں فرماتا۔\"", narratorAr: "عن أم المؤمنين عائشة رضي الله عنها", narratorEn: "Narrated by Aishah, Mother of the Believers (RA)", referenceAr: "رواه مسلم (٢٥٩٣)", referenceEn: "Sahih Muslim 2593", categoryAr: "الرحمة والرفق", categoryEn: "Mercy & Gentleness", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "146", titleAr: "من لا يَرحم لا يُرحم", titleEn: "Whoever Shows No Mercy Receives None", titleTr: "Merhamet Etmeyene Merhamet Edilmez", titleUr: "جو رحم نہیں کرتا اس پر رحم نہیں کیا جاتا", textAr: "أَنَّ الأَقْرَعَ بْنَ حَابِسٍ، أَبْصَرَ النَّبِيَّ صلى الله عليه وسلم يُقَبِّلُ الْحَسَنَ فَقَالَ إِنَّ لِي عَشَرَةً مِنَ الْوَلَدِ مَا قَبَّلْتُ وَاحِدًا مِنْهُمْ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «إِنَّهُ مَنْ لاَ يَرْحَمْ لاَ يُرْحَمْ».", translationEn: "Abu Huraira reported that al-Aqra' b. Habis saw Allah's Apostle (ﷺ) kissing Hasan. He said: I have ten children, but I have never kissed any one of them, whereupon Allah's Messenger (ﷺ) said: He who does not show mercy (towards his children), no mercy would be shown to him.", translationTr: "Akra' b. Habis Nebi (Sallallahu Aleyhi ve Sellem) Hasan'ı öperken görmüş de: — Benim on çocuğum var, onlardan birini öpmedim, demiş. Bunun üzerine Resulullah (Sallallahu Aleyhi ve Sellem): «Şüphesiz ki merhamet etmeyen merhamet olunmaz.» buyurmuşlar.", translationUr: "اقرع بن حابس رضی اللہ تعالیٰ عنہ نے نبی کریم صلی اللہ علیہ وسلم کو دیکھا، آپ حضرت حسن رضی اللہ تعالیٰ عنہ کو بوسہ دے رہے تھے، انھوں نے کہا : میرے دس بچے ہیں اور میں نے ان میں سے کسی کو کبھی بوسہ نہیں دیا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا؛ \" جو شخص رحم نہیں کرتا اس پر رحم نہیں کیا جائے گا۔\"", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه مسلم (٢٣١٨)", referenceEn: "Sahih Muslim 2318", categoryAr: "الرحمة والرفق", categoryEn: "Mercy & Gentleness", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "147", titleAr: "المرأة والهرة", titleEn: "The Woman and the Cat", titleTr: "Kadın ve Kedi", titleUr: "عورت اور بلی", textAr: "أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ «عُذِّبَتِ امْرَأَةٌ فِي هِرَّةٍ سَجَنَتْهَا حَتَّى مَاتَتْ، فَدَخَلَتْ فِيهَا النَّارَ، لاَ هِيَ أَطْعَمَتْهَا وَلاَ سَقَتْهَا إِذْ حَبَسَتْهَا، وَلاَ هِيَ تَرَكَتْهَا تَأْكُلُ مِنْ خَشَاشِ الأَرْضِ».", translationEn: "Allah's Messenger (ﷺ) said, \"A lady was punished because of a cat which she had imprisoned till it died. She entered the (Hell) Fire because of it, for she neither gave it food nor water as she had imprisoned it, nor set it free to eat from the vermin of the earth.\"", translationTr: "Resulullah Sallallahu Aleyhi ve Sellem şöyle buyurdu: \"Bir kadın ölünceye kadar bağladığı bir kedi sebebiyle azaba uğratıldı ve o kediden dolayı cehennem ateşine girdi. Kediyi hapsettiği halde ona yiyecek de vermedi, içecek bir şey de vermedi. Yerin haşeratından yiyebilsin diye de onu salmadı.\"", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ( بنی اسرائیل کی ) ایک عورت کو ایک بلی کی وجہ سے عذاب دیا گیا تھا جسے اس نے قید کر رکھا تھا جس سے وہ بلی مر گئی تھی اور اس کی سزا میں وہ عورت دوزخ میں گئی۔ جب وہ عورت بلی کو باندھے ہوئے تھی تو اس نے اسے کھانے کے لیے کوئی چیز نہ دی، نہ پینے کے لیے اور نہ اس نے بلی کو چھوڑا ہی کہ وہ زمین کے کیڑے مکوڑے ہی کھا لیتی۔“", narratorAr: "عن عبد الله بن عمر رضي الله عنهما", narratorEn: "Narrated by Abdullah ibn Umar (RA)", referenceAr: "رواه البخاري (٣٤٨٢)", referenceEn: "Sahih al-Bukhari 3482", categoryAr: "الرحمة والرفق", categoryEn: "Mercy & Gentleness", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "148", titleAr: "يسّروا ولا تعسّروا", titleEn: "Make Things Easy, Not Hard", titleTr: "Kolaylaştırın, Zorlaştırmayın", titleUr: "آسانی پیدا کرو، مشکل نہ بناؤ", textAr: "عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ «يَسِّرُوا وَلاَ تُعَسِّرُوا، وَبَشِّرُوا وَلاَ تُنَفِّرُوا».", translationEn: "The Prophet (ﷺ) said, \"Facilitate things to people (concerning religious matters), and do not make it hard for them and give them good tidings and do not make them run away (from Islam)\"", translationTr: "Nebi (Sallallahu aleyhi ve Sellem)'in şöyle söylediğini rivayet etmiştir: \"Kolaylaştırın, zorlaştırmayın. Müjdeleyin, nefret ettirmeyin.\"", translationUr: "رسول اللہ صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا، آسانی کرو اور سختی نہ کرو اور خوش کرو اور نفرت نہ دلاؤ۔", narratorAr: "عن أنس بن مالك رضي الله عنه", narratorEn: "Narrated by Anas ibn Malik (RA)", referenceAr: "رواه البخاري (٦٩)", referenceEn: "Sahih al-Bukhari 69", categoryAr: "الرحمة والرفق", categoryEn: "Mercy & Gentleness", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "149", titleAr: "الراحمون يرحمهم الرحمن", titleEn: "The Merciful Are Shown Mercy", titleTr: "Merhamet Edenlere Rahman Merhamet Eder", titleUr: "رحم کرنے والوں پر رحمن رحم کرتا ہے", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «الرَّاحِمُونَ يَرْحَمُهُمُ الرَّحْمَنُ ارْحَمُوا مَنْ فِي الأَرْضِ يَرْحَمْكُمْ مَنْ فِي السَّمَاءِ الرَّحِمُ شُجْنَةٌ مِنَ الرَّحْمَنِ فَمَنْ وَصَلَهَا وَصَلَهُ اللَّهُ وَمَنْ قَطَعَهَا قَطَعَهُ اللَّهُ».", translationEn: "Abdullah bin 'Amr narrated that the Messenger of Allah said: \"The merciful are shown mercy by Ar-Rahman. Be merciful on the earth, and you will be shown mercy from Who is above the heavens. The womb is named after Ar-Rahman, so whoever connects it, Allah connects him, and whoever severs it, Allah severs him.\"", translationTr: "Rasulullah (sallallahu aleyhi ve sellem) şöyle buyurdu: “Merhametlilere Rahman olan Allah merhamet eder. Siz yeryüzündekilere acıyın ki göktekiler de size acısın Rahm; Rahman isminden bir damardır; Her kim bağları koparmaz ilgiyi kesmezse Allah da onu rahmetine ulaştırır. Her kim de bağları koparırsa Allah da o kimseden rahmetini keser.”", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”رحم کرنے والوں پر رحمن رحم کرتا ہے، تم لوگ زمین والوں پر رحم کرو تم پر آسمان والا رحم کرے گا، رحم رحمن سے مشتق ( نکلا ) ہے، جس نے اس کو جوڑا اللہ اس کو ( اپنی رحمت سے ) جوڑے گا اور جس نے اس کو توڑا اللہ اس کو اپنی رحمت سے کاٹ دے گا“۔", narratorAr: "عن عبد الله بن عمرو رضي الله عنهما", narratorEn: "Narrated by Abdullah ibn Amr (RA)", referenceAr: "رواه الترمذي (١٩٢٤)، وصححه الألباني", referenceEn: "Jami at-Tirmidhi 1924 (Sahih - al-Albani)", categoryAr: "الرحمة والرفق", categoryEn: "Mercy & Gentleness", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "150", titleAr: "إن من أحبكم إليّ أحسنكم أخلاقًا", titleEn: "Among the Dearest: Those with the Best Character", titleTr: "En Sevdiklerimden: Ahlakı En Güzel Olanlar", titleUr: "میرے محبوب ترین لوگوں میں: بہترین اخلاق والے", textAr: "إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم لَمْ يَكُنْ فَاحِشًا وَلاَ مُتَفَحِّشًا وَقَالَ «إِنَّ مِنْ أَحَبِّكُمْ إِلَىَّ أَحْسَنَكُمْ أَخْلاَقًا».", translationEn: "Allah's Messenger (ﷺ) neither talked in an insulting manner nor did he ever speak evil intentionally. He used to say, \"The most beloved to me amongst you is the one who has the best character and manners.\"", translationTr: "Resulullah Sallallahu Aleyhi ve Sellem ne çirkin konuşur, ne de çirkin konuşmaya gayret gösterirdi. Yine şöyle buyurmuştur: Aranızda en sevdiklerim ahlakı en güzel olanlarınızdır.", translationUr: "", narratorAr: "عن عبد الله بن عمرو رضي الله عنهما", narratorEn: "Narrated by Abdullah ibn Amr (RA)", referenceAr: "رواه البخاري (٣٧٥٩)", referenceEn: "Sahih al-Bukhari 3759", categoryAr: "حسن الخلق", categoryEn: "Good Character", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "151", titleAr: "البر حسن الخلق", titleEn: "Righteousness Is Good Character", titleTr: "İyilik Güzel Ahlaktır", titleUr: "نیکی اچھے اخلاق کا نام ہے", textAr: "سَأَلْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم عَنِ الْبِرِّ وَالإِثْمِ فَقَالَ «الْبِرُّ حُسْنُ الْخُلُقِ وَالإِثْمُ مَا حَاكَ فِي صَدْرِكَ وَكَرِهْتَ أَنْ يَطَّلِعَ عَلَيْهِ النَّاسُ».", translationEn: "Nawwas b. Sam'an al-Ansari reported: I asked Allah's Messenger (ﷺ) about virtue and vice. He said: Virtue is a kind disposition and vice is what rankles in your heart and that you disapprove that people should come to know of it.", translationTr: "Resûlullah (Sallallahu Aleyhi ve Sellem)'e birr ve günah'ı sordum da şöyle buyurdular: «Birr, ahlakın güzelliğidir. Günah ise, kalbinde gıcık yapan ve başkalarının muttali olmasından hoşlanmadığın şeydir.»", translationUr: "میں نے رسول اللہ صلی اللہ علیہ وسلم سے نیکی اور گناہ کے بارے میں سوال کیا تو آپ نے فرمایا : \" نیکی اچھا خلق ہے، اور گناہ وہ ہے جو تمہارے دل میں کھٹکے اور تم ناپسند کرو کہ لوگوں کو اس کا پتہ چلے۔\"", narratorAr: "عن النواس بن سمعان رضي الله عنه", narratorEn: "Narrated by An-Nawwas ibn Sam'an (RA)", referenceAr: "رواه مسلم (٢٥٥٣)", referenceEn: "Sahih Muslim 2553", categoryAr: "حسن الخلق", categoryEn: "Good Character", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "152", titleAr: "أثقل شيء في الميزان", titleEn: "The Heaviest Thing on the Scale", titleTr: "Mizanda En Ağır Gelen", titleUr: "میزان میں سب سے بھاری چیز", textAr: "أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ «مَا شَيْءٌ أَثْقَلُ فِي مِيزَانِ الْمُؤْمِنِ يَوْمَ الْقِيَامَةِ مِنْ خُلُقٍ حَسَنٍ وَإِنَّ اللَّهَ لَيَبْغَضُ الْفَاحِشَ الْبَذِيءَ».", translationEn: "The Messenger of Allah said: \"Nothing is heavier on the believer's Scale on the Day of Judgment than good character. For indeed Allah, Most High, is angered by the shameless obscene person.\"", translationTr: "Nebi (s.a.v.) şöyle buyurmuştur: “Kıyamet günü mü’minin mizanında hiçbirşey güzel ahlaktan daha ağır değildir. Allah kaba ve ahlaksız kişileri asla sevmez.”", translationUr: "نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ”قیامت کے دن مومن کے میزان میں اخلاق حسنہ سے بھاری کوئی چیز نہیں ہو گی اور اللہ تعالیٰ بےحیاء، بدزبان سے نفرت کرتا ہے“۔", narratorAr: "عن أبي الدرداء رضي الله عنه", narratorEn: "Narrated by Abu ad-Darda' (RA)", referenceAr: "رواه الترمذي (٢٠٠٢)، وصححه الألباني", referenceEn: "Jami at-Tirmidhi 2002 (Sahih - al-Albani)", categoryAr: "حسن الخلق", categoryEn: "Good Character", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "153", titleAr: "الوجه الطلق معروف", titleEn: "A Cheerful Face Is a Kindness", titleTr: "Güler Yüz de Bir İyiliktir", titleUr: "خندہ پیشانی بھی نیکی ہے", textAr: "قَالَ لِيَ النَّبِيُّ صلى الله عليه وسلم «لاَ تَحْقِرَنَّ مِنَ الْمَعْرُوفِ شَيْئًا وَلَوْ أَنْ تَلْقَى أَخَاكَ بِوَجْهٍ طَلْقٍ».", translationEn: "Abu Dharr reported: Allah's Apostle (ﷺ) said to me: Don't consider anything insignificant out of good things even if it is that you meet your brother with a cheerful countenance.", translationTr: "Nebi (Sallallahu Aleyhi ve Sellem): «Sakın maruftan hiç bir şeyi hakir görme! Velev din kardeşini güler yüzle karşılaman olsun!» buyurdular.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا : \" نیکی میں کسی چیز کو حقیر نہ سمجھو، چاہے یہی ہو کہ تم اپنے ( مسلمان ) بھائی کو کھلتے ہوئے چہرے سے ملو۔\"", narratorAr: "عن أبي ذر رضي الله عنه", narratorEn: "Narrated by Abu Dharr (RA)", referenceAr: "رواه مسلم (٢٦٢٦)", referenceEn: "Sahih Muslim 2626", categoryAr: "حسن الخلق", categoryEn: "Good Character", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "154", titleAr: "فليقل خيرًا أو ليصمت", titleEn: "Speak Good or Stay Silent", titleTr: "Ya Hayır Söylesin ya da Sussun", titleUr: "اچھی بات کہے یا خاموش رہے", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلاَ يُؤْذِ جَارَهُ، وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلْيُكْرِمْ ضَيْفَهُ، وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ».", translationEn: "Allah's Messenger (ﷺ) said, \"Anybody who believes in Allah and the Last Day should not harm his neighbor, and anybody who believes in Allah and the Last Day should entertain his guest generously and anybody who believes in Allah and the Last Day should talk what is good or keep quiet. (i.e. abstain from all kinds of evil and dirty talk)\"", translationTr: "Resulullah Sallallahu Aleyhi ve Sellem şöyle buyurdu: Allah'a ve ahiret gününe iman eden bir kimse komşusuna eziyet vermesin. Allah'a ve ahiret gününe iman eden bir kimse misafirine ikram etsin. Allah'a ve ahiret gününe iman eden bir kimse ya hayır söylesin yahut sussun.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ”جو کوئی اللہ اور آخرت کے دن پر ایمان رکھتا ہو وہ اپنے پڑوسی کو تکلیف نہ پہنچائے اور جو کوئی اللہ اور آخرت کے دن پر ایمان رکھتا ہو وہ اپنے مہمان کی عزت کرے اور جو کوئی اللہ اور آخرت کے دن پر ایمان رکھتا ہو وہ اچھی بات زبان سے نکالے ورنہ خاموش رہے۔“", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (٦٠١٨)", referenceEn: "Sahih al-Bukhari 6018", categoryAr: "حسن الخلق", categoryEn: "Good Character", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "155", titleAr: "الذاكر كالحي", titleEn: "The One Who Remembers Is Alive", titleTr: "Zikreden Diri Gibidir", titleUr: "ذکر کرنے والا زندہ کی مانند ہے", textAr: "قَالَ النَّبِيُّ صلى الله عليه وسلم «مَثَلُ الَّذِي يَذْكُرُ رَبَّهُ وَالَّذِي لاَ يَذْكُرُ مَثَلُ الْحَىِّ وَالْمَيِّتِ».", translationEn: "The Prophet (ﷺ) said, \"The example of the one who celebrates the Praises of his Lord (Allah) in comparison to the one who does not celebrate the Praises of his Lord, is that of a living creature compared to a dead one.\"", translationTr: "Resulullah Sallallahu Aleyhi ve Sellem şöyle buyurmuştur: \"Allah'ı zikreden ile zikretmeyen arasındaki fark ölü ile diri arasındaki fark gibidir.\"", translationUr: "نبی کریم صلی اللہ علیہ وسلم نے فرمایا ”اس شخص کی مثال جو اپنے رب کو یاد کرتا ہے اور اس کی مثال جو اپنے رب کو یاد نہیں کرتا زندہ اور مردہ جیسی ہے۔“", narratorAr: "عن أبي موسى الأشعري رضي الله عنه", narratorEn: "Narrated by Abu Musa al-Ash'ari (RA)", referenceAr: "رواه البخاري (٦٤٠٧)", referenceEn: "Sahih al-Bukhari 6407", categoryAr: "الذكر", categoryEn: "Remembrance", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "156", titleAr: "أحب الكلام إلى الله", titleEn: "The Words Allah Loves Most", titleTr: "Allah'ın En Sevdiği Sözler", titleUr: "اللہ کو سب سے محبوب کلمات", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «أَحَبُّ الْكَلاَمِ إِلَى اللَّهِ أَرْبَعٌ سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلاَ إِلَهَ إِلاَّ اللَّهُ وَاللَّهُ أَكْبَرُ. لاَ يَضُرُّكَ بَأَيِّهِنَّ بَدَأْتَ».", translationEn: "Samura b. Jundub reported: The Messenger of Allah (peace and blessings of Allah be upon him) said \"The dearest phrases to Allah are four: Subhan Allah (Hallowed be Allah), Al-Hamdulillah (Praise be to Allah), La ilaha illa-Allah (There is no deity but Allah), Allahu Akbar (Allah is Greater). There is no harm for you in which of them begin with (while remembering Allah)\"", translationTr: "Resûlullah (Sallallahu Aleyhi ve Sellem): «Allah indinde sözün en makbulü dörtdür: Allah'ı tenzih ederim=(SUBHANALLAH), hamd Allah'a mahsustur=(ELHAMDU LİLLAH), Allah'dan başka ilâh yoktur ve Allah en büyüktür=(LA İLAHE İLLALLAHU VALLAHU EKBER) (sözleri). Bunların hangisinden başlasan sana zarar etmez.»", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”سب سے زیادہ پسند اللہ تعالیٰ کو چار کلمے ہیں «سُبْحَانَ اللهِ، وَالْحَمْدُ لِلَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكْبَرُ» ان میں سے جس کو چاہے پہلے کہے۔“", narratorAr: "عن سمرة بن جندب رضي الله عنه", narratorEn: "Narrated by Samurah ibn Jundub (RA)", referenceAr: "رواه مسلم (٢١٣٧)", referenceEn: "Sahih Muslim 2137", categoryAr: "الذكر", categoryEn: "Remembrance", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "157", titleAr: "بلّغوا عني ولو آية", titleEn: "Pass It On, Even a Single Verse", titleTr: "Benden Bir Ayet Bile Olsa Tebliğ Edin", titleUr: "میری طرف سے پہنچاؤ خواہ ایک آیت ہی ہو", textAr: "أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ «بَلِّغُوا عَنِّي وَلَوْ آيَةً، وَحَدِّثُوا عَنْ بَنِي إِسْرَائِيلَ وَلاَ حَرَجَ، وَمَنْ كَذَبَ عَلَىَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ».", translationEn: "The Prophet (ﷺ) said, \"Convey (my teachings) to the people even if it were a single sentence, and tell others the stories of Bani Israel (which have been taught to you), for it is not sinful to do so. And whoever tells a lie on me intentionally, will surely take his place in the (Hell) Fire.\"", translationTr: "Nebi Sallallahu Aleyhi ve Sellem şöyle buyurdu: \"Benden bir ayet dahi olsa tebliğ ediniz. İsrailoğullarından nakledebilirsiniz, bunda bir mahzur yoktur. Kasten aleyhime yalan söyleyen kimse de cehennemdeki yerine hazırlansın.\"", translationUr: "نبی کریم صلی اللہ علیہ وسلم نے فرمایا ”میرا پیغام لوگوں کو پہنچاؤ! اگرچہ ایک ہی آیت ہو اور بنی اسرائیل کے واقعات تم بیان کر سکتے ہو، ان میں کوئی حرج نہیں اور جس نے مجھ پر قصداً جھوٹ باندھا تو اسے اپنے جہنم کے ٹھکانے کے لیے تیار رہنا چاہئے۔“", narratorAr: "عن عبد الله بن عمرو رضي الله عنهما", narratorEn: "Narrated by Abdullah ibn Amr (RA)", referenceAr: "رواه البخاري (٣٤٦١)", referenceEn: "Sahih al-Bukhari 3461", categoryAr: "العلم", categoryEn: "Knowledge", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "158", titleAr: "السواك", titleEn: "The Tooth-Stick (Siwak)", titleTr: "Misvak", titleUr: "مسواک", textAr: "أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ «لَوْلاَ أَنْ أَشُقَّ عَلَى أُمَّتِي لأَمَرْتُهُمْ بِالسِّوَاكِ».", translationEn: "Allah's Messenger (ﷺ) said, \"Were I not afraid that it would be hard on my followers, I would order them to use the siwak (as obligatory, for cleaning the teeth)\"", translationTr: "Resulullah Sallallahu Aleyhi ve Sellem \"Ümmetime meşakkat vermiş olmasaydım, onlara mutlaka misvak kullanmalarını emrederdim\" buyurmuştur.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ”اگر میری امت پر شاق نہ ہوتا تو میں ان پر مسواک کرنا واجب قرار دیتا۔“", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (٧٢٤٠)", referenceEn: "Sahih al-Bukhari 7240", categoryAr: "الطهارة", categoryEn: "Purity", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "159", titleAr: "الوضوء يمحو الخطايا", titleEn: "Wudu Washes Away Sins", titleTr: "Abdest Günahları Giderir", titleUr: "وضو گناہوں کو دھو دیتا ہے", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «مَنْ تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ خَرَجَتْ خَطَايَاهُ مِنْ جَسَدِهِ حَتَّى تَخْرُجَ مِنْ تَحْتِ أَظْفَارِهِ».", translationEn: "Uthman b. 'Affan reported: The Messenger of Allah (ﷺ) said: He who performed ablution well, his sins would come out from his body, even coming out from under his nails.", translationTr: "Resulullah (Sallallahu aleyhi ve Sellem): \"Kim güzel bir şekilde abdest alırsa günahları tırnaklarının altından çıkmaya varıncaya kadar vücudundan çıkar\" buyurdu.", translationUr: "رسول اللہ ﷺ نے فرمایا : ’’جس نے وضو کیا اور خوب اچھی طرح وضو کیا، تو اس کے جسم سے اس کےگناہ خارج ہو جاتے ہیں حتی کہ اس کے ناخنوں کےنیچے سے بھی نکل جاتے ہیں۔‘‘", narratorAr: "عن عثمان بن عفان رضي الله عنه", narratorEn: "Narrated by Uthman ibn Affan (RA)", referenceAr: "رواه مسلم (٢٤٥)", referenceEn: "Sahih Muslim 245", categoryAr: "الطهارة", categoryEn: "Purity", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "160", titleAr: "الطهور شطر الإيمان", titleEn: "Purity Is Half of Faith", titleTr: "Temizlik İmanın Yarısıdır", titleUr: "پاکیزگی نصف ایمان ہے", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «الطُّهُورُ شَطْرُ الإِيمَانِ وَالْحَمْدُ لِلَّهِ تَمْلأُ الْمِيزَانَ. وَسُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ تَمْلآنِ - أَوْ تَمْلأُ - مَا بَيْنَ السَّمَوَاتِ وَالأَرْضِ وَالصَّلاَةُ نُورٌ وَالصَّدَقَةُ بُرْهَانٌ وَالصَّبْرُ ضِيَاءٌ وَالْقُرْآنُ حُجَّةٌ لَكَ أَوْ عَلَيْكَ كُلُّ النَّاسِ يَغْدُو فَبَائِعٌ نَفْسَهُ فَمُعْتِقُهَا أَوْ مُوبِقُهَا».", translationEn: "Abu Malik at-Ash'ari reported: The Messenger of Allah (ﷺ) said: Cleanliness is half of faith and al-Hamdu Lillah (all praise and gratitude is for Allah alone) fills the scale, and Subhan Allah (Glory be to Allah) and al-Hamdu Lillah fill up what is between the heavens and the earth, and prayer is a light, and charity is proof (of one's faith) and endurance is a brightness and the Holy Qur'an is a proof on your behalf or against you. All men go out early in the morning and sell themselves, thereby setting themselves free or destroying themselves.", translationTr: "Rasülullah (Sallallahu aleyhi ve Sellem) şöyle buyurdu: \"Abdest imanın yarısıdır. Elhamdulillah mizanı doldurur. Subhanallah ve'l-hamdulillah da göklerle yer arasını doldururlar -yahut doldurur-, namaz bir nurdur, sadaka bir burhandır, sabır bir ışıktır, Kur'an senin lehine ya da aleyhine bir huccettir. Bütün insanlar sabah gider ve nefsini satar. Bu sebeple ya onu hürriyetine kavuşturur (azad eder) yahut onu helake götürür.\"", translationUr: "رسول اللہ ﷺ نے فرمایا : ’’پاکیزگی نصف ایمان ہے۔ الحمد لله ترازو کو بھر دیتا ہے۔ سبحان الله اور الحمد لله آسمانوں سے زمین تک کی وسعت کو بھر دیتے ہیں۔ نماز نور ہے۔ صدقہ دلیل ہے۔ صبر روشنی ہے۔ قرآن تمہارے حق میں یا تمہارے خلاف حجت ہے ہر انسان دن کا آغاز کرتا ہے تو ( کچھ اعمال کے عوض ) اپنا سودا کرتا ہے، پھر یا تو خود آزاد کرنےوالا ہوتا ہے خود کو تباہ کرنے والا۔‘‘", narratorAr: "عن أبي مالك الأشعري رضي الله عنه", narratorEn: "Narrated by Abu Malik al-Ash'ari (RA)", referenceAr: "رواه مسلم (٢٢٣)", referenceEn: "Sahih Muslim 223", categoryAr: "الطهارة", categoryEn: "Purity", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "161", titleAr: "ما ينفع بعد الموت", titleEn: "What Still Benefits After Death", titleTr: "Ölümden Sonra da Fayda Verenler", titleUr: "موت کے بعد بھی فائدہ دینے والی چیزیں", textAr: "أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ «إِذَا مَاتَ الإِنْسَانُ انْقَطَعَ عَنْهُ عَمَلُهُ إِلاَّ مِنْ ثَلاَثَةٍ إِلاَّ مِنْ صَدَقَةٍ جَارِيَةٍ أَوْ عِلْمٍ يُنْتَفَعُ بِهِ أَوْ وَلَدٍ صَالِحٍ يَدْعُو لَهُ».", translationEn: "Abu Huraira (Allah be pleased with him) reported Allah's Messenger (ﷺ) as saying: When a man dies, his acts come to an end, but three, recurring charity, or knowledge (by which people) benefit, or a pious son, who prays for him (for the deceased)", translationTr: "Resulullah (Sallallahu Aleyhi ve Sellem): «İnsan öldüğü vakit bütün amelleri ondan kesilir. Yalnız üç şeyden: sadaka-i cariyeden, faydalanılan ilimden ve kendisine dua eden salih evladdan kesilmez.» buyurmuşlar.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب انسان فوت ہو جائے تو اس کا عمل منقطع ہو جاتا ہے سوائے تین اعمال کے ( وہ منقطع نہیں ہوتے ) : صدقہ جاریہ یا ایسا علم جس سے فائدہ اٹھایا جائے یا نیک بیٹا جو اس کے لیے دعا کرے۔\"", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه مسلم (١٦٣١)", referenceEn: "Sahih Muslim 1631", categoryAr: "الآخرة", categoryEn: "The Hereafter", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "162", titleAr: "ما يبقى مع الميت", titleEn: "What Stays with the Dead", titleTr: "Ölüyle Birlikte Kalan", titleUr: "میت کے ساتھ کیا رہ جاتا ہے", textAr: "قَالَ رَسُولُ اللَّهُ صلى الله عليه وسلم «يَتْبَعُ الْمَيِّتَ ثَلاَثَةٌ، فَيَرْجِعُ اثْنَانِ وَيَبْقَى مَعَهُ وَاحِدٌ، يَتْبَعُهُ أَهْلُهُ وَمَالُهُ وَعَمَلُهُ، فَيَرْجِعُ أَهْلُهُ وَمَالُهُ، وَيَبْقَى عَمَلُهُ».", translationEn: "Allah's Messenger (ﷺ) said, \"When carried to his grave, a dead person is followed by three, two of which return (after his burial) and one remains with him: his relative, his property, and his deeds follow him; relatives and his property go back while his deeds remain with him.\"", translationTr: "Resulullah Sallallahu Aleyhi ve Sellem şöyle buyurmuştur: \"Ölüyü üç şey takip edip kabre kadar gider ve ikisi tekrar geri döner. Biri onunla birlikte kalır: Ölüyü ailesi, malı ve ameli takip eder. Neticede ailesi ve malı geriye döner, kendisiyle beraber sadece ameli kalır.\"", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ”میت کے ساتھ تین چیزیں چلتی ہیں دو تو واپس آ جاتی ہیں صرف ایک کام اس کے ساتھ رہ جاتا ہے، اس کے ساتھ اس کے گھر والے اس کا مال اور اس کا عمل چلتا ہے اس کے گھر والے اور مال تو واپس آ جاتا ہے اور اس کا عمل اس کے ساتھ باقی رہ جاتا ہے۔“", narratorAr: "عن أنس بن مالك رضي الله عنه", narratorEn: "Narrated by Anas ibn Malik (RA)", referenceAr: "رواه البخاري (٦٥١٤)", referenceEn: "Sahih al-Bukhari 6514", categoryAr: "الآخرة", categoryEn: "The Hereafter", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "163", titleAr: "كن في الدنيا كأنك غريب", titleEn: "Be in This World Like a Stranger", titleTr: "Dünyada Bir Garip Gibi Ol", titleUr: "دنیا میں ایک اجنبی کی طرح رہو", textAr: "أَخَذَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِمَنْكِبِي فَقَالَ «كُنْ فِي الدُّنْيَا كَأَنَّكَ غَرِيبٌ، أَوْ عَابِرُ سَبِيلٍ». وَكَانَ ابْنُ عُمَرَ يَقُولُ إِذَا أَمْسَيْتَ فَلاَ تَنْتَظِرِ الصَّبَاحَ، وَإِذَا أَصْبَحْتَ فَلاَ تَنْتَظِرِ الْمَسَاءَ، وَخُذْ مِنْ صِحَّتِكَ لِمَرَضِكَ، وَمِنْ حَيَاتِكَ لِمَوْتِكَ.", translationEn: "'Abdullah bin 'Umar said, \"Allah's Messenger (ﷺ) took hold of my shoulder and said, 'Be in this world as if you were a stranger or a traveler.\" The sub-narrator added: Ibn 'Umar used to say, \"If you survive till the evening, do not expect to be alive in the morning, and if you survive till the morning, do not expect to be alive in the evening, and take from your health for your sickness, and (take) from your life for your death.\"", translationTr: "Resulullah Sallallahu Aleyhi ve Sellem omzumu tutup \"Dünyada garip veya yolcu gibi ol\" buyurdu. İbn Ömer hep \"Akşama kavuştuğunda sabahı, sabaha ulaştığında akşamı bekleme, sağlığında hastalığın için, yaşamında da ölümün için bir şeyler yap\" derdi.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے میرا شانہ پکڑ کر فرمایا ”دنیا میں اس طرح ہو جا جیسے تو مسافر یا راستہ چلنے والا ہو۔“ عبداللہ بن عمر رضی اللہ عنہما فرمایا کرتے تھے شام ہو جائے تو صبح کے منتظر نہ رہو اور صبح کے وقت شام کے منتظر نہ رہو، اپنی صحت کو مرض سے پہلے غنیمت جانو اور زندگی کو موت سے پہلے۔", narratorAr: "عن عبد الله بن عمر رضي الله عنهما", narratorEn: "Narrated by Abdullah ibn Umar (RA)", referenceAr: "رواه البخاري (٦٤١٦)", referenceEn: "Sahih al-Bukhari 6416", categoryAr: "الآخرة", categoryEn: "The Hereafter", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "164", titleAr: "من أطاعني دخل الجنة", titleEn: "Whoever Obeys Me Enters Paradise", titleTr: "Bana İtaat Eden Cennete Girer", titleUr: "جس نے میری اطاعت کی وہ جنت میں داخل ہوگا", textAr: "أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ «كُلُّ أُمَّتِي يَدْخُلُونَ الْجَنَّةَ، إِلاَّ مَنْ أَبَى». قَالُوا يَا رَسُولَ اللَّهِ وَمَنْ يَأْبَى قَالَ «مَنْ أَطَاعَنِي دَخَلَ الْجَنَّةَ، وَمَنْ عَصَانِي فَقَدْ أَبَى».", translationEn: "Allah's Messenger (ﷺ) said, \"All my followers will enter Paradise except those who refuse.\" They said, \"O Allah's Messenger (ﷺ)! Who will refuse?\" He said, \"Whoever obeys me will enter Paradise, and whoever disobeys me is the one who refuses (to enter it)\"", translationTr: "Resulullah Sallallahu Aleyhi ve Sellem şöyle buyurmuştur: \"Ümmetimin herbir ferdi -kaçınanlar hariç- cennete girecektir.\" Orada bulunanlar \"Ya Resulallah! Kaçınan kimdir?\" deyince, Resulullah Sallallahu Aleyhi ve Sellem \"Bana itaat eden cennete girecektir, bana karşı gelen kaçınmıştır\" diye cevapladı.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ”ساری امت جنت میں جائے گی سوائے ان کے جنہوں نے انکار کیا۔“ صحابہ نے عرض کیا: یا رسول اللہ! انکار کون کرے گا؟ فرمایا ”جو میری اطاعت کرے گا وہ جنت میں داخل ہو گا اور جو میری نافرمانی کرے گا اس نے انکار کیا۔“", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (٧٢٨٠)", referenceEn: "Sahih al-Bukhari 7280", categoryAr: "اتباع السنة", categoryEn: "Following the Sunnah", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "165", titleAr: "محبة النبي ﷺ من الإيمان", titleEn: "Loving the Prophet Is Part of Faith", titleTr: "Peygamber'i Sevmek İmandandır", titleUr: "نبی ﷺ سے محبت ایمان کا حصہ ہے", textAr: "قَالَ النَّبِيُّ صلى الله عليه وسلم «لاَ يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَالِدِهِ وَوَلَدِهِ وَالنَّاسِ أَجْمَعِينَ».", translationEn: "The Prophet (ﷺ) said \"None of you will have faith till he loves me more than his father, his children and all mankind.\"", translationTr: "Nebi (Sallallahu aleyhi ve Sellem) şöyle buyurmuştur: \"Hiçbiriniz, beni ana-babasından, çoluk çocuğundan ve bütün insanlardan daha çok sevmedikçe iman etmiş olmaz.\"", translationUr: "نبی کریم صلی اللہ علیہ وسلم نے فرمایا تم میں سے کوئی شخص ایماندار نہ ہو گا جب تک اس کے والد اور اس کی اولاد اور تمام لوگوں سے زیادہ اس کے دل میں میری محبت نہ ہو جائے۔", narratorAr: "عن أنس بن مالك رضي الله عنه", narratorEn: "Narrated by Anas ibn Malik (RA)", referenceAr: "رواه البخاري (١٥)", referenceEn: "Sahih al-Bukhari 15", categoryAr: "الإيمان والنية", categoryEn: "Faith & Intention", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "166", titleAr: "شعب الإيمان", titleEn: "The Branches of Faith", titleTr: "İmanın Şubeleri", titleUr: "ایمان کی شاخیں", textAr: "عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ «الإِيمَانُ بِضْعٌ وَسِتُّونَ شُعْبَةً، وَالْحَيَاءُ شُعْبَةٌ مِنَ الإِيمَانِ».", translationEn: "The Prophet (ﷺ) said, \"Faith (Belief) consists of more than sixty branches (i.e. parts). And Haya (This term \"Haya\" covers a large number of concepts which are to be taken together; amongst them are self respect, modesty, bashfulness, and scruple, etc.) is a part of faith.\"", translationTr: "Nebiyy-i Muhterem sallallahu aleyhi ve sellem buyurdu ki: İman altmış bu kadar şubedir. Haya da iman’ın bir şubesidir.", translationUr: "آپ صلی اللہ علیہ وسلم نے فرمایا کہ ایمان کی ساٹھ سے کچھ اوپر شاخیں ہیں۔ اور حیاء ( شرم ) بھی ایمان کی ایک شاخ ہے۔", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (٩)", referenceEn: "Sahih al-Bukhari 9", categoryAr: "الإيمان والنية", categoryEn: "Faith & Intention", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "167", titleAr: "حلاوة الإيمان", titleEn: "The Sweetness of Faith", titleTr: "İmanın Tadı", titleUr: "ایمان کی مٹھاس", textAr: "عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ «ثَلاَثٌ مَنْ كُنَّ فِيهِ وَجَدَ حَلاَوَةَ الإِيمَانِ مَنْ كَانَ اللَّهُ وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا، وَمَنْ أَحَبَّ عَبْدًا لاَ يُحِبُّهُ إِلاَّ لِلَّهِ، وَمَنْ يَكْرَهُ أَنْ يَعُودَ فِي الْكُفْرِ بَعْدَ إِذْ أَنْقَذَهُ اللَّهُ، كَمَا يَكْرَهُ أَنْ يُلْقَى فِي النَّارِ».", translationEn: "The Prophet (ﷺ) said, \"Whoever possesses the following three qualities will taste the sweetness of faith: 1. The one to whom Allah and His Apostle become dearer than anything else. 2. Who loves a person and he loves him only for Allah's sake. 3. Who hates to revert to disbelief (Atheism) after Allah has brought (saved) him out from it, as he hates to be thrown in fire.\"", translationTr: "Peygamber şöyle buyurdu: Şu üç şey kimde olursa, o imanın tadını bulur: 1. Allah ve Resûlü'nü her şeyden daha çok sevmek, 2. Sevdiği kişiyi yalnızca Allah için sevmek, 3. Allah kendisini küfürden kurtardıktan sonra yeniden küfre (inkarcılığa) dönmeyi, ateşe atılmak kadar kötü görmek.", translationUr: "نبی کریم صلی اللہ علیہ وسلم سے نقل کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا، جس شخص میں یہ تین باتیں ہوں گی وہ ایمان کا مزہ پالے گا، ایک یہ کہ وہ شخص جسے اللہ اور اس کا رسول ان کے ماسوا سے زیادہ عزیز ہوں اور دوسرے یہ کہ جو کسی بندے سے محض اللہ ہی کے لیے محبت کرے اور تیسری بات یہ کہ جسے اللہ نے کفر سے نجات دی ہو، پھر دوبارہ کفر اختیار کرنے کو وہ ایسا برا سمجھے جیسا آگ میں گر جانے کو برا جانتا ہے۔", narratorAr: "عن أنس بن مالك رضي الله عنه", narratorEn: "Narrated by Anas ibn Malik (RA)", referenceAr: "رواه البخاري (٢١)", referenceEn: "Sahih al-Bukhari 21", categoryAr: "الإيمان والنية", categoryEn: "Faith & Intention", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "168", titleAr: "من رضي بالله ربًا", titleEn: "Content with Allah as Lord", titleTr: "Rab Olarak Allah'tan Razı Olan", titleUr: "جو اللہ کے رب ہونے پر راضی ہوا", textAr: "سَمِعَ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ «ذَاقَ طَعْمَ الإِيمَانِ مَنْ رَضِيَ بِاللَّهِ رَبًّا وَبِالإِسْلاَمِ دِينًا وَبِمُحَمَّدٍ رَسُولاً».", translationEn: "It is narrated on the authority of 'Abbas b. 'Abdul-Muttalib that he heard the Messenger of Allah saying: He has found the taste of faith (iman) who is content with Allah as his Lord, with Islam as his religion (code of life) and with Muhammad (ﷺ) as his Prophet.", translationTr: "Resulullah (Sallallahu aleyhi ve Sellem)'i şöyle buyururken dinlemiştir: \"Rab olarak Allah'a, din olarak İslam'a, Resul olarak Muhammed'e razı olan kimse imanın tadını almış olur.\"", translationUr: "انہوں نے رسول اللہ ﷺ سے سنا، آپ فرما رہے تھے : ’’اس شخص نے ایمان کا مزہ چکھ لیا جو اللہ کے رب، اسلام کو دین اور محمدﷺ کے رسول ہونے پر ( دل سے ) راضی ہو گیا۔‘‘", narratorAr: "عن العباس بن عبد المطلب رضي الله عنه", narratorEn: "Narrated by Al-Abbas ibn Abd al-Muttalib (RA)", referenceAr: "رواه مسلم (٣٤)", referenceEn: "Sahih Muslim 34", categoryAr: "الإيمان والنية", categoryEn: "Faith & Intention", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "169", titleAr: "في ذمة الله", titleEn: "Under Allah's Protection", titleTr: "Allah'ın Himayesinde", titleUr: "اللہ کی حفاظت میں", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «مَنْ صَلَّى الصُّبْحَ فَهُوَ فِي ذِمَّةِ اللَّهِ فَلاَ يَطْلُبَنَّكُمُ اللَّهُ مِنْ ذِمَّتِهِ بِشَىْءٍ فَيُدْرِكَهُ فَيَكُبَّهُ فِي نَارِ جَهَنَّمَ».", translationEn: "Jundab b. 'Abdullah reported Allah's Messenger (ﷺ) as saying: He who prayed the morning prayer (in congregation) he is in fact under the protection of Allah. And it can never happen that Allah should demand anything from you in connection with the protection (that He guarantees) and one should not get it. He would then throw him in the fire of Hell.", translationTr: "Resulullah (Sallallahu Aleyhi ve Sellem): «Her kim sabah namazını cemaatla kılarsa, o kimse Allah'ın zimmetindedir. Sakın Allah zimmetine âid bir şey'den dolayı sizî talep etmesin. Talep ettiği kimseyi de yetişerek, cehennem ateşine tepetaklak atmasın!» buyurdular.", translationUr: "رسول اللہ ﷺ نے فرمایا : ’’جس شخص نے صبح کی نماز پڑھی و ہ اللہ تعالیٰ کی ذمہ داری ( امان ) میں ہے۔ تو ایسانہ ہو کہ ( ایسے شخص کو کسی طرح نقصان پہنچانے کی بناپر ) اللہ تعالیٰ تم ( میں سے کسی شخص ) سے اپنے ذمے کے بارے میں کسی چیز کا مطالبہ کرے، پھر وہ اسے پکڑ لے، پھر اسے اوندھے منہ جہنم میں ڈال دے۔‘‘", narratorAr: "عن جندب بن عبد الله رضي الله عنه", narratorEn: "Narrated by Jundub ibn Abdullah (RA)", referenceAr: "رواه مسلم (٦٥٧)", referenceEn: "Sahih Muslim 657", categoryAr: "الصلاة", categoryEn: "Prayer", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "170", titleAr: "الصلاة عهد بيننا", titleEn: "Prayer Is the Line Between", titleTr: "Namaz Ayırt Edicidir", titleUr: "نماز فرق کرنے والی ہے", textAr: "سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ «بَيْنَ الرَّجُلِ وَبَيْنَ الشِّرْكِ وَالْكُفْرِ تَرْكُ الصَّلاَةِ».", translationEn: "It is narrated on the authority of Abu Zubair that he heard Jabir b. 'Abdullah saying. I heard the Messenger of Allah (may peace and blessings be upon him) observing this: Between man and polytheism and unbelief is the abandonment of salat.", translationTr: "Resûlullah (Sallallahu aleyhi ve Sellem)'i: \"Kişi ile şirk ve küfür arasında namazın terk edilmesi vardır\" buyururken dinledim.", translationUr: "میں نے رسول اللہ ﷺ کویہ فرماتے ہوئے سنا : ’’ آدمی اور شرک و کفر کے درمیان ( فاصلہ مٹانے والا عمل ) نماز چھوڑنا ہے۔ ‘‘ ( اس روایت میں إن’’بےشک ‘‘ کا لفظ نہیں، باقی وہی ہے۔)", narratorAr: "عن جابر بن عبد الله رضي الله عنهما", narratorEn: "Narrated by Jabir ibn Abdullah (RA)", referenceAr: "رواه مسلم (٨٢)", referenceEn: "Sahih Muslim 82", categoryAr: "الصلاة", categoryEn: "Prayer", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "171", titleAr: "تعجيل الفطر", titleEn: "Hastening to Break the Fast", titleTr: "İftarı Acele Ettirmek", titleUr: "افطار میں جلدی", textAr: "أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ «لاَ يَزَالُ النَّاسُ بِخَيْرٍ مَا عَجَّلُوا الْفِطْرَ».", translationEn: "Allah's Messenger (ﷺ) said, \"The people will remain on the right path as long as they hasten the breaking of the fast.\"", translationTr: "Nebi Sallallahu Aleyhi ve Sellem şöyle buyurmuştur; İftar vakti girer girmez oruçlarını açtıkları sürece insanlar hayır üzerindedir.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، میری امت کے لوگوں میں اس وقت تک خیر باقی رہے گی، جب تک وہ افطار میں جلدی کرتے رہیں گے۔", narratorAr: "عن سهل بن سعد رضي الله عنه", narratorEn: "Narrated by Sahl ibn Sa'd (RA)", referenceAr: "رواه البخاري (١٩٥٧)", referenceEn: "Sahih al-Bukhari 1957", categoryAr: "الصيام", categoryEn: "Fasting", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "172", titleAr: "ستّ من شوال", titleEn: "Six Days of Shawwal", titleTr: "Şevval'in Altı Günü", titleUr: "شوال کے چھ روزے", textAr: "أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ «مَنْ صَامَ رَمَضَانَ ثُمَّ أَتْبَعَهُ سِتًّا مِنْ شَوَّالٍ كَانَ كَصِيَامِ الدَّهْرِ».", translationEn: "Abu Ayyub al-Ansari (Allah be pleased with him) reported Allah's Messenger (ﷺ) as saying: He who observed the fast of Ramadan and then followed it with six (fasts) of Shawwal. it would be as if he fasted perpetually.", translationTr: "Resulullah (Sallallahu Aleyhi ve Sellem): — «Her kim ramazan orucunu tutar da sonra Şevval'den altı günü eklerse bu bütün sene oruçlu gibi olur.» buyurmuşlar.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" جس نے رمضا ن کے روزے رکھے۔ پھر اس کے بعد شوال کے چھروزے رکھے تو یہ ( پوراسال ) مسلسل روزے رکھنے کی طرح ہے۔\"", narratorAr: "عن أبي أيوب الأنصاري رضي الله عنه", narratorEn: "Narrated by Abu Ayyub al-Ansari (RA)", referenceAr: "رواه مسلم (١١٦٤)", referenceEn: "Sahih Muslim 1164", categoryAr: "الصيام", categoryEn: "Fasting", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "173", titleAr: "الدالّ على الخير كفاعله", titleEn: "Whoever Points to Good", titleTr: "Hayra Vesile Olan", titleUr: "بھلائی کی طرف رہنمائی کرنے والا", textAr: "جَاءَ رَجُلٌ إِلَى النَّبِيِّ صلى الله عليه وسلم فَقَالَ إِنِّي أُبْدِعَ بِي فَاحْمِلْنِي فَقَالَ «مَا عِنْدِي». فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ أَنَا أَدُلُّهُ عَلَى مَنْ يَحْمِلُهُ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «مَنْ دَلَّ عَلَى خَيْرٍ فَلَهُ مِثْلُ أَجْرِ فَاعِلِهِ».", translationEn: "It has been narrated on the authority of Abu Mas'ud al-Ansari who said: A man came to the Messenger of Allah (ﷺ) and said: My riding beast has been killed, so give me some animal to ride upon. He (the Holy Prophet) said: I have none with me. A man said: Messenger of Allah, I can guide him to one who will provide him with a riding beast. The Messenger of Allah (ﷺ) said: One who guides to something good has a reward similar to that of its doer.", translationTr: "Nebi (Sallalldhu Aleyhi ve Sellem)'e gelerek: Benim hayvanım helak oldu; bana bir binek hayvanı ver! Dedi. Efendimiz: «Bende yok!» buyurdu. Bunun üzerine bir adam: — Yâ Resûlâllah! Ben ona binek hayvanı verecek kimseyi gösteririm! Dedi. Resûlullah (Sallalldhu Aleyhi ve Sellem) «Her kim bir hayra delâlet ederse ona da hayrı yapanın ecri kadar ecir verilir.» buyurdular.", translationUr: "نبی صلی اللہ علیہ وسلم کی خدمت میں آیا اور عرض کی : اللہ کے رسول! میرا سواری کا جانور ضائع ہو گیا ہے، آپ مجھے سواری مہیا کر دیجئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" میرے پاس سواری نہیں ہے۔ \" ایک شخص سے عرض کی : اللہ کے رسول! میں اس کو ایسا شخص بتاتا ہوں جو اسے سواری کا جانور مہیا کر دے گا۔ آپ نے فرمایا : \" جس شخص نے کسی نیکی کا پتہ بتایا، اس کے لیے ( بھی ) نیکی کرنے والے کے جیسا اجر ہے۔\"", narratorAr: "عن أبي مسعود الأنصاري رضي الله عنه", narratorEn: "Narrated by Abu Mas'ud al-Ansari (RA)", referenceAr: "رواه مسلم (١٨٩٣)", referenceEn: "Sahih Muslim 1893", categoryAr: "الصدقة", categoryEn: "Charity", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "174", titleAr: "لا حسد إلا في اثنتين", titleEn: "Envy Is Only for Two", titleTr: "Ancak İki Kişiye Gıpta Edilir", titleUr: "رشک صرف دو پر", textAr: "سَمِعْتُ النَّبِيَّ صلى الله عليه وسلم يَقُولُ «لاَ حَسَدَ إِلاَّ فِي اثْنَتَيْنِ رَجُلٌ آتَاهُ اللَّهُ مَالاً فَسَلَّطَهُ عَلَى هَلَكَتِهِ فِي الْحَقِّ، وَرَجُلٌ آتَاهُ اللَّهُ حِكْمَةً فَهْوَ يَقْضِي بِهَا وَيُعَلِّمُهَا».", translationEn: "I heard the Prophet (ﷺ) saying, \"There is no envy except in two: a person whom Allah has given wealth and he spends it in the right way, and a person whom Allah has given wisdom (i.e. religious knowledge) and he gives his decisions accordingly and teaches it to the others.\"", translationTr: "Resûlullah Sallallahu Aleyhi ve Sellem'i şöyle buyururken işitmiştir: \"Şu iki kimse dışında hiçbir kimseye gıpta edilmez. Bunlardan birincisi; Allah'ın kendisine mal verdiği ve bu mal'ı hakk yolda harcayan kimsedir, ikincisi ise, Allah'ın kendisine hikmet verip buna göre hüküm veren ve bunu (insanlara) öğreten kimsedir.\"", translationUr: "حسد ( رشک ) کرنا صرف دو ہی آدمیوں کے ساتھ جائز ہو سکتا ہے۔ ایک تو اس شخص کے ساتھ جسے اللہ نے مال دیا اور اسے حق اور مناسب جگہوں میں خرچ کرنے کی توفیق دی۔ دوسرے اس شخص کے ساتھ جسے اللہ تعالیٰ نے حکمت ( عقل علم قرآن و حدیث اور معاملہ فہمی ) دی اور وہ اپنی حکمت کے مطابق حق فیصلے کرتا ہے اور لوگوں کو اس کی تعلیم دیتا ہے۔", narratorAr: "عن عبد الله بن مسعود رضي الله عنه", narratorEn: "Narrated by Abdullah ibn Mas'ud (RA)", referenceAr: "رواه البخاري (١٤٠٩)", referenceEn: "Sahih al-Bukhari 1409", categoryAr: "القرآن الكريم", categoryEn: "The Quran", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "175", titleAr: "سبق المفرِّدون", titleEn: "Those Who Remember Allah Much Have Gone Ahead", titleTr: "Müferridler Öne Geçti", titleUr: "ذکر کرنے والے آگے نکل گئے", textAr: "كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَسِيرُ فِي طَرِيقِ مَكَّةَ فَمَرَّ عَلَى جَبَلٍ يُقَالُ لَهُ جُمْدَانُ فَقَالَ «سِيرُوا هَذَا جُمْدَانُ سَبَقَ الْمُفَرِّدُونَ». قَالُوا وَمَا الْمُفَرِّدُونَ يَا رَسُولَ اللَّهِ قَالَ «الذَّاكِرُونَ اللَّهَ كَثِيرًا وَالذَّاكِرَاتُ».", translationEn: "Abu Huraira reported that Allah's Messenger (ﷺ) was travelling along the path leading to Mecca that he happened to pass by a mountain called Jumdan. He said: Proceed on, it is Jumdan, Mufarradun have gone ahead. They (the Companions of the Holy Prophet) said: Allah's Messenger, who are Mufarradun? He said: They are those males and females who remember Allah much.", translationTr: "Resulullah (Sallallahu Aleyhi ve Sellem) Mekke yolunda yürüyordu. Derken Cümdan denilen dağın yanından geçti. Ve: «Yürüyün! Bu Cümdan'dır. Müferridler geçmiştir.» buyurdu. Ashab: — Müferridler nedir yâ Resûlallah? dediler. «Allah'ı çok zikreden erkek ve kadınlardır.» buyurdular.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم مکہ کے ایک راستے پر چلے جا رہے تھے کہ آپ کا ایک پہاڑ کے قریب سے گزر ہوا جس کو جمدان کہا جاتا ہے، آپ نے فرمایا : \" چلتے رہو، یہ جُمدان ہے۔ مفردون 0لوگوں سے الگ ہو کر تنہا ہو جانے والے ) بازی لے گئے۔ \" لوگوں نے پوچھا : اللہ کے رسول! مفردون سے کیا مراد ہے؟ فرمایا : \" کثرت سے اللہ کو یاد کرنے والے ( مرد ) اور اللہ کو یاد کرنے والی ( عورتیں۔)\"", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه مسلم (٢٦٧٦)", referenceEn: "Sahih Muslim 2676", categoryAr: "الذكر", categoryEn: "Remembrance", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "176", titleAr: "سبحان الله وبحمده مئة مرة", titleEn: "Glory Be to Allah, a Hundred Times", titleTr: "Yüz Kere Sübhanallahi ve Bihamdihi", titleUr: "سو بار سبحان اللہ وبحمدہ", textAr: "أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ «مَنْ قَالَ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ. فِي يَوْمٍ مِائَةَ مَرَّةٍ حُطَّتْ خَطَايَاهُ، وَإِنْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ».", translationEn: "Allah's Messenger (ﷺ) said, \"Whoever says, 'Subhan Allah wa bihamdihi,' one hundred times a day, will be forgiven all his sins even if they were as much as the foam of the sea.\"", translationTr: "Resulullah Sallallahu Aleyhi ve Sellem şöyle buyurmuştur: \"Günde yüz defa tesbih edenlerin deniz köpüğü kadar bile olsa günahları bağışlanır.\"", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ”جس نے «سبحان الله وبحمده‏.‏» دن میں سو مرتبہ کہا، اس کے گناہ معاف کر دئیے جاتے ہیں، خواہ سمندر کی جھاگ کے برابر ہی کیوں نہ ہوں۔“", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (٦٤٠٥)", referenceEn: "Sahih al-Bukhari 6405", categoryAr: "الذكر", categoryEn: "Remembrance", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "177", titleAr: "ربنا آتنا في الدنيا حسنة", titleEn: "Our Lord, Give Us Good in This World", titleTr: "Rabbimiz, Bize Dünyada İyilik Ver", titleUr: "اے ہمارے رب، ہمیں دنیا میں بھلائی دے", textAr: "كَانَ أَكْثَرُ دُعَاءِ النَّبِيِّ صلى الله عليه وسلم «اللَّهُمَّ رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً، وَفِي الآخِرَةِ حَسَنَةً، وَقِنَا عَذَابَ النَّارِ».", translationEn: "The most frequent invocation of The Prophet (ﷺ) was: \"O Allah! Give to us in the world that which is good and in the Hereafter that which is good, and save us from the torment of the Fire.\"", translationTr: "Resulullah Sallallahu Aleyhi ve Sellem'in en fazla yaptığı dua şudur: Rabbena atina fi'd-dünya haseneten ve fi'l-Ahireti haseneten ve kina azabennar = \"Rabbimiz bize dünyada ve ahirette güzellikler ver ve bizi cehennem azabından koru\".", translationUr: "نبی کریم صلی اللہ علیہ وسلم کی اکثر یہ دعا ہوا کرتی تھی «اللهم ربنا آتنا في الدنيا حسنة،‏‏‏‏ ‏‏‏‏ وفي الآخرة حسنة،‏‏‏‏ ‏‏‏‏ وقنا عذاب النار ‏ ‏‏.‏» ”اے اللہ! ہمیں دنیا میں بھلائی ( «حسنة» ) عطا کر اور آخرت میں بھلائی عطا کر اور ہمیں دوزخ سے بچا۔“", narratorAr: "عن أنس بن مالك رضي الله عنه", narratorEn: "Narrated by Anas ibn Malik (RA)", referenceAr: "رواه البخاري (٦٣٨٩)", referenceEn: "Sahih al-Bukhari 6389", categoryAr: "الدعاء", categoryEn: "Supplication", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "178", titleAr: "الشديد من يملك نفسه عند الغضب", titleEn: "Strength Is Mastering Anger", titleTr: "Güçlü, Öfkesine Hâkim Olandır", titleUr: "طاقتور وہ ہے جو غصے پر قابو رکھے", textAr: "أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ «لَيْسَ الشَّدِيدُ بِالصُّرَعَةِ، إِنَّمَا الشَّدِيدُ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ».", translationEn: "Allah's Messenger (ﷺ) said, \"The strong is not the one who overcomes the people by his strength, but the strong is the one who controls himself while in anger.\"", translationTr: "Resulullah Sallallahu Aleyhi ve Sellem şöyle buyurdu: Güçlü, kuvvetli kişi rakiplerinin sırtını yerine getiren kişi değildir. Asıl güçlü kuvvetli kişi, öfkelendiği vakit nefsine hakim olabilendir.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ”پہلوان وہ نہیں ہے جو کشتی لڑنے میں غالب ہو جائے بلکہ اصلی پہلوان تو وہ ہے جو غصہ کی حالت میں اپنے آپ پر قابو پائے بے قابو نہ ہو جائے۔“", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (٦١١٤)", referenceEn: "Sahih al-Bukhari 6114", categoryAr: "حسن الخلق", categoryEn: "Good Character", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "179", titleAr: "إن الله جميل يحب الجمال", titleEn: "Allah Is Beautiful and Loves Beauty", titleTr: "Allah Güzeldir, Güzeli Sever", titleUr: "اللہ جمیل ہے اور جمال کو پسند کرتا ہے", textAr: "عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ «لاَ يَدْخُلُ الْجَنَّةَ مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ ذَرَّةٍ مِنْ كِبْرٍ». قَالَ رَجُلٌ إِنَّ الرَّجُلَ يُحِبُّ أَنْ يَكُونَ ثَوْبُهُ حَسَنًا وَنَعْلُهُ حَسَنَةً. قَالَ «إِنَّ اللَّهَ جَمِيلٌ يُحِبُّ الْجَمَالَ الْكِبْرُ بَطَرُ الْحَقِّ وَغَمْطُ النَّاسِ».", translationEn: "It Is narrated on the authority of Abdullah b. Mas'ud that the Messenger of Allah (ﷺ), observed: He who has in his heart the weight of a mustard seed of pride shall not enter Paradise. A person (amongst his hearers) said: Verily a person loves that his dress should be fine, and his shoes should be fine. He (the Holy Prophet) remarked: Verily, Allah is Graceful and He loves Grace. Pride is disdaining the truth (out of self-conceit) and contempt for the people.", translationTr: "Nebi (Sallallahu aleyhi ve Sellem)'den şöyle buyurduğunu nakletti: \"Kalbinde zerre ağırlığınca kibir bulunan bir kimse cennete girmez. \" Bir adam: Kişi elbisesinin güzel, ayakkabısının güzel olmasını sever(se) durumu nedir, dedi. Allah Resulü (Sallallahu aleyhi ve Sellem): \"Şüphesiz Allah güzeldir, güzeli sever. Kibir ise hakkı kabul etmemek ve insanları küçümsemektir\" buyurdu.", translationUr: "انہوں نے نبی کریمﷺ سے روایت کی، آپ نے فرمایا : ’’ جس کے دل میں ذرہ برابر تکبر ہو گا، وہ جنت میں داخل نہ ہو گا۔ ‘‘ ایک آدمی نے کہا : انسان چاہتا ہے کہ اس کے کپڑے اچھے ہوں اور اس کے جوتے اچھے ہوں۔ آپ نے فرمایا : ’’ اللہ خود جمیل ہے، وہ جمال کو پسند فرماتا ہے۔ تکبر، حق کو قبول نہ کرنا اورلوگوں کو حقیر سمجھنا ہے۔‘‘", narratorAr: "عن عبد الله بن مسعود رضي الله عنه", narratorEn: "Narrated by Abdullah ibn Mas'ud (RA)", referenceAr: "رواه مسلم (٩١)", referenceEn: "Sahih Muslim 91", categoryAr: "حسن الخلق", categoryEn: "Good Character", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "180", titleAr: "انصر أخاك ظالمًا أو مظلومًا", titleEn: "Help Your Brother, Wronging or Wronged", titleTr: "Zalim de Olsa Mazlum da Olsa Kardeşine Yardım Et", titleUr: "اپنے بھائی کی مدد کرو، ظالم ہو یا مظلوم", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «انْصُرْ أَخَاكَ ظَالِمًا أَوْ مَظْلُومًا». قَالُوا يَا رَسُولَ اللَّهِ هَذَا نَنْصُرُهُ مَظْلُومًا، فَكَيْفَ نَنْصُرُهُ ظَالِمًا قَالَ «تَأْخُذُ فَوْقَ يَدَيْهِ».", translationEn: "Allah's Messenger (ﷺ) said, \"Help your brother, whether he is an oppressor or he is an oppressed one. People asked, \"O Allah's Messenger (ﷺ)! It is all right to help him if he is oppressed, but how should we help him if he is an oppressor?\" The Prophet (ﷺ) said, \"By preventing him from oppressing others.", translationTr: "Allah Resulü Sallallahu Aleyhi ve Sellem şöyle buyurdular: \"İster haksızlığa uğrasın, ister haksızlık etsin, din kardeşinize yardım ediniz\" \"Ey Allah'ın Resulü! Haklı olana yardım etmeyi anlıyoruz da haksız olana nasıl yardım edelim!\" diye sordular. Nebi Sallallahu Aleyhi ve Sellem de \"Ellerini tutarsınız\" buyurdu.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، اپنے بھائی کی مدد کرو خواہ وہ ظالم ہو یا مظلوم۔ صحابہ نے عرض کیا، یا رسول اللہ! ہم مظلوم کی تو مدد کر سکتے ہیں۔ لیکن ظالم کی مدد کس طرح کریں؟ آپ صلی اللہ علیہ وسلم نے فرمایا کہ ظلم سے اس کا ہاتھ پکڑ لو ( یہی اس کی مدد ہے )۔", narratorAr: "عن أنس بن مالك رضي الله عنه", narratorEn: "Narrated by Anas ibn Malik (RA)", referenceAr: "رواه البخاري (٢٤٤٤)", referenceEn: "Sahih al-Bukhari 2444", categoryAr: "الجار والمجتمع", categoryEn: "Neighbours & Society", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "181", titleAr: "من غشّنا فليس منا", titleEn: "Whoever Cheats Us Is Not of Us", titleTr: "Bizi Aldatan Bizden Değildir", titleUr: "جو دھوکا دے وہ ہم میں سے نہیں", textAr: "أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ «مَنْ حَمَلَ عَلَيْنَا السِّلاَحَ فَلَيْسَ مِنَّا وَمَنْ غَشَّنَا فَلَيْسَ مِنَّا».", translationEn: "It is narrated on the authority of Abu Huraira that the Messenger of Allah (ﷺ) observed: He who took up arms against us is not of us and he who acted dishonestly towards us is not of us.", translationTr: "Resulullah (Sallallahu aleyhi ve Sellem): \"Bize karşı silah taşıyan bizden değildir, bizi aldatan bizden değildir\" buyurdu.", translationUr: "رسول اللہ ﷺ نے فرمایا : ’’ جس نے ہمارے خلاف ہتھیار اٹھایا، وہ ہم میں سے نہیں اور جس نے ہمیں دھوکا دیا، وہ ہم میں سے نہیں۔‘‘", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه مسلم (١٠١)", referenceEn: "Sahih Muslim 101", categoryAr: "الصدق", categoryEn: "Truthfulness", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "182", titleAr: "غصن الشوك على الطريق", titleEn: "The Thorn Branch on the Road", titleTr: "Yoldaki Dikenli Dal", titleUr: "راستے کی کانٹے دار ٹہنی", textAr: "أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ «بَيْنَمَا رَجُلٌ يَمْشِي بِطَرِيقٍ، وَجَدَ غُصْنَ شَوْكٍ فَأَخَذَهُ، فَشَكَرَ اللَّهُ لَهُ، فَغَفَرَ لَهُ».", translationEn: "Allah's Messenger (ﷺ) said, \"While a man was on the way, he found a thorny branch of a tree there on the way and removed it. Allah thanked him for that deed and forgave him.\"", translationTr: "Allah Resulü Sallallahu Aleyhi ve Sellem şöyle buyurmuştur: \"Bir adam yolda yürürken bir diken dalı bulmuştu. Onu aldı ve Allah onun bu davranışına memnun olup onu bağışladı.\"", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، ایک شخص راستے پر چل رہا تھا کہ اس نے وہاں کانٹے دار ڈالی دیکھی۔ اس نے اسے اٹھا لیا تو اللہ تعالیٰ نے اس کا یہ عمل قبول کیا اور اس کی مغفرت کر دی۔", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (٢٤٧٢)", referenceEn: "Sahih al-Bukhari 2472", categoryAr: "الجار والمجتمع", categoryEn: "Neighbours & Society", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "183", titleAr: "من أكبر الكبائر", titleEn: "Among the Gravest Sins", titleTr: "Büyük Günahların En Büyüklerinden", titleUr: "بڑے گناہوں میں سے", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «إِنَّ مِنْ أَكْبَرِ الْكَبَائِرِ أَنْ يَلْعَنَ الرَّجُلُ وَالِدَيْهِ». قِيلَ يَا رَسُولَ اللَّهِ وَكَيْفَ يَلْعَنُ الرَّجُلُ وَالِدَيْهِ قَالَ «يَسُبُّ الرَّجُلُ أَبَا الرَّجُلِ، فَيَسُبُّ أَبَاهُ، وَيَسُبُّ أَمَّهُ».", translationEn: "Allah's Messenger (ﷺ) said. \"It is one of the greatest sins that a man should curse his parents.\" It was asked (by the people), \"O Allah's Messenger (ﷺ)! How does a man curse his parents?\" The Prophet (ﷺ) said, \"'The man abuses the father of another man and the latter abuses the father of the former and abuses his mother.\"", translationTr: "Resulullah Sallallahu Aleyhi ve Sellem: Şüphesiz büyük günahların en büyüklerinden birisi de kişinin anne-babasına lanet etmesidir, buyurdu. Ey Allah'ın Rasulü, kişi nasıl anne-babasına lanet eder, diye sorulunca, o: Başka bir adamın babasına söver, o da onun babasına söver, başka birisinin annesine söver, o da onun annesine söver, buyurdu.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: یقیناً سب سے بڑے گناہوں میں سے یہ ہے کہ کوئی شخص اپنے والدین پر لعنت بھیجے۔ پوچھا گیا: یا رسول اللہ! کوئی شخص اپنے ہی والدین پر کیسے لعنت بھیجے گا؟ نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ وہ شخص دوسرے کے باپ کو برا بھلا کہے گا تو دوسرا بھی اس کے باپ کو اور اس کی ماں کو برا بھلا کہے گا۔", narratorAr: "عن عبد الله بن عمرو رضي الله عنهما", narratorEn: "Narrated by Abdullah ibn Amr (RA)", referenceAr: "رواه البخاري (٥٩٧٣)", referenceEn: "Sahih al-Bukhari 5973", categoryAr: "الوالدان وصلة الرحم", categoryEn: "Family & Parents", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "184", titleAr: "لا صلاة بغير وضوء", titleEn: "No Prayer Without Ablution", titleTr: "Abdestsiz Namaz Olmaz", titleUr: "وضو کے بغیر نماز نہیں", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «لاَ تُقْبَلُ صَلاَةُ مَنْ أَحْدَثَ حَتَّى يَتَوَضَّأَ».", translationEn: "Allah's Messenger (ﷺ) said, \"The prayer of a person who does Hadath (passes urine, stool or wind) is not accepted till he performs the ablution.\"", translationTr: "Resulullâh sallallahu aleyhi ve sellem: \"Kendisinde hades vâkı` olan kimsenin namazı (o kimse) abdest almadıkça kabul olunmaz.\" buyurdu.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ جو شخص حدث کرے اس کی نماز قبول نہیں ہوتی جب تک کہ وہ ( دوبارہ ) وضو نہ کر لے۔", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (١٣٥)", referenceEn: "Sahih al-Bukhari 135", categoryAr: "الطهارة", categoryEn: "Purity", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "185", titleAr: "الدنيا سجن المؤمن", titleEn: "This World Is the Believer's Prison", titleTr: "Dünya Müminin Zindanıdır", titleUr: "دنیا مومن کا قید خانہ ہے", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «الدُّنْيَا سِجْنُ الْمُؤْمِنِ وَجَنَّةُ الْكَافِرِ».", translationEn: "Abu Huraira reported Allah's Messenger (ﷺ) as saying: The world is a prison-house for a believer and Paradise for a non-believer.", translationTr: "Resûlullah (Sallallahu Aleyhi ve Sellem): «Dünya mü'minîn zindanı, kâfir'în cennetidir.» buyurdular.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" دنیا مومن کا قید خانہ اور کافر کی جنت ہے۔\"", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه مسلم (٢٩٥٦)", referenceEn: "Sahih Muslim 2956", categoryAr: "الآخرة", categoryEn: "The Hereafter", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "186", titleAr: "حُفّت الجنة بالمكاره", titleEn: "Paradise Is Surrounded by Hardships", titleTr: "Cennet Zorluklarla Kuşatılmıştır", titleUr: "جنت ناگواریوں سے گھری ہے", textAr: "قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «حُفَّتِ الْجَنَّةُ بِالْمَكَارِهِ وَحُفَّتِ النَّارُ بِالشَّهَوَاتِ».", translationEn: "Anas b. Malik reported: The Paradise is surrounded by hardships and the Hell-Fire is surrounded by temptations.", translationTr: "Resûlullah (Sallallahu Aleyhi ve Sellem): «Cennet hoş'a gitmeyen şeylerle sarılmış; cehennem de şehvetlerle sarılmıştır.»; buyurdular.", translationUr: "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جنت گراں امور میں گھری ہوئی ہے اور دوزخ خواہشات نفسانی میں گھری ہوئی ہے۔\"", narratorAr: "عن أنس بن مالك رضي الله عنه", narratorEn: "Narrated by Anas ibn Malik (RA)", referenceAr: "رواه مسلم (٢٨٢٢)", referenceEn: "Sahih Muslim 2822", categoryAr: "الآخرة", categoryEn: "The Hereafter", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
        OfflineDailyHadith(id: "187", titleAr: "من رغب عن سنتي", titleEn: "Turning Away from My Way", titleTr: "Sünnetimden Yüz Çeviren", titleUr: "جو میری سنت سے منہ موڑے", textAr: "جَاءَ ثَلاَثَةُ رَهْطٍ إِلَى بُيُوتِ أَزْوَاجِ النَّبِيِّ صلى الله عليه وسلم يَسْأَلُونَ عَنْ عِبَادَةِ النَّبِيِّ صلى الله عليه وسلم فَلَمَّا أُخْبِرُوا كَأَنَّهُمْ تَقَالُّوهَا فَقَالُوا وَأَيْنَ نَحْنُ مِنَ النَّبِيِّ صلى الله عليه وسلم قَدْ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَمَا تَأَخَّرَ. قَالَ أَحَدُهُمْ أَمَّا أَنَا فَإِنِّي أُصَلِّي اللَّيْلَ أَبَدًا. وَقَالَ آخَرُ أَنَا أَصُومُ الدَّهْرَ وَلاَ أُفْطِرُ. وَقَالَ آخَرُ أَنَا أَعْتَزِلُ النِّسَاءَ فَلاَ أَتَزَوَّجُ أَبَدًا. فَجَاءَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَقَالَ «أَنْتُمُ الَّذِينَ قُلْتُمْ كَذَا وَكَذَا أَمَا وَاللَّهِ إِنِّي لأَخْشَاكُمْ لِلَّهِ وَأَتْقَاكُمْ لَهُ، لَكِنِّي أَصُومُ وَأُفْطِرُ، وَأُصَلِّي وَأَرْقُدُ وَأَتَزَوَّجُ النِّسَاءَ، فَمَنْ رَغِبَ عَنْ سُنَّتِي فَلَيْسَ مِنِّي».", translationEn: "A group of three men came to the houses of the wives of the Prophet (ﷺ) asking how the Prophet (ﷺ) worshipped (Allah), and when they were informed about that, they considered their worship insufficient and said, \"Where are we from the Prophet (ﷺ) as his past and future sins have been forgiven.\" Then one of them said, \"I will offer the prayer throughout the night forever.\" The other said, \"I will fast throughout the year and will not break my fast.\" The third said, \"I will keep away from the women and will not marry forever.\" Allah's Messenger (ﷺ) came to them and said, \"Are you the same people who said so-and-so? By Allah, I am more submissive to Allah and more afraid of Him than you; yet I fast and break my fast, I do sleep and I also marry women. So he who does not follow my tradition in religion, is not from me (not one of my followers)\"", translationTr: "Nebi Sallallahu Aleyhi ve Sellem'in hanımlarının evlerine gelerek Nebi Sallallahu Aleyhi ve Sellem'in ibadetine dair soru sordular. Onlara haber verilince, onu azımsar gibi oldular ve şöyle dediler: Biz nerede, Nebi Sallallahu Aleyhi ve Sellem nerde? Allah onun geçmiş ve gelecek günahlarını bağışlamış bulunuyor. Onlardan birisi: Ben her zaman geceleyin namaz kılacağım, dedi. Diğeri: Ben de oruç açmamak üzere sene boyunca oruç tutacağım, dedi. Üçüncüleri: Ben de kadınlardan uzak kalacak ve ebediyyen evlenmeyeceğim,dedi. Sonra Rasulullah Sallallahu Aleyhi ve Sellem gelerek şöyle buyurdu: \"Şöyle şöyle diyenler, sizler miydiniz? Bana gelince, Allah'a yemin ederim, şüphesiz ben aranızda Allah'tan en çok korkan ve ona karşı en takvalı olanınızım. Bununla birlikte oruç tuttuğum da olur, tutmadığım da olur. (Geceleyin) kimi zaman namaz kılarım, kimi zaman uyurum, kadınlarla da evlenirim. Benim sünnetimden yüz çeviren, benden değildir.\"", translationUr: "نبی کریم صلی اللہ علیہ وسلم کی ازواج مطہرات کے گھروں کی طرف آپ کی عبادت کے متعلق پوچھنے آئے، جب انہیں نبی کریم صلی اللہ علیہ وسلم کا عمل بتایا گیا تو جیسے انہوں نے اسے کم سمجھا اور کہا کہ ہمارا نبی کریم صلی اللہ علیہ وسلم سے کیا مقابلہ! آپ کی تو تمام اگلی پچھلی لغزشیں معاف کر دی گئی ہیں۔ ان میں سے ایک نے کہا کہ آج سے میں ہمیشہ رات بھر نماز پڑھا کروں گا۔ دوسرے نے کہا کہ میں ہمیشہ روزے سے رہوں گا اور کبھی ناغہ نہیں ہونے دوں گا۔ تیسرے نے کہا کہ میں عورتوں سے جدائی اختیار کر لوں گا اور کبھی نکاح نہیں کروں گا۔ پھر نبی کریم صلی اللہ علیہ وسلم تشریف لائے اور ان سے پوچھا کیا تم نے ہی یہ باتیں کہی ہیں؟ سن لو! اللہ تعالیٰ کی قسم! اللہ رب العالمین سے میں تم سب سے زیادہ ڈرنے والا ہوں۔ میں تم میں سب سے زیادہ پرہیزگار ہوں لیکن میں اگر روزے رکھتا ہوں تو افطار بھی کرتا ہوں۔ نماز پڑھتا ہوں ( رات میں ) اور سوتا بھی ہوں اور میں عورتوں سے نکاح کرتا ہوں۔ «فمن رغب عن سنتي فليس مني» میرے طریقے سے جس نے بے رغبتی کی وہ مجھ میں سے نہیں ہے۔", narratorAr: "عن أنس بن مالك رضي الله عنه", narratorEn: "Narrated by Anas ibn Malik (RA)", referenceAr: "رواه البخاري (٥٠٦٣)", referenceEn: "Sahih al-Bukhari 5063", categoryAr: "اتباع السنة", categoryEn: "Following the Sunnah", explanationAr: "", explanationEn: "", explanationTr: "", explanationUr: ""),
    ]

    public static func verseForDayIndex(_ dayIndex: Int) -> OfflineDailyVerse {
        let idx = ((dayIndex % verses.count) + verses.count) % verses.count
        return verses[idx]
    }

    public static func hadithForDayIndex(_ dayIndex: Int) -> OfflineDailyHadith {
        let idx = ((dayIndex % hadiths.count) + hadiths.count) % hadiths.count
        return hadiths[idx]
    }
}
